import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ScriptMetrics {
  wordCount: number;
  estimatedDurationMinutes: number;
  estimatedClipCount: number;
}

export interface GeneratedClip {
  id: string;
  scriptLine: string;
  narrativeContext: string;
  visualPrompt: string;
  clipNumber: number;
}

export interface StyleSettings {
  visualStyle: string;
  lighting: string;
  mood: string;
}

export enum GenerationStatus {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

export const VISUAL_STYLES = [
  "Cinematic Realism",
  "3D Render (Unreal Engine 5)",
  "Anime / Cel-Shaded",
  "Analog Film (16mm Grain)",
  "Cyberpunk / Neon Noir",
  "Minimalist Commercial",
  "Documentary Style"
];

export const LIGHTING_OPTIONS = [
  "Natural / Golden Hour",
  "Dramatic / Chiaroscuro",
  "Studio Softbox",
  "Neon / Artificial",
  "Overcast / Diffused",
  "Dark / Moody"
];

export const MOOD_OPTIONS = [
  "Professional & Trustworthy",
  "Intense & Fast-Paced",
  "Emotional & Heartfelt",
  "Mysterious & Suspenseful",
  "Upbeat & Energetic",
  "Calm & Serene"
];

export const DEFAULT_SETTINGS = {
  visualStyle: "Cinematic Realism",
  lighting: "Natural / Golden Hour",
  mood: "Professional & Trustworthy"
};

import { GoogleGenAI, Type } from "@google/genai";
import { StyleSettings, GeneratedClip } from "../types";

const processScript = async (script: string, settings: StyleSettings): Promise<GeneratedClip[]> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `You are an expert video prompt engineer for high-end AI video generation (Veo 3.1). 

  CORE RESPONSIBILITIES:
  1. Analyze the provided video script.
  2. Split the script into chunks of approximately 26-27 words (roughly 8 seconds of speech).
  3. For each chunk, generate a specific video generation prompt.

  CRITICAL SAFETY & CONTENT PROTOCOLS:
  - STRICTLY FOLLOW Veo 3.1 safety protocols.
  - NO violence, gore, or blood. Convert violence to "aftermath", "tension", or "implication".
  - NO morphing or body horror.
  - NO direct touching, hugging, or kissing. Convert intimacy to "reaching out", "standing side-by-side", "intense eye contact", or "shared focus".

  GENERATION RULES:
  - Extract the 'scriptLine' EXACTLY word-for-word from the source text for that chunk.
  - 'narrativeContext': 40-80 words explaining the story beat.
  - 'visualPrompt': 80-150 words. MUST include: Visual Description, MOTION details, CAMERA MOVEMENT, and character ATTIRE.
  - Apply the requested Visual Style: "${settings.visualStyle}", Lighting: "${settings.lighting}", and Mood: "${settings.mood}".
  `;

  const prompt = `Here is the script to process:
  """
  ${script}
  """

  Generate the video clips now.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", // Efficient for text processing
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              scriptLine: { type: Type.STRING, description: "The exact text from the script for this segment." },
              narrativeContext: { type: Type.STRING, description: "40-80 words explaining the action/story context." },
              visualPrompt: { type: Type.STRING, description: "80-150 words describing visual, motion, camera, and attire." }
            },
            required: ["scriptLine", "narrativeContext", "visualPrompt"]
          }
        }
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) {
      throw new Error("Empty response from AI");
    }

    const rawClips = JSON.parse(jsonStr);

    // Map to internal structure with IDs
    return rawClips.map((clip: any, index: number) => ({
      id: crypto.randomUUID(),
      clipNumber: index + 1,
      scriptLine: clip.scriptLine,
      narrativeContext: clip.narrativeContext,
      visualPrompt: clip.visualPrompt
    }));

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const geminiService = {
  processScript
};

