import React, { useState } from 'react';
import { GeneratedClip } from '../types';
import { Copy, Check, Video, FileText, Camera } from 'lucide-react';

interface PromptCardProps {
  clip: GeneratedClip;
}

export const PromptCard: React.FC<PromptCardProps> = ({ clip }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(clip.visualPrompt);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="bg-[#1a202c] border border-gray-700 rounded-xl overflow-hidden hover:border-blue-500/50 transition-colors duration-300">
      {/* Header */}
      <div className="bg-[#2d3748] px-4 py-2 flex justify-between items-center border-b border-gray-700">
        <span className="text-xs font-bold bg-blue-900 text-blue-200 px-2 py-1 rounded">
          CLIP {String(clip.clipNumber).padStart(2, '0')}
        </span>
        <div className="text-xs text-gray-400 font-mono">~8.0s</div>
      </div>

      <div className="p-5 space-y-5">

        {/* Script Line */}
        <div>
          <div className="flex items-center gap-2 mb-1 text-gray-400 text-xs font-semibold uppercase tracking-wider">
            <FileText size={14} /> Script Line
          </div>
          <div className="text-lg font-serif text-white italic border-l-2 border-blue-500 pl-3 py-1">
            "{clip.scriptLine}"
          </div>
        </div>

        {/* Narrative Context */}
        <div>
          <div className="flex items-center gap-2 mb-1 text-gray-400 text-xs font-semibold uppercase tracking-wider">
            <Video size={14} /> Context
          </div>
          <p className="text-gray-300 text-sm leading-relaxed">
            {clip.narrativeContext}
          </p>
        </div>

        {/* The Prompt */}
        <div className="bg-[#0e1117] rounded-lg border border-gray-800 p-4 relative group">
          <div className="flex items-center gap-2 mb-2 text-purple-400 text-xs font-semibold uppercase tracking-wider">
            <Camera size={14} /> AI Video Prompt
          </div>
          <p className="text-sm text-gray-200 font-mono leading-relaxed pb-6">
            {clip.visualPrompt}
          </p>

          <button
            onClick={handleCopy}
            className="absolute bottom-2 right-2 p-2 rounded-md bg-gray-800 hover:bg-blue-600 text-gray-400 hover:text-white transition-all border border-gray-700 hover:border-blue-500"
            title="Copy Prompt"
          >
            {copied ? <Check size={16} /> : <Copy size={16} />}
          </button>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { StyleEngine } from './components/StyleEngine';
import { MetricsDisplay } from './components/MetricsDisplay';
import { PromptCard } from './components/PromptCard';
import { geminiService } from './services/geminiService';
import { StyleSettings, ScriptMetrics, GeneratedClip, GenerationStatus } from './types';
import { DEFAULT_SETTINGS } from './constants';
import { Sparkles, Play, AlertCircle } from 'lucide-react';

const App: React.FC = () => {
  const [script, setScript] = useState('');
  const [settings, setSettings] = useState<StyleSettings>(DEFAULT_SETTINGS);
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [clips, setClips] = useState<GeneratedClip[]>([]);

  const [metrics, setMetrics] = useState<ScriptMetrics>({
    wordCount: 0,
    estimatedDurationMinutes: 0,
    estimatedClipCount: 0
  });

  // Calculate metrics on script change
  useEffect(() => {
    const trimmed = script.trim();
    if (!trimmed) {
      setMetrics({ wordCount: 0, estimatedDurationMinutes: 0, estimatedClipCount: 0 });
      return;
    }

    const words = trimmed.split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;
    // Standard speaking rate ~150-200 wpm. Using 200 for calculation per user request.
    const durationMins = wordCount / 200; 
    // 8 seconds per clip
    const estClips = Math.ceil((durationMins * 60) / 8);

    setMetrics({
      wordCount,
      estimatedDurationMinutes: durationMins,
      estimatedClipCount: estClips
    });
  }, [script]);

  const handleGenerate = useCallback(async () => {
    if (!script.trim()) return;

    setStatus(GenerationStatus.LOADING);
    setErrorMsg(null);
    setClips([]);

    try {
      const generatedClips = await geminiService.processScript(script, settings);
      setClips(generatedClips);
      setStatus(GenerationStatus.SUCCESS);
    } catch (error: any) {
      setStatus(GenerationStatus.ERROR);
      setErrorMsg(error.message || "An unexpected error occurred.");
    }
  }, [script, settings]);

  return (
    <div className="min-h-screen bg-[#0e1117] text-gray-200 pb-20">
      {/* Navbar / Header */}
      <header className="bg-[#0f172a]/50 backdrop-blur-md border-b border-gray-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-900/50">
              <Sparkles className="text-white w-6 h-6" />
            </div>
            <h1 className="text-2xl font-bold text-white tracking-tight">
              Video Script to <span className="text-blue-500">Prompt Elite</span>
            </h1>
          </div>
          <div className="text-sm text-gray-500 hidden sm:block font-medium">
            Powered by Gemini 2.5
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-10 space-y-10">

        {/* Top Controls Section */}
        <section>
          <StyleEngine 
            settings={settings} 
            setSettings={setSettings} 
            disabled={status === GenerationStatus.LOADING}
          />
        </section>

        {/* Input Section */}
        <section className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          <div className="lg:col-span-1 space-y-4">
            <div className="sticky top-28">
              <div className="flex justify-between items-center mb-2">
                <label className="text-sm font-bold text-gray-300 uppercase tracking-wider">Input Script</label>
                <button 
                  onClick={() => setScript('')}
                  className="text-xs text-red-400 hover:text-red-300 transition-colors"
                >
                  Clear
                </button>
              </div>

              <div className="relative">
                <textarea
                  value={script}
                  onChange={(e) => setScript(e.target.value)}
                  placeholder="Paste your video script here..."
                  className="w-full h-[400px] bg-[#1a202c] border border-gray-700 rounded-xl p-4 text-gray-200 placeholder-gray-600 focus:ring-2 focus:ring-blue-600 focus:border-transparent transition-all resize-none font-mono text-sm leading-relaxed"
                  disabled={status === GenerationStatus.LOADING}
                />

                {/* Generate Button Overlay */}
                <div className="absolute bottom-4 right-4 left-4">
                  <button
                    onClick={handleGenerate}
                    disabled={status === GenerationStatus.LOADING || !script.trim()}
                    className={`w-full py-4 rounded-lg flex items-center justify-center gap-2 font-bold text-lg shadow-xl transition-all transform active:scale-95 ${
                      status === GenerationStatus.LOADING || !script.trim()
                        ? 'bg-gray-700 text-gray-500 cursor-not-allowed'
                        : 'bg-[#2563eb] hover:bg-blue-500 text-white shadow-blue-900/50 hover:shadow-blue-700/50'
                    }`}
                  >
                    {status === GenerationStatus.LOADING ? (
                      <>
                        <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        Processing...
                      </>
                    ) : (
                      <>
                        <Play fill="currentColor" size={20} />
                        GENERATE PROMPTS
                      </>
                    )}
                  </button>
                </div>
              </div>

              <MetricsDisplay metrics={metrics} />
            </div>
          </div>

          {/* Results Section */}
          <div className="lg:col-span-2 space-y-6">
             <div className="flex justify-between items-center border-b border-gray-800 pb-4">
                <h2 className="text-xl font-bold text-white">Generated Output</h2>
                {clips.length > 0 && (
                   <span className="bg-green-900/30 text-green-400 px-3 py-1 rounded-full text-xs font-semibold border border-green-800">
                     {clips.length} Clips Ready
                   </span>
                )}
             </div>

             {status === GenerationStatus.ERROR && (
               <div className="bg-red-900/20 border border-red-800 text-red-200 p-4 rounded-lg flex items-center gap-3">
                 <AlertCircle className="shrink-0" />
                 <p>{errorMsg}</p>
               </div>
             )}

             {status === GenerationStatus.IDLE && clips.length === 0 && (
               <div className="h-[400px] flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl">
                 <Video size={48} className="mb-4 opacity-50" />
                 <p className="text-lg">Ready to generate elites prompts.</p>
                 <p className="text-sm">Enter a script and configure your style to begin.</p>
               </div>
             )}

            <div className="grid grid-cols-1 gap-6">
              {clips.map((clip) => (
                <PromptCard key={clip.id} clip={clip} />
              ))}
            </div>
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

