                    disabled={status === GenerationStatus.LOADING || !script.trim()}
                    className={`w-full py-4 rounded-lg flex items-center justify-center gap-2 font-bold text-lg shadow-xl transition-all transform active:scale-95 ${
                      status === GenerationStatus.LOADING || !script.trim()
                        ? 'bg-gray-700 text-gray-500 cursor-not-allowed'
                        : 'bg-[#2563eb] hover:bg-blue-500 text-white shadow-blue-900/50 hover:shadow-blue-700/50'
                    }`}
                  >
                    {status === GenerationStatus.LOADING ? (
                      <>
                        <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        Processing...
                      </>
                    ) : (
                      <>
                        <Play fill="currentColor" size={20} />
                        GENERATE PROMPTS
                      </>
                    )}
                  </button>
                </div>
              </div>

              <MetricsDisplay metrics={metrics} />
            </div>
          </div>

          {/* Results Section */}
          <div className="lg:col-span-2 space-y-6">
             <div className="flex justify-between items-center border-b border-gray-800 pb-4">
                <h2 className="text-xl font-bold text-white">Generated Output</h2>
                {clips.length > 0 && (
                   <span className="bg-green-900/30 text-green-400 px-3 py-1 rounded-full text-xs font-semibold border border-green-800">
                     {clips.length} Clips Ready
                   </span>
                )}
             </div>

             {status === GenerationStatus.ERROR && (
               <div className="bg-red-900/20 border border-red-800 text-red-200 p-4 rounded-lg flex items-center gap-3">
                 <AlertCircle className="shrink-0" />
                 <p>{errorMsg}</p>
               </div>
             )}

             {status === GenerationStatus.IDLE && clips.length === 0 && (
               <div className="h-[400px] flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl">
                 <Video size={48} className="mb-4 opacity-50" />
                 <p className="text-lg">Ready to generate elites prompts.</p>
                 <p className="text-sm">Enter a script and configure your style to begin.</p>
               </div>
             )}

            <div className="grid grid-cols-1 gap-6">
              {clips.map((clip) => (
                <PromptCard key={clip.id} clip={clip} />
              ))}
            </div>
          </div>
        </section>
      </main>
    </div>
  );
};

