import { GoogleGenAI, Type } from "@google/genai";
import { StyleSettings, GeneratedClip, ClipDuration } from "../types";

const getAIClient = () => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

// Analyze video reference to extract style
const analyzeVideoStyle = async (videoBase64: string, mimeType: string): Promise<Partial<StyleSettings>> => {
  const ai = getAIClient();

  const systemInstruction = `You are an expert film director and cinematographer. 
  Your task is to analyze the provided video clip and extract its stylistic attributes into a structured format.
  Identify the visual style, color palette (approximate hex codes), mood, lighting, camera techniques, and keywords.`;

  const prompt = "Analyze this video and return the style settings.";

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType, data: videoBase64 } },
          { text: prompt }
        ]
      },
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            visualStyle: { type: Type.STRING, enum: ["Cinematic Photorealistic", "Modern Corporate", "Documentary", "3D Render", "Anime", "Vintage Film"] },
            colorPalette: {
              type: Type.OBJECT,
              properties: {
                primary: { type: Type.STRING, description: "Hex code" },
                secondary: { type: Type.STRING, description: "Hex code" },
                accent: { type: Type.STRING, description: "Hex code" }
              }
            },
            mood: { type: Type.STRING, enum: ["Professional", "Inspiring", "Dramatic", "Intense", "Melancholic"] },
            lighting: { type: Type.STRING, enum: ["Soft natural", "Dramatic high-contrast", "Golden hour", "Neon/Cyberpunk", "Studio Clean"] },
            cameraStyle: { type: Type.STRING, enum: ["Wide shots", "Close-ups", "First-Person POV", "Drone/Aerial"] },
            cameraMovement: { type: Type.STRING, enum: ["Smooth tracking", "Slow pan", "Handheld shake", "Static", "Crane movement"] },
            artKeywords: { type: Type.STRING, description: "Comma separated keywords describing the aesthetic" }
          },
          required: ["visualStyle", "colorPalette", "mood", "lighting", "cameraStyle", "cameraMovement", "artKeywords"]
        }
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) throw new Error("No analysis result");
    return JSON.parse(jsonStr);

  } catch (error) {
    console.error("Video Analysis Error:", error);
    throw error;
  }
};

const processScript = async (
  script: string, 
  settings: StyleSettings, 
  clipDuration: ClipDuration
): Promise<GeneratedClip[]> => {
  const ai = getAIClient();

  // Calculate approx words per chunk based on 3 words/second heuristic
  const wordsPerChunk = clipDuration * 3;
  const chunkDesc = `approximately ${wordsPerChunk} words (${clipDuration} seconds of speech)`;

  const systemInstruction = `You are an expert video prompt engineer for high-end AI video generation (Veo 3.1). 

  CORE RESPONSIBILITIES:
  1. Analyze the provided video script.
  2. Split the script into chunks of ${chunkDesc}.
  3. For each chunk, generate a specific video generation prompt using the PROVIDED STYLE SETTINGS.

  STYLE SETTINGS TO APPLY:
  - Visual Style: ${settings.visualStyle}
  - Color Palette: Primary(${settings.colorPalette.primary}), Secondary(${settings.colorPalette.secondary}), Accent(${settings.colorPalette.accent})
  - Mood: ${settings.mood}
  - Lighting: ${settings.lighting}
  - Camera: ${settings.cameraStyle} with ${settings.cameraMovement}
  - Keywords: ${settings.artKeywords}

  CRITICAL SAFETY & CONTENT PROTOCOLS:
  - STRICTLY FOLLOW Veo 3.1 safety protocols.
  - NO violence, gore, or blood. Convert violence to "aftermath", "tension", or "implication".
  - NO morphing or body horror.
  - NO direct touching, hugging, or kissing. Convert intimacy to "reaching out", "standing side-by-side", "intense eye contact", or "shared focus".

  GENERATION RULES:
  - Extract the 'scriptLine' EXACTLY word-for-word from the source text for that chunk.
  - 'narrativeContext': 40-80 words explaining the story beat.
  - 'visualPrompt': 80-150 words. MUST include: Visual Description, MOTION details, CAMERA MOVEMENT, and character ATTIRE.
  `;

  const prompt = `Here is the script to process:
  """
  ${script}
  """

  Generate the video clips now.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              scriptLine: { type: Type.STRING, description: "The exact text from the script for this segment." },
              narrativeContext: { type: Type.STRING, description: "40-80 words explaining the action/story context." },
              visualPrompt: { type: Type.STRING, description: "80-150 words describing visual, motion, camera, and attire." }
            },
            required: ["scriptLine", "narrativeContext", "visualPrompt"]
          }
        }
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) {
      throw new Error("Empty response from AI");
    }

    const rawClips = JSON.parse(jsonStr);

    return rawClips.map((clip: any, index: number) => ({
      id: crypto.randomUUID(),
      clipNumber: index + 1,
      scriptLine: clip.scriptLine,
      narrativeContext: clip.narrativeContext,
      visualPrompt: clip.visualPrompt
    }));

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

