import React, { useRef, useState, useEffect } from 'react';
import { StyleSettings } from '../types';
import { 
  VISUAL_STYLES, 
  LIGHTING_OPTIONS, 
  MOOD_OPTIONS, 
  CAMERA_STYLES, 
  CAMERA_MOVEMENTS 
} from '../constants';
import { Palette, Zap, Film, Camera, Video, Upload, Sparkles, Loader, X } from 'lucide-react';
import { geminiService } from '../services/geminiService';

interface StyleEngineProps {
  settings: StyleSettings;
  setSettings: React.Dispatch<React.SetStateAction<StyleSettings>>;
  disabled: boolean;
}

export const StyleEngine: React.FC<StyleEngineProps> = ({ settings, setSettings, disabled }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [videoPreview, setVideoPreview] = useState<string | null>(null);

  // Cleanup preview URL on unmount
  useEffect(() => {
    return () => {
      if (videoPreview) URL.revokeObjectURL(videoPreview);
    };
  }, [videoPreview]);

  const handleChange = (key: keyof StyleSettings, value: any) => {
    setSettings(prev => ({ ...prev, [key]: value }));
  };

  const handleColorChange = (key: 'primary' | 'secondary' | 'accent', value: string) => {
    setSettings(prev => ({
      ...prev,
      colorPalette: { ...prev.colorPalette, [key]: value }
    }));
  };

  const clearVideo = () => {
    if (videoPreview) URL.revokeObjectURL(videoPreview);
    setVideoPreview(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleVideoUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.size > 20 * 1024 * 1024) {
      alert("Please upload a video smaller than 20MB.");
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    // Set preview immediately
    const url = URL.createObjectURL(file);
    setVideoPreview(url);

    setAnalyzing(true);
    const reader = new FileReader();

    reader.onloadend = async () => {
      try {
        const base64String = reader.result?.toString().split(',')[1];
        if (base64String) {
          const newStyles = await geminiService.analyzeVideoStyle(base64String, file.type || 'video/mp4');
          setSettings(prev => ({ ...prev, ...newStyles }));
        }
      } catch (error) {
        console.error("Analysis failed", error);
        alert("Failed to analyze video style. Please try a different file.");
      } finally {
        setAnalyzing(false);
        // We do NOT clear the file input value here so the user sees something happened, 
        // but we already have the preview URL so strictly we can clear the input if we want 
        // to allow re-uploading the same file. 
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="bg-[#1a202c] border border-gray-700 rounded-xl p-6 mb-6 shadow-lg relative overflow-hidden">
      {/* Loading Overlay for Analysis */}
      {analyzing && (
        <div className="absolute inset-0 z-50 bg-[#1a202c]/90 flex flex-col items-center justify-center backdrop-blur-sm">
           <Loader className="animate-spin text-blue-500 w-10 h-10 mb-4" />
           <p className="text-blue-300 font-medium animate-pulse">Analyzing visual style...</p>
        </div>
      )}

      {/* Header & Auto-Fill */}
      <div className="flex flex-col gap-4 mb-6 border-b border-gray-700 pb-4">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <div className="w-2 h-8 bg-blue-600 rounded-full"></div>
            <h2 className="text-xl font-bold text-white tracking-wide">Style Engine</h2>
          </div>

          <div className="flex gap-2">
            <input 
              type="file" 
              ref={fileInputRef}
              onChange={handleVideoUpload}
              accept="video/mp4,video/quicktime,video/webm" 
              className="hidden" 
            />
            <button 
              onClick={() => fileInputRef.current?.click()}
              disabled={disabled || analyzing}
              className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-500 hover:to-blue-500 text-white rounded-lg text-sm font-semibold transition-all shadow-lg shadow-blue-900/30 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {analyzing ? <Sparkles className="animate-spin" size={16} /> : <Upload size={16} />}
              Analyze Video & Auto-Fill
            </button>
          </div>
        </div>

        {/* Video Preview Area */}
        {videoPreview && (
          <div className="relative w-full md:w-1/3 aspect-video bg-black rounded-lg overflow-hidden border border-gray-600 mx-auto md:mx-0">
            <video 
              src={videoPreview} 
              className="w-full h-full object-contain" 
              controls 
              playsInline
            />
            <button 
              onClick={clearVideo}
              className="absolute top-2 right-2 p-1 bg-black/50 hover:bg-red-600 rounded-full text-white transition-colors"
              title="Remove video"
            >
              <X size={14} />
            </button>
            <div className="absolute bottom-2 left-2 px-2 py-1 bg-black/60 rounded text-xs text-green-400 flex items-center gap-1">
              <CheckIcon /> Style Analyzed
            </div>
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">

        {/* Visual Style */}
        <div className="space-y-2">
          <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
            <Palette size={14} className="text-blue-500" /> Visual Style
          </label>
          <select
            value={settings.visualStyle}
            onChange={(e) => handleChange('visualStyle', e.target.value)}
            disabled={disabled}
            className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 focus:border-blue-500 outline-none"
          >
            {VISUAL_STYLES.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>

        {/* Mood */}
        <div className="space-y-2">
          <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
            <Film size={14} className="text-purple-500" /> Mood & Tone
          </label>
          <select
            value={settings.mood}
            onChange={(e) => handleChange('mood', e.target.value)}
            disabled={disabled}
            className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 focus:border-blue-500 outline-none"
          >
            {MOOD_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>

        {/* Lighting */}
        <div className="space-y-2">
          <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
            <Zap size={14} className="text-yellow-500" /> Lighting Style
          </label>
          <select
            value={settings.lighting}
            onChange={(e) => handleChange('lighting', e.target.value)}
            disabled={disabled}
            className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 focus:border-blue-500 outline-none"
          >
            {LIGHTING_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>

        {/* Camera Style */}
        <div className="space-y-2">
          <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
            <Camera size={14} className="text-green-500" /> Camera Style
          </label>
          <select
            value={settings.cameraStyle}
            onChange={(e) => handleChange('cameraStyle', e.target.value)}
            disabled={disabled}
            className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 focus:border-blue-500 outline-none"
          >
            {CAMERA_STYLES.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>

        {/* Camera Movement */}
        <div className="space-y-2">
          <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
            <Video size={14} className="text-red-500" /> Camera Movement
          </label>
          <select
            value={settings.cameraMovement}
            onChange={(e) => handleChange('cameraMovement', e.target.value)}
            disabled={disabled}
            className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 focus:border-blue-500 outline-none"
          >
            {CAMERA_MOVEMENTS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>

        {/* Color Palette */}
        <div className="space-y-2">
           <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
             Color Palette (Hex)
           </label>
           <div className="grid grid-cols-3 gap-2">
              <input 
                type="text" 
                placeholder="#Pri" 
                value={settings.colorPalette.primary}
                onChange={(e) => handleColorChange('primary', e.target.value)}
                className="bg-[#0e1117] border border-gray-600 text-xs text-white rounded p-2 text-center"
              />
              <input 
                type="text" 
                placeholder="#Sec" 
                value={settings.colorPalette.secondary}
                onChange={(e) => handleColorChange('secondary', e.target.value)}
                className="bg-[#0e1117] border border-gray-600 text-xs text-white rounded p-2 text-center"
              />
              <input 
                type="text" 
                placeholder="#Acc" 
                value={settings.colorPalette.accent}
                onChange={(e) => handleColorChange('accent', e.target.value)}
                className="bg-[#0e1117] border border-gray-600 text-xs text-white rounded p-2 text-center"
              />
           </div>
        </div>

        {/* Art Keywords - Spans full width */}
        <div className="md:col-span-2 lg:col-span-3 space-y-2">
          <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
            Art Direction Keywords
          </label>
          <input
             type="text"
             value={settings.artKeywords}
             onChange={(e) => handleChange('artKeywords', e.target.value)}
             placeholder="e.g. clean, minimal, 4K, bokeh, volumetric fog"
             disabled={disabled}
             className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 focus:border-blue-500 outline-none"
          />
        </div>

      </div>
    </div>
  );
};

const CheckIcon = () => (
  <svg className="w-3 h-3 text-green-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
  </svg>
);

import React, { useState, useEffect, useCallback } from 'react';
import { StyleEngine } from './components/StyleEngine';
import { MetricsDisplay } from './components/MetricsDisplay';
import { PromptCard } from './components/PromptCard';
import { ExportActions } from './components/ExportActions';
import { geminiService } from './services/geminiService';
import { StyleSettings, ScriptMetrics, GeneratedClip, GenerationStatus, ClipDuration } from './types';
import { DEFAULT_SETTINGS, CLIP_DURATIONS } from './constants';
import { Sparkles, Play, AlertCircle, Video, Loader2 } from 'lucide-react';

const App: React.FC = () => {
  const [script, setScript] = useState('');
  const [settings, setSettings] = useState<StyleSettings>(DEFAULT_SETTINGS);
  const [clipDuration, setClipDuration] = useState<ClipDuration>(8);
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [clips, setClips] = useState<GeneratedClip[]>([]);

  const [metrics, setMetrics] = useState<ScriptMetrics>({
    wordCount: 0,
    estimatedDurationMinutes: 0,
    estimatedClipCount: 0
  });

  // Calculate metrics on script change or duration change
  useEffect(() => {
    const trimmed = script.trim();
    if (!trimmed) {
      setMetrics({ wordCount: 0, estimatedDurationMinutes: 0, estimatedClipCount: 0 });
      return;
    }

    const words = trimmed.split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;
    // Heuristic: 3 words per second approx.
    const wordsPerSec = 3; 
    const totalDurationSeconds = wordCount / wordsPerSec;
    const durationMins = totalDurationSeconds / 60;

    const estClips = Math.ceil(totalDurationSeconds / clipDuration);

    setMetrics({
      wordCount,
      estimatedDurationMinutes: durationMins,
      estimatedClipCount: estClips
    });
  }, [script, clipDuration]);

  const handleGenerate = useCallback(async () => {
    if (!script.trim()) return;

    setStatus(GenerationStatus.LOADING);
    setErrorMsg(null);
    setClips([]);

    try {
      const generatedClips = await geminiService.processScript(script, settings, clipDuration);
      setClips(generatedClips);
      setStatus(GenerationStatus.SUCCESS);
    } catch (error: any) {
      setStatus(GenerationStatus.ERROR);
      setErrorMsg(error.message || "An unexpected error occurred.");
    }
  }, [script, settings, clipDuration]);

  return (
    <div className="min-h-screen bg-[#0f172a] text-gray-200 pb-20">
      {/* Navbar / Header */}
      <header className="bg-[#0f172a]/80 backdrop-blur-md border-b border-gray-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-900/50">
              <Sparkles className="text-white w-6 h-6" />
            </div>
            <h1 className="text-2xl font-bold text-white tracking-tight">
              Video Script to <span className="text-blue-500">Prompt Elite 2.0</span>
            </h1>
          </div>
          <div className="text-sm text-gray-500 hidden sm:block font-medium">
            Powered by Gemini 2.5
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-10 space-y-10">

        {/* Style Engine Panel */}
        <section>
          <StyleEngine 
            settings={settings} 
            setSettings={setSettings} 
            disabled={status === GenerationStatus.LOADING}
          />
        </section>

        {/* Input & Output Grid */}
        <section className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Left Column: Input */}
          <div className="lg:col-span-1 space-y-6">
            <div className="sticky top-28 space-y-6">

              {/* Script Input Box */}
              <div className="space-y-2">
                <div className="flex justify-between items-center">
                  <label className="text-sm font-bold text-gray-300 uppercase tracking-wider">Input Script</label>
                  <button 
                    onClick={() => setScript('')}
                    className="text-xs text-red-400 hover:text-red-300 transition-colors"
                  >
                    Clear
                  </button>
                </div>

                <div className="relative">
                  <textarea
                    value={script}
                    onChange={(e) => setScript(e.target.value)}
                    placeholder="Paste your video script here..."
                    className="w-full h-[400px] bg-[#1e293b] border border-gray-700 rounded-xl p-4 text-gray-200 placeholder-gray-500 focus:ring-2 focus:ring-blue-600 focus:border-transparent transition-all resize-none font-mono text-sm leading-relaxed"
                    disabled={status === GenerationStatus.LOADING}
                  />

                  {/* Generate Button Overlay */}
                  <div className="absolute bottom-4 right-4 left-4">
                    <button
                      onClick={handleGenerate}
                      disabled={status === GenerationStatus.LOADING || !script.trim()}
                      className={`w-full py-4 rounded-lg flex items-center justify-center gap-2 font-bold text-lg shadow-xl transition-all transform active:scale-95 ${
                        status === GenerationStatus.LOADING || !script.trim()
                          ? 'bg-gray-700 text-gray-500 cursor-not-allowed'
                          : 'bg-[#3b82f6] hover:bg-blue-600 text-white shadow-blue-900/50 hover:shadow-blue-700/50'
                      }`}
                    >
                      {status === GenerationStatus.LOADING ? (
                        <>
                          <Loader2 className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" />
                          Processing...
                        </>
                      ) : (
                        <>
                          <Play fill="currentColor" size={20} />
                          GENERATE PROMPTS
                        </>
                      )}
                    </button>
                  </div>
                </div>
              </div>

              {/* Clip Duration Selector */}
              <div className="bg-[#1e293b] border border-gray-700 rounded-xl p-4">
                <label className="text-xs font-bold text-gray-400 uppercase tracking-wider block mb-3">Seconds per Clip</label>
                <div className="flex justify-between gap-2">
                  {CLIP_DURATIONS.map(dur => (
                    <button
                      key={dur}
                      onClick={() => setClipDuration(dur)}
                      className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${
                        clipDuration === dur 
                          ? 'bg-blue-600 text-white shadow-lg' 
                          : 'bg-[#0f172a] text-gray-400 hover:text-white border border-gray-700 hover:border-gray-500'
                      }`}
                    >
                      {dur}s
                    </button>
                  ))}
                </div>
              </div>

              <MetricsDisplay metrics={metrics} />
            </div>
          </div>

          {/* Right Column: Output */}
          <div className="lg:col-span-2 space-y-6">
             <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-gray-800 pb-4">
                <div className="flex items-center gap-3">
                  <h2 className="text-xl font-bold text-white">Generated Output</h2>
                  {clips.length > 0 && (
                    <span className="bg-green-900/30 text-green-400 px-3 py-1 rounded-full text-xs font-semibold border border-green-800">
                      {clips.length} Clips
                    </span>
                  )}
                </div>

                {/* Export Options */}
                <ExportActions clips={clips} />
             </div>

             {status === GenerationStatus.ERROR && (
               <div className="bg-red-900/20 border border-red-800 text-red-200 p-4 rounded-lg flex items-center gap-3">
                 <AlertCircle className="shrink-0" />
                 <p>{errorMsg}</p>
               </div>
             )}

             {status === GenerationStatus.LOADING && (
               <div className="space-y-6 animate-pulse">
                  <div className="bg-[#1e293b] h-32 rounded-xl border border-gray-700/50 p-6 flex flex-col gap-3">
                     <div className="h-4 bg-gray-700 rounded w-1/4"></div>
                     <div className="h-4 bg-gray-700 rounded w-3/4"></div>
                     <div className="h-20 bg-gray-800 rounded w-full mt-2"></div>
                  </div>
                  <div className="bg-[#1e293b] h-32 rounded-xl border border-gray-700/50 p-6 flex flex-col gap-3 opacity-70">
                     <div className="h-4 bg-gray-700 rounded w-1/4"></div>
