import React, { useRef, useState, useEffect } from 'react';
import { StyleSettings } from '../types';
import { 
  VISUAL_STYLES, 
  LIGHTING_OPTIONS, 
  MOOD_OPTIONS, 
  CAMERA_STYLES, 
  CAMERA_MOVEMENTS 
} from '../constants';
import { Palette, Zap, Film, Camera, Video, Upload, Sparkles, Loader, X, AlertCircle } from 'lucide-react';
import { geminiService } from '../services/geminiService';

interface StyleEngineProps {
  settings: StyleSettings;
  setSettings: React.Dispatch<React.SetStateAction<StyleSettings>>;
  disabled: boolean;
}

export const StyleEngine: React.FC<StyleEngineProps> = ({ settings, setSettings, disabled }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [videoPreview, setVideoPreview] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Cleanup preview URL on unmount
  useEffect(() => {
    return () => {
      if (videoPreview) URL.revokeObjectURL(videoPreview);
    };
  }, [videoPreview]);

  const handleChange = (key: keyof StyleSettings, value: any) => {
    setSettings(prev => ({ ...prev, [key]: value }));
  };

  const handleColorChange = (key: 'primary' | 'secondary' | 'accent', value: string) => {
    setSettings(prev => ({
      ...prev,
      colorPalette: { ...prev.colorPalette, [key]: value }
    }));
  };

  const clearVideo = () => {
    if (videoPreview) URL.revokeObjectURL(videoPreview);
    setVideoPreview(null);
    setError(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleVideoUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    setError(null);

    if (!file) return;

    // 1. File Size Validation (20MB Limit)
    if (file.size > 20 * 1024 * 1024) {
      setError("File size exceeds 20MB limit. Please upload a smaller video clip.");
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    // 2. File Type Validation
    const supportedTypes = ['video/mp4', 'video/quicktime', 'video/webm', 'video/mpeg', 'video/x-matroska'];
    if (!supportedTypes.includes(file.type)) {
      setError("Unsupported file format. Please use MP4, MOV, WEBM, or MPEG.");
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    // Set preview immediately
    const url = URL.createObjectURL(file);
    setVideoPreview(url);

    setAnalyzing(true);
    const reader = new FileReader();

    reader.onloadend = async () => {
      try {
        const result = reader.result;
        if (!result) throw new Error("Failed to read file data.");

        const base64String = result.toString().split(',')[1];
        if (base64String) {
          const newStyles = await geminiService.analyzeVideoStyle(base64String, file.type);
          setSettings(prev => ({ ...prev, ...newStyles }));
        }
      } catch (err: any) {
        console.error("Analysis failed", err);

        // Specific API Error handling
        let errorMessage = "Failed to analyze video style.";
        if (err.message?.includes('400')) {
          errorMessage = "The AI model could not process this video format. Try converting to MP4.";
        } else if (err.message?.includes('413') || err.message?.includes('too large')) {
          errorMessage = "Video content is too complex or large for the AI model.";
        } else if (err.message?.includes('API Key')) {
          errorMessage = "API Key is missing or invalid.";
        }

        setError(errorMessage);

        // Remove preview on analysis failure so user knows to try again
        if (videoPreview) URL.revokeObjectURL(videoPreview);
        setVideoPreview(null);

      } finally {
        setAnalyzing(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.onerror = () => {
      setAnalyzing(false);
      setError("Error reading file from disk. Please try again.");
      if (fileInputRef.current) fileInputRef.current.value = '';
    };

    reader.readAsDataURL(file);
  };

  return (
    <div className="bg-[#1a202c] border border-gray-700 rounded-xl p-6 mb-6 shadow-lg relative overflow-hidden">
      {/* Loading Overlay for Analysis */}
      {analyzing && (
        <div className="absolute inset-0 z-50 bg-[#1a202c]/90 flex flex-col items-center justify-center backdrop-blur-sm">
           <Loader className="animate-spin text-blue-500 w-10 h-10 mb-4" />
           <p className="text-blue-300 font-medium animate-pulse">Analyzing visual style...</p>
        </div>
      )}

      {/* Header & Auto-Fill */}
      <div className="flex flex-col gap-4 mb-6 border-b border-gray-700 pb-4">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <div className="w-2 h-8 bg-blue-600 rounded-full"></div>
            <h2 className="text-xl font-bold text-white tracking-wide">Style Engine</h2>
          </div>

          <div className="flex gap-2">
            <input 
              type="file" 
              ref={fileInputRef}
              onChange={handleVideoUpload}
              accept="video/mp4,video/quicktime,video/webm" 
              className="hidden" 
            />
            <button 
              onClick={() => fileInputRef.current?.click()}
              disabled={disabled || analyzing}
              className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-500 hover:to-blue-500 text-white rounded-lg text-sm font-semibold transition-all shadow-lg shadow-blue-900/30 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {analyzing ? <Sparkles className="animate-spin" size={16} /> : <Upload size={16} />}
              Analyze Video & Auto-Fill
            </button>
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="bg-red-900/20 border border-red-800 text-red-200 p-3 rounded-lg flex items-center gap-2 text-sm">
            <AlertCircle size={16} className="shrink-0" />
            <p>{error}</p>
          </div>
        )}

        {/* Video Preview Area */}
        {videoPreview && !error && (
          <div className="relative w-full md:w-1/3 aspect-video bg-black rounded-lg overflow-hidden border border-gray-600 mx-auto md:mx-0">
            <video 
              src={videoPreview} 
              className="w-full h-full object-contain" 
              controls 
              playsInline
            />
            <button 
              onClick={clearVideo}
              className="absolute top-2 right-2 p-1 bg-black/50 hover:bg-red-600 rounded-full text-white transition-colors"
              title="Remove video"
            >
              <X size={14} />
            </button>
            {!analyzing && (
              <div className="absolute bottom-2 left-2 px-2 py-1 bg-black/60 rounded text-xs text-green-400 flex items-center gap-1">
                <CheckIcon /> Style Analyzed
              </div>
            )}
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">

        {/* Visual Style */}
        <div className="space-y-2">
          <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
            <Palette size={14} className="text-blue-500" /> Visual Style
          </label>
          <select
            value={settings.visualStyle}
            onChange={(e) => handleChange('visualStyle', e.target.value)}
            disabled={disabled}
            className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 focus:border-blue-500 outline-none"
          >
            {VISUAL_STYLES.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>

        {/* Mood */}
        <div className="space-y-2">
          <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
            <Film size={14} className="text-purple-500" /> Mood & Tone
          </label>
          <select
            value={settings.mood}
            onChange={(e) => handleChange('mood', e.target.value)}
            disabled={disabled}
            className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 focus:border-blue-500 outline-none"
          >
            {MOOD_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>

        {/* Lighting */}
        <div className="space-y-2">
          <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
            <Zap size={14} className="text-yellow-500" /> Lighting Style
          </label>
          <select
            value={settings.lighting}
            onChange={(e) => handleChange('lighting', e.target.value)}
            disabled={disabled}
            className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 focus:border-blue-500 outline-none"
          >
            {LIGHTING_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>

        {/* Camera Style */}
        <div className="space-y-2">
          <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
            <Camera size={14} className="text-green-500" /> Camera Style
          </label>
          <select
            value={settings.cameraStyle}
            onChange={(e) => handleChange('cameraStyle', e.target.value)}
            disabled={disabled}
            className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 focus:border-blue-500 outline-none"
          >
            {CAMERA_STYLES.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>

        {/* Camera Movement */}
        <div className="space-y-2">
          <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
            <Video size={14} className="text-red-500" /> Camera Movement
          </label>
          <select
            value={settings.cameraMovement}
            onChange={(e) => handleChange('cameraMovement', e.target.value)}
            disabled={disabled}
            className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 focus:border-blue-500 outline-none"
          >
            {CAMERA_MOVEMENTS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>

        {/* Color Palette */}
        <div className="space-y-2">
           <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
             Color Palette (Hex)
           </label>
           <div className="grid grid-cols-3 gap-2">
              <input 
                type="text" 
                placeholder="#Pri" 
                value={settings.colorPalette.primary}
                onChange={(e) => handleColorChange('primary', e.target.value)}
                className="bg-[#0e1117] border border-gray-600 text-xs text-white rounded p-2 text-center"
              />
              <input 
                type="text" 
                placeholder="#Sec" 
                value={settings.colorPalette.secondary}
                onChange={(e) => handleColorChange('secondary', e.target.value)}
                className="bg-[#0e1117] border border-gray-600 text-xs text-white rounded p-2 text-center"
              />
              <input 
                type="text" 
                placeholder="#Acc" 
                value={settings.colorPalette.accent}
                onChange={(e) => handleColorChange('accent', e.target.value)}
                className="bg-[#0e1117] border border-gray-600 text-xs text-white rounded p-2 text-center"
              />
           </div>
        </div>

        {/* Art Keywords - Spans full width */}
        <div className="md:col-span-2 lg:col-span-3 space-y-2">
          <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
            Art Direction Keywords
          </label>
          <input
             type="text"
             value={settings.artKeywords}
             onChange={(e) => handleChange('artKeywords', e.target.value)}
             placeholder="e.g. clean, minimal, 4K, bokeh, volumetric fog"
             disabled={disabled}
             className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 focus:border-blue-500 outline-none"
          />
        </div>

      </div>
    </div>
  );
};

