        {/* Script Line */}
        <div>
          <div className="flex items-center gap-2 mb-1 text-gray-400 text-xs font-semibold uppercase tracking-wider">
            <FileText size={14} /> Script Line
          </div>
          <div className="text-lg font-serif text-white italic border-l-2 border-blue-500 pl-3 py-1">
            "{clip.scriptLine}"
