import React, { useRef, useState, useEffect } from 'react';
import { StyleSettings } from '../types';
import { 
  VISUAL_STYLES, 
  LIGHTING_OPTIONS, 
  MOOD_OPTIONS, 
  CAMERA_STYLES, 
  CAMERA_MOVEMENTS 
} from '../constants';
import { Palette, Zap, Film, Camera, Video, Upload, Sparkles, Loader, X, AlertCircle, Edit3, ChevronDown } from 'lucide-react';
import { geminiService } from '../services/geminiService';

interface StyleEngineProps {
  settings: StyleSettings;
  setSettings: React.Dispatch<React.SetStateAction<StyleSettings>>;
  disabled: boolean;
}

// Helper Component for Select/Custom Logic
const StyleSelector: React.FC<{
  label: string;
  icon: React.ReactNode;
  value: string;
  options: string[];
  onChange: (val: string) => void;
  disabled: boolean;
}> = ({ label, icon, value, options, onChange, disabled }) => {
  // Determine if we are in custom mode.
  // We are in custom mode if the current value is NOT in the standard options list
  // AND the value is not empty (unless manually triggered).
  const [isCustomMode, setIsCustomMode] = useState(false);

  useEffect(() => {
    // If the incoming value (e.g. from Video Analysis) is not in the list, switch to input mode automatically
    if (value && !options.includes(value)) {
      setIsCustomMode(true);
    } else {
      setIsCustomMode(false);
    }
  }, [value, options]);

  const handleSelectChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selected = e.target.value;
    if (selected === "✏️ Custom...") {
      setIsCustomMode(true);
      onChange(""); // Clear for typing
    } else {
      onChange(selected);
    }
  };

  const handleResetToDropdown = () => {
    setIsCustomMode(false);
    onChange(options[0]); // Reset to first option
  };

  return (
    <div className="space-y-2">
      <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">
        {icon} {label}
      </label>

      {isCustomMode ? (
        <div className="relative flex items-center animate-in fade-in zoom-in duration-200">
          <input
            type="text"
            value={value}
            onChange={(e) => onChange(e.target.value)}
            placeholder={`Type custom ${label.toLowerCase()}...`}
            disabled={disabled}
            autoFocus
