                placeholder="e.g. clean, minimal, 4K, bokeh, volumetric fog"
                disabled={disabled}
                className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 pl-9 focus:border-blue-500 outline-none"
             />
             <div className="absolute left-3 top-3 text-gray-500">
