import React, { useRef, useState, useEffect } from 'react';
import { StyleSettings, Character } from '../types';
import { 
  VISUAL_STYLES, 
  LIGHTING_OPTIONS, 
  MOOD_OPTIONS, 
  CAMERA_STYLES, 
  CAMERA_MOVEMENTS 
} from '../constants';
import { Palette, Zap, Film, Camera, Video, Upload, Sparkles, Loader, X, AlertCircle, Edit3, ChevronDown, Users, UserPlus, Lock, Trash2, User, Image as ImageIcon } from 'lucide-react';
