                )}
              </label>
              {charError?.id === character.id && (
                <p className="text-[10px] text-red-400 mt-1">{charError.msg}</p>
              )}
            </div>
          </div>
        </div>

        {/* RIGHT COLUMN: Description & Style Engine */}
        <div className="md:col-span-9 space-y-4">
          <div className="space-y-2 relative">
            <label className="text-xs font-bold text-gray-500 uppercase flex justify-between items-center">
              <span>Fixed Visual Anchor (Strict Description)</span>
              <label className="flex items-center gap-2 cursor-pointer">
                <input 
                  type="checkbox" 
                  checked={character.isFaceLocked}
                  onChange={(e) => updateCharacter(character.id, { isFaceLocked: e.target.checked })}
                  disabled={disabled}
                  className="accent-purple-500"
                />
                <span className={`text-xs flex items-center gap-1 ${character.isFaceLocked ? 'text-purple-400 font-bold' : 'text-gray-500'}`}>
                  <Lock size={12} /> Strict Face Lock
                </span>
              </label>
            </label>
            <textarea 
              value={character.description}
              onChange={(e) => updateCharacter(character.id, { description: e.target.value })}
              placeholder="e.g. Young woman, 20s, sharp features, wearing worn grey 1940s wool coat, blonde hair in a messy braid."
              disabled={disabled}
              className="w-full h-24 bg-[#1e293b] border border-gray-600 rounded p-3 text-sm text-gray-200 focus:border-purple-500 outline-none resize-none leading-relaxed transition-all"
            />
          </div>

          {/* COLLAPSIBLE: CHARACTER-SPECIFIC STYLE ENGINE */}
          <div className="bg-[#1e293b]/50 border border-gray-700/50 rounded-lg overflow-hidden">
            <div className="flex items-center justify-between p-3 bg-gray-800/50 hover:bg-gray-800 transition-colors">
               <button 
                onClick={() => setIsStyleExpanded(!isStyleExpanded)}
                className="flex items-center gap-2 text-xs font-bold uppercase text-purple-300"
              >
                <Palette size={14} /> 🎨 Character-Specific Style Engine
                {isStyleExpanded ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
              </button>

              {/* Preset Manager for Character (Compact Mode) */}
              <div className="w-64" onClick={(e) => e.stopPropagation()}>
                <PresetManager 
                  compact 
                  disabled={disabled}
                  currentData={{
                    visualStyle: character.visualStyle,
                    mood: character.mood,
                    lighting: character.lighting,
                    cameraStyle: character.cameraStyle,
                    cameraMovement: character.cameraMovement,
                    colorPalette: character.colorPalette || { primary: '', secondary: '', accent: '' }
                  }}
                  onLoad={(data) => updateCharacter(character.id, { ...data })}
                />
              </div>
            </div>

            {isStyleExpanded && (
              <div className="p-4 bg-[#0f172a] border-t border-gray-700 animate-in slide-in-from-top-2">
                <p className="text-[10px] text-gray-500 mb-3">Overrides global project settings when this character appears.</p>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                  <StyleSelector 
                    label="Visual Style" 
                    icon={<Palette size={12} className="text-blue-500" />} 
                    value={character.visualStyle || ''} 
                    options={VISUAL_STYLES} 
                    onChange={(val) => updateCharacter(character.id, { visualStyle: val })} 
                    disabled={disabled}
                    compact
                  />
                  <StyleSelector 
                    label="Mood" 
                    icon={<Film size={12} className="text-purple-500" />} 
                    value={character.mood || ''} 
                    options={MOOD_OPTIONS} 
                    onChange={(val) => updateCharacter(character.id, { mood: val })} 
                    disabled={disabled}
                    compact
                  />
                  <StyleSelector 
                    label="Lighting" 
                    icon={<Zap size={12} className="text-yellow-500" />} 
                    value={character.lighting || ''} 
                    options={LIGHTING_OPTIONS} 
                    onChange={(val) => updateCharacter(character.id, { lighting: val })} 
                    disabled={disabled}
                    compact
                  />
                  <StyleSelector 
                    label="Camera" 
                    icon={<Camera size={12} className="text-green-500" />} 
                    value={character.cameraStyle || ''} 
                    options={CAMERA_STYLES} 
                    onChange={(val) => updateCharacter(character.id, { cameraStyle: val })} 
                    disabled={disabled}
                    compact
                  />
                  <StyleSelector 
                    label="Movement" 
                    icon={<Video size={12} className="text-red-500" />} 
                    value={character.cameraMovement || ''} 
                    options={CAMERA_MOVEMENTS} 
                    onChange={(val) => updateCharacter(character.id, { cameraMovement: val })} 
                    disabled={disabled}
                    compact
                  />

                  {/* Mini Color Palette */}
                  <div className="space-y-1.5">
                     <label className="flex items-center gap-2 text-[10px] font-bold uppercase text-gray-400">Palette Override</label>
                     <div className="grid grid-cols-3 gap-1">
                        <input type="text" placeholder="#Pri" value={character.colorPalette?.primary || ''} onChange={(e) => updateCharacter(character.id, { colorPalette: { ...character.colorPalette!, primary: e.target.value } })} className="bg-[#0e1117] border border-gray-600 text-[10px] text-white rounded p-1.5 text-center" />
                        <input type="text" placeholder="#Sec" value={character.colorPalette?.secondary || ''} onChange={(e) => updateCharacter(character.id, { colorPalette: { ...character.colorPalette!, secondary: e.target.value } })} className="bg-[#0e1117] border border-gray-600 text-[10px] text-white rounded p-1.5 text-center" />
                        <input type="text" placeholder="#Acc" value={character.colorPalette?.accent || ''} onChange={(e) => updateCharacter(character.id, { colorPalette: { ...character.colorPalette!, accent: e.target.value } })} className="bg-[#0e1117] border border-gray-600 text-[10px] text-white rounded p-1.5 text-center" />
                     </div>
                  </div>
                </div>
              </div>
            )}
          </div>

        </div>
      </div>
    </div>
  );
};


// ----------------------------------------------------------------------
// 4. MAIN STYLE ENGINE COMPONENT
// ----------------------------------------------------------------------

export const StyleEngine: React.FC<StyleEngineProps> = ({ settings, setSettings, disabled }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeTab, setActiveTab] = useState<'style' | 'characters'>('style');
  const [analyzing, setAnalyzing] = useState(false);
  const [videoPreview, setVideoPreview] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Character Analysis State
  const [analyzingCharId, setAnalyzingCharId] = useState<string | null>(null);
  const [charError, setCharError] = useState<{id: string, msg: string} | null>(null);

  // Character Management
  const addCharacter = () => {
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: "New Character",
      description: "Describe visual appearance here...",
      frequency: "Main Protagonist",
      isFaceLocked: false,
      // Initialize with Global Settings Defaults
      visualStyle: settings.visualStyle,
      lighting: settings.lighting,
      mood: settings.mood,
      cameraStyle: settings.cameraStyle,
      cameraMovement: settings.cameraMovement,
      colorPalette: { ...settings.colorPalette }
    };
    setSettings(prev => ({ ...prev, characters: [...prev.characters, newChar] }));
  };

  const updateCharacter = (id: string, updates: Partial<Character>) => {
    setSettings(prev => ({
      ...prev,
      characters: prev.characters.map(c => c.id === id ? { ...c, ...updates } : c)
    }));
  };

  const removeCharacter = (id: string) => {
    setSettings(prev => ({
      ...prev,
      characters: prev.characters.filter(c => c.id !== id)
    }));
  };

  const handleCharacterImageUpload = async (charId: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setAnalyzingCharId(charId);
    setCharError(null);

    const reader = new FileReader();
    reader.onloadend = async () => {
      try {
        const result = reader.result;
        if (!result) throw new Error("Failed to read file.");
        const base64String = result.toString().split(',')[1];

        const description = await geminiService.analyzeCharacterImage(base64String, file.type);
        updateCharacter(charId, { description });
      } catch (err) {
        setCharError({ id: charId, msg: "Could not analyze character. Please enter description manually." });
      } finally {
        setAnalyzingCharId(null);
        e.target.value = '';
      }
    };
    reader.readAsDataURL(file);
  };

  // Cleanup preview URL on unmount
  useEffect(() => {
    return () => {
      if (videoPreview) URL.revokeObjectURL(videoPreview);
    };
  }, [videoPreview]);

  const handleChange = (key: keyof StyleSettings, value: any) => {
    setSettings(prev => ({ ...prev, [key]: value }));
  };

  const handleColorChange = (key: 'primary' | 'secondary' | 'accent', value: string) => {
    setSettings(prev => ({
      ...prev,
      colorPalette: { ...prev.colorPalette, [key]: value }
    }));
  };

  const clearVideo = () => {
    if (videoPreview) URL.revokeObjectURL(videoPreview);
    setVideoPreview(null);
    setError(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleVideoUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    setError(null);
    if (!file) return;

    if (file.size > 100 * 1024 * 1024) {
      setError("File size exceeds 100MB limit. Please upload a smaller video clip.");
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    const supportedTypes = ['video/mp4', 'video/quicktime', 'video/webm', 'video/mpeg', 'video/x-matroska'];
    if (!supportedTypes.includes(file.type)) {
      setError("Unsupported file format. Please use MP4, MOV, WEBM, or MPEG.");
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    const url = URL.createObjectURL(file);
    setVideoPreview(url);

    setAnalyzing(true);
    const reader = new FileReader();

    reader.onloadend = async () => {
      try {
        const result = reader.result;
        if (!result) throw new Error("Failed to read file data.");

        const base64String = result.toString().split(',')[1];
        if (base64String) {
          const newStyles = await geminiService.analyzeVideoStyle(base64String, file.type);
          setSettings(prev => ({ ...prev, ...newStyles }));
          setActiveTab('style');
        }
      } catch (err: any) {
        console.error("Analysis failed", err);
        let errorMessage = "Failed to analyze video style.";
        const msg = err.message || '';

        if (msg.includes('400')) errorMessage = "Invalid Request (400): The AI model rejected the video format.";
        else if (msg.includes('413')) errorMessage = "Payload Too Large (413): The video file is too heavy.";
        else if (msg.includes('429')) errorMessage = "Rate Limit Exceeded (429): System is busy.";
        else if (msg.includes('safety')) errorMessage = "Safety Filter: Video content flagged.";
        else if (msg.includes('No analysis result')) errorMessage = "Analysis Failed: No data returned.";

        setError(errorMessage);
        if (videoPreview) URL.revokeObjectURL(videoPreview);
        setVideoPreview(null);
      } finally {
        setAnalyzing(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.onerror = () => {
      setAnalyzing(false);
      setError("Browser Error: Failed to read file.");
      if (fileInputRef.current) fileInputRef.current.value = '';
    };

    reader.readAsDataURL(file);
  };

  return (
    <div className="bg-[#1a202c] border border-gray-700 rounded-xl mb-6 shadow-lg relative overflow-hidden flex flex-col">
      {/* Loading Overlay */}
      {analyzing && (
        <div className="absolute inset-0 z-50 bg-[#1a202c]/90 flex flex-col items-center justify-center backdrop-blur-sm">
           <Loader className="animate-spin text-blue-500 w-10 h-10 mb-4" />
           <p className="text-blue-300 font-medium animate-pulse">Analyzing visual style...</p>
        </div>
      )}

      {/* Tabs Header */}
      <div className="flex border-b border-gray-700 bg-[#0f172a]">
        <button
          onClick={() => setActiveTab('style')}
          className={`flex-1 py-4 flex items-center justify-center gap-2 font-bold text-sm tracking-wide transition-colors ${
            activeTab === 'style' 
            ? 'bg-[#1a202c] text-blue-400 border-t-2 border-blue-500' 
            : 'text-gray-500 hover:text-gray-300 hover:bg-[#1a202c]/50'
          }`}
        >
          <Palette size={16} /> VISUAL STYLE ENGINE
        </button>
        <button
          onClick={() => setActiveTab('characters')}
          className={`flex-1 py-4 flex items-center justify-center gap-2 font-bold text-sm tracking-wide transition-colors ${
            activeTab === 'characters' 
            ? 'bg-[#1a202c] text-purple-400 border-t-2 border-purple-500' 
            : 'text-gray-500 hover:text-gray-300 hover:bg-[#1a202c]/50'
          }`}
        >
          <Users size={16} /> CAST & CHARACTERS
          <span className="bg-gray-700 text-gray-300 px-2 py-0.5 rounded-full text-xs">
            {settings.characters.length}
          </span>
        </button>
      </div>

      <div className="p-6">
        {/* TAB 1: VISUAL STYLE CONTENT */}
        {activeTab === 'style' && (
          <div className="animate-in fade-in duration-300">
            {/* Auto-Fill Header */}
            <div className="flex flex-col gap-4 mb-6 border-b border-gray-700 pb-4">

              {/* Preset Toolbar */}
              <div className="flex items-center gap-4 bg-[#1e293b] p-3 rounded-lg border border-gray-600 mb-2">
                <span className="text-xs font-bold uppercase text-gray-400 whitespace-nowrap hidden sm:block">Global Presets:</span>
                <PresetManager 
                  disabled={disabled}
                  currentData={{
                    visualStyle: settings.visualStyle,
                    mood: settings.mood,
                    lighting: settings.lighting,
                    cameraStyle: settings.cameraStyle,
                    cameraMovement: settings.cameraMovement,
                    colorPalette: settings.colorPalette
                  }}
                  onLoad={(data) => setSettings(prev => ({ ...prev, ...data }))}
                />
              </div>

              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mt-2">
                <div className="space-y-1 max-w-lg">
                  <h3 className="text-sm font-bold text-gray-200">Reference Video (Upload .mp4/mov)</h3>
                  <p className="text-xs text-gray-500 leading-relaxed">
                    💡 Pro Tip: For YouTube videos, screen-record the specific scene you want to mimic and upload that clip here. The AI will analyze the lighting and camera style frame-by-frame.
                  </p>
                </div>
                <div className="flex gap-2 shrink-0">
                  <input 
                    type="file" 
                    ref={fileInputRef}
                    onChange={handleVideoUpload}
                    accept="video/mp4,video/quicktime,video/webm" 
                    className="hidden" 
                  />
                  <button 
                    onClick={() => fileInputRef.current?.click()}
                    disabled={disabled || analyzing}
                    className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-blue-700 to-blue-600 hover:from-blue-600 hover:to-blue-500 text-white rounded-lg text-sm font-semibold transition-all shadow-lg shadow-blue-900/30 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {analyzing ? <Sparkles className="animate-spin" size={16} /> : <Upload size={16} />}
                    Auto-Fill from Video
                  </button>
                </div>
              </div>

              {error && (
                <div className="bg-red-900/20 border border-red-800 text-red-200 p-3 rounded-lg flex items-center gap-2 text-sm">
                  <AlertCircle size={16} className="shrink-0" />
                  <p>{error}</p>
                </div>
              )}

              {videoPreview && !error && (
                <div className="relative w-full md:w-1/3 aspect-video bg-black rounded-lg overflow-hidden border border-gray-600 mx-auto md:mx-0">
                  <video src={videoPreview} className="w-full h-full object-contain" controls playsInline />
                  <button 
                    onClick={clearVideo}
                    className="absolute top-2 right-2 p-1 bg-black/50 hover:bg-red-600 rounded-full text-white transition-colors"
                    title="Remove video"
                  >
                    <X size={14} />
                  </button>
                  {!analyzing && (
                    <div className="absolute bottom-2 left-2 px-2 py-1 bg-black/60 rounded text-xs text-green-400 flex items-center gap-1">
                      <CheckIcon /> Style Analyzed
                    </div>
                  )}
                </div>
              )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              <StyleSelector label="Visual Style" icon={<Palette size={14} className="text-blue-500" />} value={settings.visualStyle} options={VISUAL_STYLES} onChange={(val) => handleChange('visualStyle', val)} disabled={disabled} />
              <StyleSelector label="Mood & Tone" icon={<Film size={14} className="text-purple-500" />} value={settings.mood} options={MOOD_OPTIONS} onChange={(val) => handleChange('mood', val)} disabled={disabled} />
              <StyleSelector label="Lighting Style" icon={<Zap size={14} className="text-yellow-500" />} value={settings.lighting} options={LIGHTING_OPTIONS} onChange={(val) => handleChange('lighting', val)} disabled={disabled} />
              <StyleSelector label="Camera Style" icon={<Camera size={14} className="text-green-500" />} value={settings.cameraStyle} options={CAMERA_STYLES} onChange={(val) => handleChange('cameraStyle', val)} disabled={disabled} />
              <StyleSelector label="Camera Movement" icon={<Video size={14} className="text-red-500" />} value={settings.cameraMovement} options={CAMERA_MOVEMENTS} onChange={(val) => handleChange('cameraMovement', val)} disabled={disabled} />

              <div className="space-y-2">
                 <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">Color Palette (Hex)</label>
                 <div className="grid grid-cols-3 gap-2">
                    <input type="text" placeholder="#Pri" value={settings.colorPalette.primary} onChange={(e) => handleColorChange('primary', e.target.value)} className="bg-[#0e1117] border border-gray-600 text-xs text-white rounded p-2 text-center" />
                    <input type="text" placeholder="#Sec" value={settings.colorPalette.secondary} onChange={(e) => handleColorChange('secondary', e.target.value)} className="bg-[#0e1117] border border-gray-600 text-xs text-white rounded p-2 text-center" />
                    <input type="text" placeholder="#Acc" value={settings.colorPalette.accent} onChange={(e) => handleColorChange('accent', e.target.value)} className="bg-[#0e1117] border border-gray-600 text-xs text-white rounded p-2 text-center" />
                 </div>
              </div>

              <div className="md:col-span-2 lg:col-span-3 space-y-2">
                <label className="flex items-center gap-2 text-xs font-bold uppercase text-gray-400">Art Direction Keywords</label>
                <div className="relative">
                   <input type="text" value={settings.artKeywords} onChange={(e) => handleChange('artKeywords', e.target.value)} placeholder="e.g. clean, minimal, 4K, bokeh, volumetric fog" disabled={disabled} className="w-full bg-[#0e1117] border border-gray-600 text-gray-200 rounded-lg p-2.5 pl-9 focus:border-blue-500 outline-none" />
                   <div className="absolute left-3 top-3 text-gray-500"><Edit3 size={14} /></div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* TAB 2: CHARACTERS CONTENT */}
        {activeTab === 'characters' && (
          <div className="space-y-6 animate-in fade-in duration-300">
             <div className="flex justify-between items-center">
               <p className="text-sm text-gray-400">Define characters here. The AI will strictly use these descriptions when names appear in the script.</p>
               <button onClick={addCharacter} disabled={disabled} className="px-4 py-2 bg-purple-600 hover:bg-purple-500 text-white text-sm font-bold rounded-lg flex items-center gap-2 shadow-lg shadow-purple-900/40 transition-all">
                 <UserPlus size={16} /> Add Character
               </button>
             </div>

             <div className="grid grid-cols-1 gap-4">
               {settings.characters.length === 0 && (
                 <div className="text-center py-10 border-2 border-dashed border-gray-700 rounded-xl bg-gray-800/30">
                    <Users className="mx-auto h-10 w-10 text-gray-600 mb-2" />
                    <p className="text-gray-500 font-medium">No cast members defined yet.</p>
                    <p className="text-xs text-gray-600">Add a character to ensure visual consistency.</p>
                 </div>
               )}

               {settings.characters.map((char) => (
                 <CharacterCard 
                   key={char.id}
                   character={char}
                   updateCharacter={updateCharacter}
                   removeCharacter={removeCharacter}
                   onImageUpload={handleCharacterImageUpload}
                   analyzingCharId={analyzingCharId}
                   charError={charError}
                   disabled={disabled}
                 />
               ))}
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

const CheckIcon = () => (
  <svg className="w-3 h-3 text-green-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
  </svg>
);

