import React, { useState } from 'react';
import { Upload, X, Check, AlertCircle } from 'lucide-react';

interface ProjectImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (jsonString: string) => boolean;
}

export const ProjectImportModal: React.FC<ProjectImportModalProps> = ({ isOpen, onClose, onImport }) => {
  const [jsonInput, setJsonInput] = useState('');
  const [error, setError] = useState<string | null>(null);

  if (!isOpen) return null;

  const handleImportClick = () => {
    setError(null);
    if (!jsonInput.trim()) return;

    const success = onImport(jsonInput);
    if (success) {
      setJsonInput('');
      onClose();
    } else {
      setError("Invalid JSON format. Please ensure all required fields (script, globalStyle) are present.");
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-[#1e293b] border border-gray-700 rounded-xl w-full max-w-2xl shadow-2xl flex flex-col max-h-[90vh]">
        <div className="flex justify-between items-center p-4 border-b border-gray-700">
          <h3 className="text-lg font-bold text-white flex items-center gap-2">
            <Upload size={20} className="text-blue-400" /> Import Project
          </h3>
          <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors">
            <X size={20} />
          </button>
        </div>

        <div className="p-6 flex-1 overflow-y-auto">
          <div className="bg-blue-900/20 border border-blue-800 rounded-lg p-3 mb-4">
             <p className="text-sm text-blue-200">
               <strong>Pro Tip:</strong> Ask an LLM (Gemini/ChatGPT) to "Generate a full video project plan JSON" and paste it here to instantly configure the entire app.
             </p>
          </div>

          <textarea
            value={jsonInput}
            onChange={(e) => setJsonInput(e.target.value)}
            placeholder='{ 
  "script": "Narrator: In a world...", 
  "pacing": "8s",
  "globalStyle": { "visualStyle": "Cinematic", ... }, 
  "characters": [] 
}'
            className="w-full h-64 bg-[#0f172a] border border-gray-600 rounded-lg p-4 font-mono text-xs text-green-400 placeholder-gray-600 focus:outline-none focus:border-blue-500 resize-none leading-relaxed"
          />

          {error && (
            <div className="mt-4 p-3 bg-red-900/20 border border-red-800 rounded-lg flex items-center gap-2 text-red-200 text-sm">
              <AlertCircle size={16} />
              {error}
            </div>
          )}
        </div>

        <div className="p-4 border-t border-gray-700 bg-[#1a202c] rounded-b-xl flex justify-end gap-3">
          <button 
            onClick={onClose}
            className="px-4 py-2 text-gray-300 hover:text-white font-medium text-sm"
          >
            Cancel
          </button>
          <button 
            onClick={handleImportClick}
            disabled={!jsonInput.trim()}
            className="px-6 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-lg font-bold text-sm shadow-lg shadow-blue-900/50 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
          >
            <Check size={16} /> Load Data
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { StyleEngine } from './components/StyleEngine';
import { MetricsDisplay } from './components/MetricsDisplay';
import { PromptCard } from './components/PromptCard';
import { ExportActions } from './components/ExportActions';
import { ProjectImportModal } from './components/ProjectImportModal';
import { geminiService } from './services/geminiService';
import { StyleSettings, ScriptMetrics, GeneratedClip, GenerationStatus, ClipDuration, GenerationProgress, ProjectExportData } from './types';
import { DEFAULT_SETTINGS, CLIP_DURATIONS, BATCH_SIZE } from './constants';
import { Sparkles, Play, AlertCircle, Video, Loader2, CheckCircle, RotateCcw, ArrowDownCircle, Clock, Download, Upload } from 'lucide-react';

const App: React.FC = () => {
  const [script, setScript] = useState('');
  const [settings, setSettings] = useState<StyleSettings>(DEFAULT_SETTINGS);
  const [clipDuration, setClipDuration] = useState<ClipDuration>(8);

  // UI State
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [showToast, setShowToast] = useState<string | null>(null);

  // Generation State
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [clips, setClips] = useState<GeneratedClip[]>([]);
  const [scriptChunks, setScriptChunks] = useState<string[]>([]);
  const [progress, setProgress] = useState<GenerationProgress>({ current: 0, total: 0, currentStep: '' });
  const [estTimeRemaining, setEstTimeRemaining] = useState<string>('--:--');

  // State for individual clip regeneration
  const [regeneratingIds, setRegeneratingIds] = useState<Set<string>>(new Set());

  // Tracks the index of the next clip to be generated.
  const [nextClipIndex, setNextClipIndex] = useState(0);

  // Refs for control and scrolling
  const stopGenerationRef = useRef(false);
  const bottomRef = useRef<HTMLDivElement>(null);

  // Refs for ETR calculation
  const sessionStartTimeRef = useRef<number>(0);
  const itemsProcessedInSessionRef = useRef<number>(0);

  const [metrics, setMetrics] = useState<ScriptMetrics>({
    wordCount: 0,
    estimatedDurationMinutes: 0,
    estimatedClipCount: 0
  });

  // Calculate metrics
  useEffect(() => {
    const trimmed = script.trim();
    if (!trimmed) {
      setMetrics({ wordCount: 0, estimatedDurationMinutes: 0, estimatedClipCount: 0 });
      return;
    }
    const words = trimmed.split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;
    const wordsPerSec = 3; 
    const totalDurationSeconds = wordCount / wordsPerSec;
    const durationMins = totalDurationSeconds / 60;
    const estClips = Math.ceil(totalDurationSeconds / clipDuration);

    setMetrics({
      wordCount,
      estimatedDurationMinutes: durationMins,
      estimatedClipCount: estClips
    });
  }, [script, clipDuration]);

  // Toast Timer
  useEffect(() => {
    if (showToast) {
      const timer = setTimeout(() => setShowToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [showToast]);

  // Auto-scroll
  useEffect(() => {
    if (status === GenerationStatus.GENERATING && clips.length > 0) {
      bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [clips.length, status]);

  const formatTime = (ms: number) => {
    if (!isFinite(ms) || ms < 0) return '--:--';
    const totalSeconds = Math.floor(ms / 1000);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}m ${seconds.toString().padStart(2, '0')}s`;
  };

  const handleRegenerateClip = async (clipId: string, instruction: string) => {
    const clipToRegenerate = clips.find(c => c.id === clipId);
    if (!clipToRegenerate) return;

    setRegeneratingIds(prev => new Set(prev).add(clipId));

    try {
      const updatedClip = await geminiService.regenerateClip(clipToRegenerate, settings, instruction);
      setClips(prevClips => prevClips.map(c => c.id === clipId ? updatedClip : c));
    } catch (error) {
      console.error("Failed to regenerate clip", error);
    } finally {
      setRegeneratingIds(prev => {
        const next = new Set(prev);
        next.delete(clipId);
        return next;
      });
    }
  };

  // --- PROJECT IMPORT / EXPORT LOGIC ---

  const handleExportProject = () => {
    const { characters, ...globalStyle } = settings;
    const exportData: ProjectExportData = {
      script,
      pacing: `${clipDuration}s`,
      globalStyle,
      characters
    };

    const jsonString = JSON.stringify(exportData, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `project_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setShowToast("✅ Project exported successfully!");
  };

  const handleImportProject = (jsonString: string): boolean => {
    try {
      const data = JSON.parse(jsonString);

      // Basic Validation
      if (!data.globalStyle) return false;

      // 1. Script
      if (typeof data.script === 'string') setScript(data.script);

      // 2. Pacing (Handle "8s" or 8)
      if (data.pacing) {
        const pacingVal = parseInt(String(data.pacing).replace('s', ''));
        if (CLIP_DURATIONS.includes(pacingVal as any)) {
          setClipDuration(pacingVal as ClipDuration);
        }
      }

      // 3. Settings (Merge globalStyle + characters)
      const newSettings: StyleSettings = {
        ...DEFAULT_SETTINGS, // start with defaults
        ...data.globalStyle,
        characters: Array.isArray(data.characters) ? data.characters : []
      };
      setSettings(newSettings);

      setShowToast("✅ Project auto-filled successfully!");
      return true;
    } catch (e) {
      console.error("Import failed", e);
      return false;
    }
  };

  // --- BATCH GENERATION LOGIC ---

  const processScriptQueue = async (startIndex: number, endIndex: number, chunks: string[]) => {
    if (stopGenerationRef.current) return;

    if (startIndex >= endIndex) {
      if (endIndex === chunks.length) {
        setStatus(GenerationStatus.SUCCESS);
        setProgress(prev => ({ ...prev, current: chunks.length, currentStep: 'Generation Complete!' }));
        setEstTimeRemaining('0m 00s');
      } else {
        setStatus(GenerationStatus.WAITING_APPROVAL);
      }
      return;
    }

    const batchLimit = Math.min(startIndex + BATCH_SIZE, endIndex);
    const currentBatchNumber = Math.floor(startIndex / BATCH_SIZE) + 1;
    const isPhase1 = endIndex <= 10;
    const phaseLabel = isPhase1 ? "Phase 1: Test Run" : "Phase 3: Full Run";

    setStatus(GenerationStatus.GENERATING);
    setErrorMsg(null);

    for (let i = startIndex; i < batchLimit; i++) {
      if (stopGenerationRef.current) break;

      const clipNum = i + 1;
      setProgress(prev => ({ 
        ...prev, 
        current: i, 
        currentStep: `${phaseLabel} - Batch ${currentBatchNumber} (Clip ${clipNum}/${chunks.length})` 
      }));

      try {
        if (!clips.find(c => c.clipNumber === clipNum)) {
          const newClip = await geminiService.generateSingleClip(chunks[i], clipNum, settings);
          setClips(prev => [...prev, newClip]);

          itemsProcessedInSessionRef.current += 1;
          const elapsed = Date.now() - sessionStartTimeRef.current;
          const avgTimePerClip = elapsed / itemsProcessedInSessionRef.current;
          const remainingClips = endIndex - (i + 1);
          const estimatedRemainingMs = avgTimePerClip * remainingClips;
          setEstTimeRemaining(formatTime(estimatedRemainingMs));
        }
        setNextClipIndex(i + 1);

      } catch (err: any) {
        console.error("Batch Error:", err);
        stopGenerationRef.current = true;
        setStatus(GenerationStatus.ERROR);
        setErrorMsg(`Failed at Batch ${currentBatchNumber} (Clip ${clipNum}). Error: ${err.message || 'API Error'}`);
        return; 
      }
    }

    if (!stopGenerationRef.current) {
      setTimeout(() => {
        processScriptQueue(batchLimit, endIndex, chunks);
      }, 100);
    }
  };

  const startSessionTracking = () => {
    sessionStartTimeRef.current = Date.now();
    itemsProcessedInSessionRef.current = 0;
    setEstTimeRemaining('Calculating...');
  };

  const handleInitialGenerate = async () => {
    if (!script.trim()) return;

    setClips([]);
    setErrorMsg(null);
    setNextClipIndex(0);
    setStatus(GenerationStatus.PREPARING);
    stopGenerationRef.current = false;
    startSessionTracking();

    const chunks = geminiService.splitScriptToChunks(script, clipDuration);
    setScriptChunks(chunks);
    setProgress({ current: 0, total: chunks.length, currentStep: 'Analyzing Script Structure...' });

    const firstBatchEnd = chunks.length <= 10 ? chunks.length : 10;
    await processScriptQueue(0, firstBatchEnd, chunks);
  };

  const handleApproveAndContinue = async () => {
    if (status !== GenerationStatus.WAITING_APPROVAL && status !== GenerationStatus.ERROR) return;
    stopGenerationRef.current = false;
    startSessionTracking();
    await processScriptQueue(nextClipIndex, scriptChunks.length, scriptChunks);
  };

  const handleRetry = async () => {
    if (status !== GenerationStatus.ERROR) return;
    stopGenerationRef.current = false;
    startSessionTracking();

    const isTestBatchPhase = scriptChunks.length > 10 && nextClipIndex < 10;
    const targetEnd = isTestBatchPhase ? 10 : scriptChunks.length;

    await processScriptQueue(nextClipIndex, targetEnd, scriptChunks);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-gray-200 pb-20 relative">
      {/* Toast Notification */}
      {showToast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-green-600 text-white px-6 py-3 rounded-full shadow-2xl font-bold flex items-center gap-2 animate-in fade-in slide-in-from-top-4">
          <CheckCircle size={20} /> {showToast}
        </div>
      )}

      {/* Import Modal */}
      <ProjectImportModal 
        isOpen={isImportModalOpen} 
        onClose={() => setIsImportModalOpen(false)}
        onImport={handleImportProject}
      />

      {/* Navbar / Header */}
      <header className="bg-[#0f172a]/80 backdrop-blur-md border-b border-gray-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-900/50">
              <Sparkles className="text-white w-6 h-6" />
            </div>
            <h1 className="text-2xl font-bold text-white tracking-tight">
              Video Script to <span className="text-blue-500">Prompt Elite 2.0</span>
            </h1>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsImportModalOpen(true)}
              disabled={status === GenerationStatus.GENERATING}
              className="flex items-center gap-2 px-3 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 text-xs font-bold rounded-lg border border-gray-700 transition-colors disabled:opacity-50"
            >
              <Upload size={14} /> Import Project
            </button>
            <button 
              onClick={handleExportProject}
              className="flex items-center gap-2 px-3 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 text-xs font-bold rounded-lg border border-gray-700 transition-colors"
            >
              <Download size={14} /> Export Project
            </button>
            <div className="w-px h-6 bg-gray-700 mx-1 hidden sm:block"></div>
            <div className="text-sm text-gray-500 hidden sm:block font-medium">
              Powered by Gemini 2.5
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-10 space-y-10">

        {/* Style Engine Panel */}
        <section>
          <StyleEngine 
            settings={settings} 
            setSettings={setSettings} 
            disabled={status === GenerationStatus.GENERATING}
          />
        </section>

        {/* Input & Output Grid */}
        <section className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Left Column: Input */}
          <div className="lg:col-span-1 space-y-6">
            <div className="sticky top-28 space-y-6">

              {/* Script Input Box */}
              <div className="space-y-2">
                <div className="flex justify-between items-center">
                  <label className="text-sm font-bold text-gray-300 uppercase tracking-wider">Input Script</label>
                  <button 
                    onClick={() => {
                      setScript('');
                      setClips([]);
                      setStatus(GenerationStatus.IDLE);
                      setNextClipIndex(0);
                      setEstTimeRemaining('--:--');
                    }}
                    className="text-xs text-red-400 hover:text-red-300 transition-colors"
                  >
                    Clear & Reset
                  </button>
                </div>

                <div className="relative">
                  <textarea
                    value={script}
                    onChange={(e) => setScript(e.target.value)}
                    placeholder="Paste your video script here... (Supports 400+ clips)"
                    className="w-full h-[400px] bg-[#1e293b] border border-gray-700 rounded-xl p-4 text-gray-200 placeholder-gray-500 focus:ring-2 focus:ring-blue-600 focus:border-transparent transition-all resize-none font-mono text-sm leading-relaxed"
                    disabled={status === GenerationStatus.GENERATING}
                  />

                  {/* Generate Button Overlay */}
                  <div className="absolute bottom-4 right-4 left-4">
                    {status === GenerationStatus.IDLE || status === GenerationStatus.SUCCESS || status === GenerationStatus.ERROR ? (
                       <button
                       onClick={handleInitialGenerate}
                       disabled={!script.trim()}
                       className={`w-full py-4 rounded-lg flex items-center justify-center gap-2 font-bold text-lg shadow-xl transition-all transform active:scale-95 ${
                         !script.trim()
                           ? 'bg-gray-700 text-gray-500 cursor-not-allowed'
                           : 'bg-[#3b82f6] hover:bg-blue-600 text-white shadow-blue-900/50 hover:shadow-blue-700/50'
                       }`}
                     >
                       <Play fill="currentColor" size={20} />
                       {clips.length > 0 ? "RESTART GENERATION" : "GENERATE PROMPTS"}
                     </button>
                    ) : null}
                  </div>
                </div>
              </div>

              {/* Clip Duration Selector */}
              <div className="bg-[#1e293b] border border-gray-700 rounded-xl p-4">
                <label className="text-xs font-bold text-gray-400 uppercase tracking-wider block mb-3">Seconds per Clip</label>
                <div className="flex justify-between gap-2">
                  {CLIP_DURATIONS.map(dur => (
                    <button
                      key={dur}
                      onClick={() => setClipDuration(dur as ClipDuration)}
                      disabled={status === GenerationStatus.GENERATING}
                      className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${
                        clipDuration === dur 
                          ? 'bg-blue-600 text-white shadow-lg' 
                          : 'bg-[#0f172a] text-gray-400 hover:text-white border border-gray-700 hover:border-gray-500'
                      }`}
                    >
                      {dur}s
                    </button>
                  ))}
                </div>
              </div>

              <MetricsDisplay metrics={metrics} />
            </div>
          </div>

          {/* Right Column: Output */}
          <div className="lg:col-span-2 space-y-6">
             <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-gray-800 pb-4">
                <div className="flex items-center gap-3">
                  <h2 className="text-xl font-bold text-white">Generated Output</h2>
                  {clips.length > 0 && (
                    <span className="bg-green-900/30 text-green-400 px-3 py-1 rounded-full text-xs font-semibold border border-green-800 animate-pulse">
                      {clips.length} / {progress.total > 0 ? progress.total : metrics.estimatedClipCount} Clips
                    </span>
                  )}
                </div>

                {/* Export is always available if we have clips, even during error/generation */}
                <ExportActions clips={clips} settings={settings} />
             </div>

            {/* REAL-TIME PROGRESS BAR & ERROR BOX */}
            {(status === GenerationStatus.GENERATING || status === GenerationStatus.WAITING_APPROVAL || status === GenerationStatus.ERROR || status === GenerationStatus.PREPARING) && (
              <div className={`border rounded-xl p-4 shadow-lg transition-all duration-300 ${status === GenerationStatus.ERROR ? 'bg-red-900/10 border-red-800' : 'bg-[#1e293b] border-gray-700'}`}>

                <div className="flex justify-between items-end mb-2">
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      {status === GenerationStatus.GENERATING && <Loader2 className="animate-spin text-blue-400" size={16} />}
                      {status === GenerationStatus.ERROR && <AlertCircle className="text-red-500" size={16} />}
                      <span className={`text-sm font-bold ${status === GenerationStatus.ERROR ? 'text-red-400' : 'text-blue-300'}`}>
                        {status === GenerationStatus.ERROR ? "Generation Interrupted" : progress.currentStep}
                      </span>
                    </div>
                    {status === GenerationStatus.GENERATING && (
                      <div className="flex items-center gap-2 text-xs text-gray-400">
                         <Clock size={12} />
                         <span>Est. Remaining: <span className="text-white font-mono">{estTimeRemaining}</span></span>
                      </div>
                    )}
                  </div>
                  <span className="text-xs text-gray-500 font-mono">
                    {Math.round((clips.length / (progress.total || 1)) * 100)}%
                  </span>
                </div>

                {/* Progress Line */}
                <div className="w-full bg-gray-700 rounded-full h-2.5 overflow-hidden">
                  <div 
                    className={`h-2.5 rounded-full transition-all duration-300 ease-linear ${
                      status === GenerationStatus.ERROR ? 'bg-red-500' : 'bg-blue-500'
                    }`}
                    style={{ width: `${(clips.length / (progress.total || 1)) * 100}%` }}
                  ></div>
                </div>

                {/* ERROR STATE: THE "RED BOX" */}
                {status === GenerationStatus.ERROR && (
                  <div className="mt-4 flex flex-col md:flex-row items-center justify-between bg-red-950/40 border border-red-500/30 p-4 rounded-lg gap-4">
                    <div className="text-red-200 text-sm">
                      <p className="font-bold mb-1">❌ Failed at Batch {Math.ceil(nextClipIndex / BATCH_SIZE)}</p>
                      <p className="font-mono text-xs opacity-80">{errorMsg}</p>
                    </div>
                    <button 
                      onClick={handleRetry}
                      className="px-4 py-2 bg-red-600 hover:bg-red-500 text-white text-sm font-bold rounded-lg shadow-lg flex items-center gap-2 whitespace-nowrap transition-transform active:scale-95"
                    >
                      <RotateCcw size={16} /> Retry from Clip {nextClipIndex}
                    </button>
                  </div>
                )}
              </div>
            )}

             {status === GenerationStatus.IDLE && clips.length === 0 && (
               <div className="h-[400px] flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl bg-[#1e293b]/50">
                 <Video size={48} className="mb-4 opacity-50" />
                 <p className="text-lg font-medium text-gray-400">Ready to generate.</p>
                 <p className="text-sm text-gray-500">Supports high-volume scripts (400+ clips).</p>
               </div>
             )}

            <div className="grid grid-cols-1 gap-6">
              {clips.map((clip) => (
                <PromptCard 
                  key={clip.id} 
                  clip={clip} 
                  onRegenerate={handleRegenerateClip}
                  isRegenerating={regeneratingIds.has(clip.id)}
                />
              ))}
              <div ref={bottomRef} className="h-4" />
            </div>

            {status === GenerationStatus.WAITING_APPROVAL && (
              <div className="sticky bottom-6 z-20">
                <div className="bg-[#1e293b] border border-blue-500/50 p-4 rounded-xl shadow-2xl shadow-black/50 flex flex-col items-center gap-3 backdrop-blur-sm">
                  <div className="text-center">
                    <h3 className="text-white font-bold text-lg">Test Batch Complete (1-10)</h3>
                    <p className="text-gray-400 text-sm">Review the first 10 clips above. If satisfied, continue generating the rest.</p>
                  </div>
                  <button 
                    onClick={handleApproveAndContinue}
                    className="w-full md:w-auto px-8 py-3 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg shadow-lg shadow-green-900/50 flex items-center justify-center gap-2 transition-all transform hover:scale-105"
                  >
                    <CheckCircle size={20} />
                    APPROVE & GENERATE REMAINING {scriptChunks.length - 10} CLIPS
                  </button>
                </div>
              </div>
            )}

            {status === GenerationStatus.GENERATING && (
              <div className="opacity-50 pointer-events-none animate-pulse flex flex-col items-center gap-2">
                <div className="bg-[#1e293b] w-full h-32 rounded-xl border border-gray-700/50 p-6 flex flex-col gap-3">
                   <div className="h-4 bg-gray-700 rounded w-1/4"></div>
                   <div className="h-4 bg-gray-700 rounded w-3/4"></div>
                </div>
                <span className="text-xs text-blue-400 flex items-center gap-1">
                   <ArrowDownCircle size={12} /> Auto-scrolling enabled
                </span>
              </div>
            )}
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

