        <div className="p-4 border-t border-gray-700 bg-[#1a202c] rounded-b-xl flex justify-end gap-3">
          <button 
            onClick={onClose}
            className="px-4 py-2 text-gray-300 hover:text-white font-medium text-sm"
          >
            Cancel
          </button>
          <button 
            onClick={handleImportClick}
            disabled={!jsonInput.trim()}
            className="px-6 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-lg font-bold text-sm shadow-lg shadow-blue-900/50 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
          >
            <Check size={16} /> Load Data
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { StyleEngine } from './components/StyleEngine';
import { MetricsDisplay } from './components/MetricsDisplay';
import { PromptCard } from './components/PromptCard';
import { ExportActions } from './components/ExportActions';
import { ProjectImportModal } from './components/ProjectImportModal';
import { geminiService } from './services/geminiService';
import { StyleSettings, ScriptMetrics, GeneratedClip, GenerationStatus, ClipDuration, GenerationProgress, ProjectExportData, OutputFormat } from './types';
import { DEFAULT_SETTINGS, CLIP_DURATIONS, BATCH_SIZE } from './constants';
import { Sparkles, Play, AlertCircle, Video, Loader2, CheckCircle, RotateCcw, ArrowDownCircle, Clock, Download, Upload, FileJson, FileText } from 'lucide-react';

const App: React.FC = () => {
  const [script, setScript] = useState('');
  const [settings, setSettings] = useState<StyleSettings>(DEFAULT_SETTINGS);
  const [clipDuration, setClipDuration] = useState<ClipDuration>(8);
  const [outputFormat, setOutputFormat] = useState<OutputFormat>('standard');

  // UI State
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [showToast, setShowToast] = useState<string | null>(null);

  // Generation State
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [clips, setClips] = useState<GeneratedClip[]>([]);
  const [scriptChunks, setScriptChunks] = useState<string[]>([]);
  const [progress, setProgress] = useState<GenerationProgress>({ current: 0, total: 0, currentStep: '' });
  const [estTimeRemaining, setEstTimeRemaining] = useState<string>('--:--');

  // State for individual clip regeneration
  const [regeneratingIds, setRegeneratingIds] = useState<Set<string>>(new Set());

  // Tracks the index of the next clip to be generated.
  const [nextClipIndex, setNextClipIndex] = useState(0);

  // Refs for control and scrolling
  const stopGenerationRef = useRef(false);
  const bottomRef = useRef<HTMLDivElement>(null);

  // Refs for ETR calculation
  const sessionStartTimeRef = useRef<number>(0);
  const itemsProcessedInSessionRef = useRef<number>(0);

  const [metrics, setMetrics] = useState<ScriptMetrics>({
    wordCount: 0,
    estimatedDurationMinutes: 0,
    estimatedClipCount: 0
  });

  // Calculate metrics
  useEffect(() => {
    const trimmed = script.trim();
    if (!trimmed) {
      setMetrics({ wordCount: 0, estimatedDurationMinutes: 0, estimatedClipCount: 0 });
      return;
    }
    const words = trimmed.split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;
    const wordsPerSec = 3; 
    const totalDurationSeconds = wordCount / wordsPerSec;
    const durationMins = totalDurationSeconds / 60;
    const estClips = Math.ceil(totalDurationSeconds / clipDuration);

    setMetrics({
      wordCount,
      estimatedDurationMinutes: durationMins,
      estimatedClipCount: estClips
    });
  }, [script, clipDuration]);

  // Toast Timer
  useEffect(() => {
    if (showToast) {
      const timer = setTimeout(() => setShowToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [showToast]);

  // Auto-scroll
  useEffect(() => {
    if (status === GenerationStatus.GENERATING && clips.length > 0) {
      bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [clips.length, status]);

  const formatTime = (ms: number) => {
    if (!isFinite(ms) || ms < 0) return '--:--';
    const totalSeconds = Math.floor(ms / 1000);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}m ${seconds.toString().padStart(2, '0')}s`;
  };

  const handleRegenerateClip = async (clipId: string, instruction: string) => {
    const clipToRegenerate = clips.find(c => c.id === clipId);
    if (!clipToRegenerate) return;

    setRegeneratingIds(prev => new Set(prev).add(clipId));

    try {
      const updatedClip = await geminiService.regenerateClip(clipToRegenerate, settings, instruction, outputFormat);
      setClips(prevClips => prevClips.map(c => c.id === clipId ? updatedClip : c));
    } catch (error) {
      console.error("Failed to regenerate clip", error);
    } finally {
      setRegeneratingIds(prev => {
        const next = new Set(prev);
        next.delete(clipId);
        return next;
      });
    }
  };

  // --- PROJECT IMPORT / EXPORT LOGIC ---

  const handleExportProject = () => {
    const { characters, ...globalStyle } = settings;
    const exportData: ProjectExportData = {
      script,
      pacing: `${clipDuration}s`,
      outputFormat,
      globalStyle,
      characters
    };

    const jsonString = JSON.stringify(exportData, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `project_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setShowToast("✅ Project exported successfully!");
  };

  const handleImportProject = (jsonString: string): { success: boolean; message?: string } => {
    try {
      let data: any;
      try {
        data = JSON.parse(jsonString);
      } catch (e) {
        return { success: false, message: "Invalid JSON Syntax. Check for missing commas or brackets." };
      }

      let hasUpdates = false;

      // 1. Script (Check root level and common aliases)
      const scriptVal = data.script || data.video_script || data.source_script?.text;
      if (scriptVal && typeof scriptVal === 'string') {
        setScript(scriptVal);
        hasUpdates = true;
      }

      // 2. Pacing
      const pacingVal = data.pacing || data.clip_duration || data.pacing_seconds || data.timing_data?.duration;
      if (pacingVal) {
        const cleanPacing = parseInt(String(pacingVal).replace(/s|seconds/gi, ''));
        if (CLIP_DURATIONS.includes(cleanPacing as any)) {
          setClipDuration(cleanPacing as ClipDuration);
          hasUpdates = true;
        }
      }

      // 3. Output Format
      const formatVal = data.outputFormat || data.output_format;
      if (formatVal === 'json' || formatVal === 'standard') {
        setOutputFormat(formatVal);
        hasUpdates = true;
      }

      // 4. Smart Style Mapping
      // Check for style keys at root level OR inside a nested object (globalStyle, style, style_engine_parameters)
      // We prioritize specific objects but fall back to root.
      const styleSources = [data, data.globalStyle, data.style, data.global_style, data.style_engine_parameters].filter(Boolean);

      const findKey = (candidates: string[]) => {
        for (const source of styleSources) {
          for (const key of candidates) {
            if (source[key] !== undefined && source[key] !== null) return source[key];
          }
        }
        return undefined;
      };

      const newSettings = { ...settings }; // Start with current settings to allow partial updates
      let styleUpdated = false;

      // Visual Style
      const visualStyle = findKey(['visualStyle', 'visual_style', 'VISUAL_STYLE', 'visual_aesthetic', 'aesthetic']);
      if (visualStyle) { newSettings.visualStyle = visualStyle; styleUpdated = true; }

      // Mood
      const mood = findKey(['mood', 'mood_tone', 'MOOD_&_TONE', 'atmosphere', 'emotional_beat']);
      if (mood) { newSettings.mood = mood; styleUpdated = true; }

      // Lighting
      const lighting = findKey(['lighting', 'lighting_style', 'LIGHTING_STYLE', 'lighting_setup']);
      if (lighting) { newSettings.lighting = lighting; styleUpdated = true; }

      // Camera Style
      const cameraStyle = findKey(['cameraStyle', 'camera_style', 'CAMERA_STYLE', 'camera_angle', 'camera_architecture']);
      if (typeof cameraStyle === 'object' && cameraStyle.angle) {
          newSettings.cameraStyle = cameraStyle.angle;
          styleUpdated = true;
      } else if (typeof cameraStyle === 'string') {
          newSettings.cameraStyle = cameraStyle;
          styleUpdated = true;
      }

      // Camera Movement
      const movement = findKey(['cameraMovement', 'camera_movement', 'CAMERA_MOVEMENT', 'movement']);
      // Handle the Detailed JSON structure where movement is inside camera_architecture
      const deepMovement = data.style_engine_parameters?.camera_architecture?.movement;
      if (deepMovement) {
         newSettings.cameraMovement = deepMovement;
         styleUpdated = true;
      } else if (movement) {
         newSettings.cameraMovement = movement;
         styleUpdated = true;
      }

      // Art Keywords
      const keywords = findKey(['artKeywords', 'art_keywords', 'keywords', 'texture_keywords']);
      if (keywords) {
        newSettings.artKeywords = Array.isArray(keywords) ? keywords.join(', ') : keywords;
        styleUpdated = true;
      }

      // Color Palette
      const palette = findKey(['colorPalette', 'color_palette', 'COLOR_PALETTE', 'colors', 'color_grading']);
      if (palette && typeof palette === 'object') {
        newSettings.colorPalette = {
          primary: palette.primary || palette.hex_1 || newSettings.colorPalette.primary,
          secondary: palette.secondary || palette.hex_2 || newSettings.colorPalette.secondary,
          accent: palette.accent || palette.hex_3 || newSettings.colorPalette.accent
        };
        styleUpdated = true;
      }

      // Characters
      const chars = findKey(['characters', 'cast', 'character_profiles']);
      if (Array.isArray(chars)) {
        newSettings.characters = chars;
        styleUpdated = true;
      }

      if (styleUpdated) {
        setSettings(newSettings);
        hasUpdates = true;
      }

      if (hasUpdates) {
        setShowToast("✅ Project updated successfully!");
        return { success: true };
      } else {
        const detectedKeys = Object.keys(data).slice(0, 5).join(", ");
        return { 
          success: false, 
          message: `JSON parsed, but no recognizable fields were found. Detected keys: [${detectedKeys}...]` 
        };
      }
    } catch (e: any) {
      console.error("Import failed", e);
      return { success: false, message: "Unknown import error: " + e.message };
    }
  };

  // --- BATCH GENERATION LOGIC ---

  const processScriptQueue = async (startIndex: number, endIndex: number, chunks: string[]) => {
    if (stopGenerationRef.current) return;

    if (startIndex >= endIndex) {
      if (endIndex === chunks.length) {
        setStatus(GenerationStatus.SUCCESS);
        setProgress(prev => ({ ...prev, current: chunks.length, currentStep: 'Generation Complete!' }));
        setEstTimeRemaining('0m 00s');
      } else {
        setStatus(GenerationStatus.WAITING_APPROVAL);
      }
      return;
    }

    const batchLimit = Math.min(startIndex + BATCH_SIZE, endIndex);
    const currentBatchNumber = Math.floor(startIndex / BATCH_SIZE) + 1;
    const isPhase1 = endIndex <= 10;
    const phaseLabel = isPhase1 ? "Phase 1: Test Run" : "Phase 3: Full Run";

    setStatus(GenerationStatus.GENERATING);
    setErrorMsg(null);

    for (let i = startIndex; i < batchLimit; i++) {
      if (stopGenerationRef.current) break;

      const clipNum = i + 1;
      setProgress(prev => ({ 
        ...prev, 
        current: i, 
        currentStep: `${phaseLabel} - Batch ${currentBatchNumber} (Clip ${clipNum}/${chunks.length})` 
      }));

      try {
        if (!clips.find(c => c.clipNumber === clipNum)) {
          const newClip = await geminiService.generateSingleClip(chunks[i], clipNum, settings, clipDuration, outputFormat);
          setClips(prev => [...prev, newClip]);

          itemsProcessedInSessionRef.current += 1;
          const elapsed = Date.now() - sessionStartTimeRef.current;
          const avgTimePerClip = elapsed / itemsProcessedInSessionRef.current;
          const remainingClips = endIndex - (i + 1);
          const estimatedRemainingMs = avgTimePerClip * remainingClips;
          setEstTimeRemaining(formatTime(estimatedRemainingMs));
        }
        setNextClipIndex(i + 1);

      } catch (err: any) {
        console.error("Batch Error:", err);
        stopGenerationRef.current = true;
        setStatus(GenerationStatus.ERROR);
        setErrorMsg(`Failed at Batch ${currentBatchNumber} (Clip ${clipNum}). Error: ${err.message || 'API Error'}`);
        return; 
      }
    }

    if (!stopGenerationRef.current) {
      setTimeout(() => {
        processScriptQueue(batchLimit, endIndex, chunks);
      }, 100);
    }
  };

  const startSessionTracking = () => {
    sessionStartTimeRef.current = Date.now();
    itemsProcessedInSessionRef.current = 0;
    setEstTimeRemaining('Calculating...');
  };

  const handleInitialGenerate = async () => {
    if (!script.trim()) return;

    setClips([]);
    setErrorMsg(null);
    setNextClipIndex(0);
    setStatus(GenerationStatus.PREPARING);
    stopGenerationRef.current = false;
    startSessionTracking();

    const chunks = geminiService.splitScriptToChunks(script, clipDuration);
    setScriptChunks(chunks);
    setProgress({ current: 0, total: chunks.length, currentStep: 'Analyzing Script Structure...' });

    const firstBatchEnd = chunks.length <= 10 ? chunks.length : 10;
    await processScriptQueue(0, firstBatchEnd, chunks);
  };

  const handleApproveAndContinue = async () => {
    if (status !== GenerationStatus.WAITING_APPROVAL && status !== GenerationStatus.ERROR) return;
    stopGenerationRef.current = false;
    startSessionTracking();
    await processScriptQueue(nextClipIndex, scriptChunks.length, scriptChunks);
  };

  const handleRetry = async () => {
    if (status !== GenerationStatus.ERROR) return;
    stopGenerationRef.current = false;
    startSessionTracking();

    const isTestBatchPhase = scriptChunks.length > 10 && nextClipIndex < 10;
    const targetEnd = isTestBatchPhase ? 10 : scriptChunks.length;

    await processScriptQueue(nextClipIndex, targetEnd, scriptChunks);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-gray-200 pb-20 relative">
      {/* Toast Notification */}
      {showToast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-green-600 text-white px-6 py-3 rounded-full shadow-2xl font-bold flex items-center gap-2 animate-in fade-in slide-in-from-top-4">
          <CheckCircle size={20} /> {showToast}
        </div>
      )}

      {/* Import Modal */}
      <ProjectImportModal 
        isOpen={isImportModalOpen} 
        onClose={() => setIsImportModalOpen(false)}
        onImport={handleImportProject}
      />

      {/* Navbar / Header */}
      <header className="bg-[#0f172a]/80 backdrop-blur-md border-b border-gray-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-900/50">
              <Sparkles className="text-white w-6 h-6" />
            </div>
            <h1 className="text-2xl font-bold text-white tracking-tight">
              Video Script to <span className="text-blue-500">Prompt Elite 2.0</span>
            </h1>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsImportModalOpen(true)}
              disabled={status === GenerationStatus.GENERATING}
              className="flex items-center gap-2 px-3 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 text-xs font-bold rounded-lg border border-gray-700 transition-colors disabled:opacity-50"
            >
              <Upload size={14} /> Import Project
            </button>
            <button 
              onClick={handleExportProject}
              className="flex items-center gap-2 px-3 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 text-xs font-bold rounded-lg border border-gray-700 transition-colors"
            >
              <Download size={14} /> Export Project
            </button>
            <div className="w-px h-6 bg-gray-700 mx-1 hidden sm:block"></div>
            <div className="text-sm text-gray-500 hidden sm:block font-medium">
              Powered by Gemini 2.5
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-10 space-y-10">

        {/* Style Engine Panel */}
        <section>
          <StyleEngine 
            settings={settings} 
            setSettings={setSettings} 
            disabled={status === GenerationStatus.GENERATING}
          />
        </section>

        {/* Input & Output Grid */}
        <section className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Left Column: Input */}
          <div className="lg:col-span-1 space-y-6">
            <div className="sticky top-28 space-y-6">

              {/* Script Input Box */}
              <div className="space-y-2">
                <div className="flex justify-between items-center">
                  <label className="text-sm font-bold text-gray-300 uppercase tracking-wider">Input Script</label>
                  <button 
                    onClick={() => {
                      setScript('');
                      setClips([]);
                      setStatus(GenerationStatus.IDLE);
                      setNextClipIndex(0);
                      setEstTimeRemaining('--:--');
                    }}
                    className="text-xs text-red-400 hover:text-red-300 transition-colors"
                  >
                    Clear & Reset
                  </button>
                </div>

                <div className="relative">
                  <textarea
                    value={script}
                    onChange={(e) => setScript(e.target.value)}
                    placeholder="Paste your video script here... (Supports 400+ clips)"
                    className="w-full h-[400px] bg-[#1e293b] border border-gray-700 rounded-xl p-4 text-gray-200 placeholder-gray-500 focus:ring-2 focus:ring-blue-600 focus:border-transparent transition-all resize-none font-mono text-sm leading-relaxed"
                    disabled={status === GenerationStatus.GENERATING}
                  />

                  {/* Generate Button Overlay */}
                  <div className="absolute bottom-4 right-4 left-4">
                    {status === GenerationStatus.IDLE || status === GenerationStatus.SUCCESS || status === GenerationStatus.ERROR ? (
                       <button
                       onClick={handleInitialGenerate}
                       disabled={!script.trim()}
                       className={`w-full py-4 rounded-lg flex items-center justify-center gap-2 font-bold text-lg shadow-xl transition-all transform active:scale-95 ${
                         !script.trim()
                           ? 'bg-gray-700 text-gray-500 cursor-not-allowed'
                           : 'bg-[#3b82f6] hover:bg-blue-600 text-white shadow-blue-900/50 hover:shadow-blue-700/50'
                       }`}
                     >
                       <Play fill="currentColor" size={20} />
                       {clips.length > 0 ? "RESTART GENERATION" : "GENERATE PROMPTS"}
                     </button>
                    ) : null}
                  </div>
                </div>
              </div>

              {/* Clip Duration & Output Format Selector */}
              <div className="bg-[#1e293b] border border-gray-700 rounded-xl p-4 space-y-4">

                {/* Duration */}
                <div>
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-wider block mb-2">Seconds per Clip</label>
                  <div className="flex justify-between gap-2">
                    {CLIP_DURATIONS.map(dur => (
                      <button
                        key={dur}
                        onClick={() => setClipDuration(dur as ClipDuration)}
                        disabled={status === GenerationStatus.GENERATING}
                        className={`flex-1 py-1.5 text-xs font-semibold rounded-lg transition-all ${
                          clipDuration === dur 
                            ? 'bg-blue-600 text-white shadow-lg' 
                            : 'bg-[#0f172a] text-gray-400 hover:text-white border border-gray-700 hover:border-gray-500'
                        }`}
                      >
                        {dur}s
                      </button>
                    ))}
                  </div>
                </div>

                {/* Output Format */}
                <div>
                   <label className="text-xs font-bold text-gray-400 uppercase tracking-wider block mb-2">Output Format</label>
                   <div className="flex gap-2">
                     <button
                       onClick={() => setOutputFormat('standard')}
                       disabled={status === GenerationStatus.GENERATING}
                       className={`flex-1 py-2 rounded-lg flex items-center justify-center gap-2 text-xs font-bold transition-all border ${
                         outputFormat === 'standard' 
                         ? 'bg-blue-900/30 border-blue-500 text-blue-300' 
                         : 'bg-[#0f172a] border-gray-700 text-gray-500 hover:border-gray-500'
                       }`}
                     >
                       <FileText size={14} /> 📝 Standard
                     </button>
                     <button
                       onClick={() => setOutputFormat('json')}
                       disabled={status === GenerationStatus.GENERATING}
                       className={`flex-1 py-2 rounded-lg flex items-center justify-center gap-2 text-xs font-bold transition-all border ${
                         outputFormat === 'json' 
                         ? 'bg-purple-900/30 border-purple-500 text-purple-300' 
                         : 'bg-[#0f172a] border-gray-700 text-gray-500 hover:border-gray-500'
                       }`}
                     >
                       <FileJson size={14} /> 🤖 Detailed JSON
                     </button>
                   </div>
                </div>

              </div>

              <MetricsDisplay metrics={metrics} />
            </div>
          </div>

          {/* Right Column: Output */}
          <div className="lg:col-span-2 space-y-6">
             <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-gray-800 pb-4">
                <div className="flex items-center gap-3">
                  <h2 className="text-xl font-bold text-white">Generated Output</h2>
                  {clips.length > 0 && (
                    <span className="bg-green-900/30 text-green-400 px-3 py-1 rounded-full text-xs font-semibold border border-green-800 animate-pulse">
                      {clips.length} / {progress.total > 0 ? progress.total : metrics.estimatedClipCount} Clips
                    </span>
                  )}
                </div>

                {/* Export is always available if we have clips, even during error/generation */}
                <ExportActions clips={clips} settings={settings} />
             </div>

            {/* REAL-TIME PROGRESS BAR & ERROR BOX */}
            {(status === GenerationStatus.GENERATING || status === GenerationStatus.WAITING_APPROVAL || status === GenerationStatus.ERROR || status === GenerationStatus.PREPARING) && (
              <div className={`border rounded-xl p-4 shadow-lg transition-all duration-300 ${status === GenerationStatus.ERROR ? 'bg-red-900/10 border-red-800' : 'bg-[#1e293b] border-gray-700'}`}>

                <div className="flex justify-between items-end mb-2">
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      {status === GenerationStatus.GENERATING && <Loader2 className="animate-spin text-blue-400" size={16} />}
                      {status === GenerationStatus.ERROR && <AlertCircle className="text-red-500" size={16} />}
                      <span className={`text-sm font-bold ${status === GenerationStatus.ERROR ? 'text-red-400' : 'text-blue-300'}`}>
                        {status === GenerationStatus.ERROR ? "Generation Interrupted" : progress.currentStep}
                      </span>
                    </div>
                    {status === GenerationStatus.GENERATING && (
                      <div className="flex items-center gap-2 text-xs text-gray-400">
                         <Clock size={12} />
                         <span>Est. Remaining: <span className="text-white font-mono">{estTimeRemaining}</span></span>
                      </div>
                    )}
                  </div>
                  <span className="text-xs text-gray-500 font-mono">
                    {Math.round((clips.length / (progress.total || 1)) * 100)}%
                  </span>
                </div>

                {/* Progress Line */}
                <div className="w-full bg-gray-700 rounded-full h-2.5 overflow-hidden">
                  <div 
                    className={`h-2.5 rounded-full transition-all duration-300 ease-linear ${
                      status === GenerationStatus.ERROR ? 'bg-red-500' : 'bg-blue-500'
                    }`}
                    style={{ width: `${(clips.length / (progress.total || 1)) * 100}%` }}
                  ></div>
                </div>

                {/* ERROR STATE: THE "RED BOX" */}
                {status === GenerationStatus.ERROR && (
                  <div className="mt-4 flex flex-col md:flex-row items-center justify-between bg-red-950/40 border border-red-500/30 p-4 rounded-lg gap-4">
                    <div className="text-red-200 text-sm">
                      <p className="font-bold mb-1">❌ Failed at Batch {Math.ceil(nextClipIndex / BATCH_SIZE)}</p>
                      <p className="font-mono text-xs opacity-80">{errorMsg}</p>
                    </div>
                    <button 
                      onClick={handleRetry}
                      className="px-4 py-2 bg-red-600 hover:bg-red-500 text-white text-sm font-bold rounded-lg shadow-lg flex items-center gap-2 whitespace-nowrap transition-transform active:scale-95"
                    >
                      <RotateCcw size={16} /> Retry from Clip {nextClipIndex}
                    </button>
                  </div>
                )}
              </div>
            )}

             {status === GenerationStatus.IDLE && clips.length === 0 && (
               <div className="h-[400px] flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl bg-[#1e293b]/50">
                 <Video size={48} className="mb-4 opacity-50" />
                 <p className="text-lg font-medium text-gray-400">Ready to generate.</p>
                 <p className="text-sm text-gray-500">Supports high-volume scripts (400+ clips).</p>
               </div>
             )}

            <div className="grid grid-cols-1 gap-6">
              {clips.map((clip) => (
                <PromptCard 
                  key={clip.id} 
                  clip={clip} 
                  onRegenerate={handleRegenerateClip}
                  isRegenerating={regeneratingIds.has(clip.id)}
                />
              ))}
              <div ref={bottomRef} className="h-4" />
            </div>

            {status === GenerationStatus.WAITING_APPROVAL && (
              <div className="sticky bottom-6 z-20">
                <div className="bg-[#1e293b] border border-blue-500/50 p-4 rounded-xl shadow-2xl shadow-black/50 flex flex-col items-center gap-3 backdrop-blur-sm">
                  <div className="text-center">
                    <h3 className="text-white font-bold text-lg">Test Batch Complete (1-10)</h3>
                    <p className="text-gray-400 text-sm">Review the first 10 clips above. If satisfied, continue generating the rest.</p>
                  </div>
                  <button 
                    onClick={handleApproveAndContinue}
                    className="w-full md:w-auto px-8 py-3 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg shadow-lg shadow-green-900/50 flex items-center justify-center gap-2 transition-all transform hover:scale-105"
                  >
                    <CheckCircle size={20} />
                    APPROVE & GENERATE REMAINING {scriptChunks.length - 10} CLIPS
                  </button>
                </div>
              </div>
            )}

            {status === GenerationStatus.GENERATING && (
              <div className="opacity-50 pointer-events-none animate-pulse flex flex-col items-center gap-2">
                <div className="bg-[#1e293b] w-full h-32 rounded-xl border border-gray-700/50 p-6 flex flex-col gap-3">
                   <div className="h-4 bg-gray-700 rounded w-1/4"></div>
                   <div className="h-4 bg-gray-700 rounded w-3/4"></div>
                </div>
                <span className="text-xs text-blue-400 flex items-center gap-1">
                   <ArrowDownCircle size={12} /> Auto-scrolling enabled
                </span>
              </div>
            )}
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { StyleEngine } from './components/StyleEngine';
import { MetricsDisplay } from './components/MetricsDisplay';
import { PromptCard } from './components/PromptCard';
import { ExportActions } from './components/ExportActions';
import { ProjectImportModal } from './components/ProjectImportModal';
import { geminiService } from './services/geminiService';
import { StyleSettings, ScriptMetrics, GeneratedClip, GenerationStatus, ClipDuration, GenerationProgress, ProjectExportData, OutputFormat } from './types';
import { DEFAULT_SETTINGS, CLIP_DURATIONS, BATCH_SIZE } from './constants';
import { Sparkles, Play, AlertCircle, Video, Loader2, CheckCircle, RotateCcw, ArrowDownCircle, Clock, Download, Upload, FileJson, FileText } from 'lucide-react';

const App: React.FC = () => {
  const [script, setScript] = useState('');
  const [settings, setSettings] = useState<StyleSettings>(DEFAULT_SETTINGS);
  const [clipDuration, setClipDuration] = useState<ClipDuration>(8);
  const [outputFormat, setOutputFormat] = useState<OutputFormat>('standard');

  // UI State
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [showToast, setShowToast] = useState<string | null>(null);

  // Generation State
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [clips, setClips] = useState<GeneratedClip[]>([]);
  const [scriptChunks, setScriptChunks] = useState<string[]>([]);
  const [progress, setProgress] = useState<GenerationProgress>({ current: 0, total: 0, currentStep: '' });
  const [estTimeRemaining, setEstTimeRemaining] = useState<string>('--:--');

  // State for individual clip regeneration
  const [regeneratingIds, setRegeneratingIds] = useState<Set<string>>(new Set());

  // Tracks the index of the next clip to be generated.
  const [nextClipIndex, setNextClipIndex] = useState(0);

  // Refs for control and scrolling
  const stopGenerationRef = useRef(false);
  const bottomRef = useRef<HTMLDivElement>(null);

  // Refs for ETR calculation
  const sessionStartTimeRef = useRef<number>(0);
  const itemsProcessedInSessionRef = useRef<number>(0);

  const [metrics, setMetrics] = useState<ScriptMetrics>({
    wordCount: 0,
    estimatedDurationMinutes: 0,
    estimatedClipCount: 0
  });

  // Calculate metrics
  useEffect(() => {
    const trimmed = script.trim();
    if (!trimmed) {
      setMetrics({ wordCount: 0, estimatedDurationMinutes: 0, estimatedClipCount: 0 });
      return;
    }
    const words = trimmed.split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;
    const wordsPerSec = 3; 
    const totalDurationSeconds = wordCount / wordsPerSec;
    const durationMins = totalDurationSeconds / 60;
    const estClips = Math.ceil(totalDurationSeconds / clipDuration);

    setMetrics({
      wordCount,
      estimatedDurationMinutes: durationMins,
      estimatedClipCount: estClips
    });
  }, [script, clipDuration]);

  // Toast Timer
  useEffect(() => {
    if (showToast) {
      const timer = setTimeout(() => setShowToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [showToast]);

  // Auto-scroll
  useEffect(() => {
    if (status === GenerationStatus.GENERATING && clips.length > 0) {
      bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [clips.length, status]);

  const formatTime = (ms: number) => {
    if (!isFinite(ms) || ms < 0) return '--:--';
    const totalSeconds = Math.floor(ms / 1000);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}m ${seconds.toString().padStart(2, '0')}s`;
  };

  const handleRegenerateClip = async (clipId: string, instruction: string) => {
    const clipToRegenerate = clips.find(c => c.id === clipId);
    if (!clipToRegenerate) return;

    setRegeneratingIds(prev => new Set(prev).add(clipId));

    try {
      const updatedClip = await geminiService.regenerateClip(clipToRegenerate, settings, instruction, outputFormat);
      setClips(prevClips => prevClips.map(c => c.id === clipId ? updatedClip : c));
    } catch (error) {
      console.error("Failed to regenerate clip", error);
    } finally {
      setRegeneratingIds(prev => {
        const next = new Set(prev);
        next.delete(clipId);
        return next;
      });
    }
  };

  // --- PROJECT IMPORT / EXPORT LOGIC ---

  const handleExportProject = () => {
    const { characters, ...globalStyle } = settings;
    const exportData: ProjectExportData = {
      script,
      pacing: `${clipDuration}s`,
      outputFormat,
      globalStyle,
      characters
    };

    const jsonString = JSON.stringify(exportData, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `project_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setShowToast("✅ Project exported successfully!");
  };

  const handleImportProject = (jsonString: string): { success: boolean; message?: string } => {
    try {
      let data: any;
      try {
        data = JSON.parse(jsonString);
      } catch (e) {
        return { success: false, message: "Invalid JSON Syntax. Check for missing commas or brackets." };
      }

      let hasUpdates = false;

      // 1. Script (Check root level and common aliases)
      const scriptVal = data.script || data.video_script || data.source_script?.text;
      if (scriptVal && typeof scriptVal === 'string') {
        setScript(scriptVal);
        hasUpdates = true;
      }

      // 2. Pacing
      const pacingVal = data.pacing || data.clip_duration || data.pacing_seconds || data.timing_data?.duration;
      if (pacingVal) {
        const cleanPacing = parseInt(String(pacingVal).replace(/s|seconds/gi, ''));
        if (CLIP_DURATIONS.includes(cleanPacing as any)) {
          setClipDuration(cleanPacing as ClipDuration);
          hasUpdates = true;
        }
      }

      // 3. Output Format
      const formatVal = data.outputFormat || data.output_format;
      if (formatVal === 'json' || formatVal === 'standard') {
        setOutputFormat(formatVal);
        hasUpdates = true;
      }

      // 4. Smart Style Mapping
      // Check for style keys at root level OR inside a nested object (globalStyle, style, style_engine_parameters)
      // We prioritize specific objects but fall back to root.
      const styleSources = [data, data.globalStyle, data.style, data.global_style, data.style_engine_parameters].filter(Boolean);

      const findKey = (candidates: string[]) => {
        for (const source of styleSources) {
          for (const key of candidates) {
            if (source[key] !== undefined && source[key] !== null) return source[key];
          }
        }
        return undefined;
      };

      const newSettings = { ...settings }; // Start with current settings to allow partial updates
      let styleUpdated = false;

      // Visual Style
      const visualStyle = findKey(['visualStyle', 'visual_style', 'VISUAL_STYLE', 'visual_aesthetic', 'aesthetic']);
      if (visualStyle) { newSettings.visualStyle = visualStyle; styleUpdated = true; }

      // Mood
      const mood = findKey(['mood', 'mood_tone', 'MOOD_&_TONE', 'atmosphere', 'emotional_beat']);
      if (mood) { newSettings.mood = mood; styleUpdated = true; }

      // Lighting
      const lighting = findKey(['lighting', 'lighting_style', 'LIGHTING_STYLE', 'lighting_setup']);
      if (lighting) { newSettings.lighting = lighting; styleUpdated = true; }

      // Camera Style
      const cameraStyle = findKey(['cameraStyle', 'camera_style', 'CAMERA_STYLE', 'camera_angle', 'camera_architecture']);
      if (typeof cameraStyle === 'object' && cameraStyle.angle) {
          newSettings.cameraStyle = cameraStyle.angle;
          styleUpdated = true;
      } else if (typeof cameraStyle === 'string') {
          newSettings.cameraStyle = cameraStyle;
          styleUpdated = true;
      }

      // Camera Movement
      const movement = findKey(['cameraMovement', 'camera_movement', 'CAMERA_MOVEMENT', 'movement']);
      // Handle the Detailed JSON structure where movement is inside camera_architecture
      const deepMovement = data.style_engine_parameters?.camera_architecture?.movement;
      if (deepMovement) {
         newSettings.cameraMovement = deepMovement;
         styleUpdated = true;
      } else if (movement) {
         newSettings.cameraMovement = movement;
         styleUpdated = true;
      }

      // Art Keywords
      // UPDATED: Added aliases for ART_DIRECTION_KEYWORDS and art_direction_keywords
      const keywords = findKey(['artKeywords', 'art_keywords', 'keywords', 'texture_keywords', 'ART_DIRECTION_KEYWORDS', 'art_direction_keywords']);
      if (keywords) {
        newSettings.artKeywords = Array.isArray(keywords) ? keywords.join(', ') : keywords;
        styleUpdated = true;
      }

      // Color Palette
      // UPDATED: Added COLOR_PALETTE_HEX alias and mapped Color_1, Color_2, Color_3 fields
      const palette = findKey(['colorPalette', 'color_palette', 'COLOR_PALETTE', 'colors', 'color_grading', 'COLOR_PALETTE_HEX']);
      if (palette && typeof palette === 'object') {
        newSettings.colorPalette = {
          primary: palette.primary || palette.hex_1 || palette.Color_1 || palette.color_1 || newSettings.colorPalette.primary,
          secondary: palette.secondary || palette.hex_2 || palette.Color_2 || palette.color_2 || newSettings.colorPalette.secondary,
          accent: palette.accent || palette.hex_3 || palette.Color_3 || palette.color_3 || newSettings.colorPalette.accent
        };
        styleUpdated = true;
      }

      // Characters
      const chars = findKey(['characters', 'cast', 'character_profiles']);
      if (Array.isArray(chars)) {
        newSettings.characters = chars;
        styleUpdated = true;
      }

      if (styleUpdated) {
        setSettings(newSettings);
        hasUpdates = true;
      }

      if (hasUpdates) {
        setShowToast("✅ Project updated successfully!");
        return { success: true };
      } else {
        const detectedKeys = Object.keys(data).slice(0, 5).join(", ");
        return { 
          success: false, 
          message: `JSON parsed, but no recognizable fields were found. Detected keys: [${detectedKeys}...]` 
        };
      }
    } catch (e: any) {
      console.error("Import failed", e);
      return { success: false, message: "Unknown import error: " + e.message };
    }
  };

  // --- BATCH GENERATION LOGIC ---

  const processScriptQueue = async (startIndex: number, endIndex: number, chunks: string[]) => {
    if (stopGenerationRef.current) return;

    if (startIndex >= endIndex) {
      if (endIndex === chunks.length) {
        setStatus(GenerationStatus.SUCCESS);
        setProgress(prev => ({ ...prev, current: chunks.length, currentStep: 'Generation Complete!' }));
        setEstTimeRemaining('0m 00s');
      } else {
        setStatus(GenerationStatus.WAITING_APPROVAL);
      }
      return;
    }

    const batchLimit = Math.min(startIndex + BATCH_SIZE, endIndex);
    const currentBatchNumber = Math.floor(startIndex / BATCH_SIZE) + 1;
    const isPhase1 = endIndex <= 10;
    const phaseLabel = isPhase1 ? "Phase 1: Test Run" : "Phase 3: Full Run";

    setStatus(GenerationStatus.GENERATING);
    setErrorMsg(null);

    for (let i = startIndex; i < batchLimit; i++) {
      if (stopGenerationRef.current) break;

      const clipNum = i + 1;
      setProgress(prev => ({ 
        ...prev, 
        current: i, 
        currentStep: `${phaseLabel} - Batch ${currentBatchNumber} (Clip ${clipNum}/${chunks.length})` 
      }));

      try {
        if (!clips.find(c => c.clipNumber === clipNum)) {
          const newClip = await geminiService.generateSingleClip(chunks[i], clipNum, settings, clipDuration, outputFormat);
          setClips(prev => [...prev, newClip]);

          itemsProcessedInSessionRef.current += 1;
          const elapsed = Date.now() - sessionStartTimeRef.current;
          const avgTimePerClip = elapsed / itemsProcessedInSessionRef.current;
          const remainingClips = endIndex - (i + 1);
          const estimatedRemainingMs = avgTimePerClip * remainingClips;
          setEstTimeRemaining(formatTime(estimatedRemainingMs));
        }
        setNextClipIndex(i + 1);

      } catch (err: any) {
        console.error("Batch Error:", err);
        stopGenerationRef.current = true;
        setStatus(GenerationStatus.ERROR);
        setErrorMsg(`Failed at Batch ${currentBatchNumber} (Clip ${clipNum}). Error: ${err.message || 'API Error'}`);
        return; 
      }
    }

    if (!stopGenerationRef.current) {
      setTimeout(() => {
        processScriptQueue(batchLimit, endIndex, chunks);
      }, 100);
    }
  };

  const startSessionTracking = () => {
    sessionStartTimeRef.current = Date.now();
    itemsProcessedInSessionRef.current = 0;
    setEstTimeRemaining('Calculating...');
  };

  const handleInitialGenerate = async () => {
    if (!script.trim()) return;

    setClips([]);
    setErrorMsg(null);
    setNextClipIndex(0);
    setStatus(GenerationStatus.PREPARING);
    stopGenerationRef.current = false;
    startSessionTracking();

    const chunks = geminiService.splitScriptToChunks(script, clipDuration);
    setScriptChunks(chunks);
    setProgress({ current: 0, total: chunks.length, currentStep: 'Analyzing Script Structure...' });

    const firstBatchEnd = chunks.length <= 10 ? chunks.length : 10;
    await processScriptQueue(0, firstBatchEnd, chunks);
  };

  const handleApproveAndContinue = async () => {
    if (status !== GenerationStatus.WAITING_APPROVAL && status !== GenerationStatus.ERROR) return;
    stopGenerationRef.current = false;
    startSessionTracking();
    await processScriptQueue(nextClipIndex, scriptChunks.length, scriptChunks);
  };

  const handleRetry = async () => {
    if (status !== GenerationStatus.ERROR) return;
    stopGenerationRef.current = false;
    startSessionTracking();

    const isTestBatchPhase = scriptChunks.length > 10 && nextClipIndex < 10;
    const targetEnd = isTestBatchPhase ? 10 : scriptChunks.length;

    await processScriptQueue(nextClipIndex, targetEnd, scriptChunks);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-gray-200 pb-20 relative">
      {/* Toast Notification */}
      {showToast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-green-600 text-white px-6 py-3 rounded-full shadow-2xl font-bold flex items-center gap-2 animate-in fade-in slide-in-from-top-4">
          <CheckCircle size={20} /> {showToast}
        </div>
      )}

      {/* Import Modal */}
      <ProjectImportModal 
        isOpen={isImportModalOpen} 
        onClose={() => setIsImportModalOpen(false)}
        onImport={handleImportProject}
      />

      {/* Navbar / Header */}
      <header className="bg-[#0f172a]/80 backdrop-blur-md border-b border-gray-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-900/50">
              <Sparkles className="text-white w-6 h-6" />
            </div>
            <h1 className="text-2xl font-bold text-white tracking-tight">
              Video Script to <span className="text-blue-500">Prompt Elite 2.0</span>
            </h1>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsImportModalOpen(true)}
              disabled={status === GenerationStatus.GENERATING}
              className="flex items-center gap-2 px-3 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 text-xs font-bold rounded-lg border border-gray-700 transition-colors disabled:opacity-50"
            >
              <Upload size={14} /> Import Project
            </button>
            <button 
              onClick={handleExportProject}
              className="flex items-center gap-2 px-3 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 text-xs font-bold rounded-lg border border-gray-700 transition-colors"
            >
              <Download size={14} /> Export Project
            </button>
            <div className="w-px h-6 bg-gray-700 mx-1 hidden sm:block"></div>
            <div className="text-sm text-gray-500 hidden sm:block font-medium">
              Powered by Gemini 2.5
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-10 space-y-10">

        {/* Style Engine Panel */}
        <section>
          <StyleEngine 
            settings={settings} 
            setSettings={setSettings} 
            disabled={status === GenerationStatus.GENERATING}
          />
        </section>

        {/* Input & Output Grid */}
        <section className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Left Column: Input */}
          <div className="lg:col-span-1 space-y-6">
            <div className="sticky top-28 space-y-6">

              {/* Script Input Box */}
              <div className="space-y-2">
                <div className="flex justify-between items-center">
                  <label className="text-sm font-bold text-gray-300 uppercase tracking-wider">Input Script</label>
                  <button 
                    onClick={() => {
                      setScript('');
                      setClips([]);
                      setStatus(GenerationStatus.IDLE);
                      setNextClipIndex(0);
                      setEstTimeRemaining('--:--');
                    }}
                    className="text-xs text-red-400 hover:text-red-300 transition-colors"
                  >
                    Clear & Reset
                  </button>
                </div>

                <div className="relative">
                  <textarea
                    value={script}
                    onChange={(e) => setScript(e.target.value)}
                    placeholder="Paste your video script here... (Supports 400+ clips)"
                    className="w-full h-[400px] bg-[#1e293b] border border-gray-700 rounded-xl p-4 text-gray-200 placeholder-gray-500 focus:ring-2 focus:ring-blue-600 focus:border-transparent transition-all resize-none font-mono text-sm leading-relaxed"
                    disabled={status === GenerationStatus.GENERATING}
                  />

                  {/* Generate Button Overlay */}
                  <div className="absolute bottom-4 right-4 left-4">
                    {status === GenerationStatus.IDLE || status === GenerationStatus.SUCCESS || status === GenerationStatus.ERROR ? (
                       <button
                       onClick={handleInitialGenerate}
                       disabled={!script.trim()}
                       className={`w-full py-4 rounded-lg flex items-center justify-center gap-2 font-bold text-lg shadow-xl transition-all transform active:scale-95 ${
                         !script.trim()
                           ? 'bg-gray-700 text-gray-500 cursor-not-allowed'
                           : 'bg-[#3b82f6] hover:bg-blue-600 text-white shadow-blue-900/50 hover:shadow-blue-700/50'
                       }`}
                     >
                       <Play fill="currentColor" size={20} />
                       {clips.length > 0 ? "RESTART GENERATION" : "GENERATE PROMPTS"}
                     </button>
                    ) : null}
                  </div>
                </div>
              </div>

              {/* Clip Duration & Output Format Selector */}
              <div className="bg-[#1e293b] border border-gray-700 rounded-xl p-4 space-y-4">

                {/* Duration */}
                <div>
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-wider block mb-2">Seconds per Clip</label>
                  <div className="flex justify-between gap-2">
                    {CLIP_DURATIONS.map(dur => (
                      <button
                        key={dur}
                        onClick={() => setClipDuration(dur as ClipDuration)}
                        disabled={status === GenerationStatus.GENERATING}
                        className={`flex-1 py-1.5 text-xs font-semibold rounded-lg transition-all ${
                          clipDuration === dur 
                            ? 'bg-blue-600 text-white shadow-lg' 
                            : 'bg-[#0f172a] text-gray-400 hover:text-white border border-gray-700 hover:border-gray-500'
                        }`}
                      >
                        {dur}s
                      </button>
                    ))}
                  </div>
                </div>

                {/* Output Format */}
                <div>
                   <label className="text-xs font-bold text-gray-400 uppercase tracking-wider block mb-2">Output Format</label>
                   <div className="flex gap-2">
                     <button
                       onClick={() => setOutputFormat('standard')}
                       disabled={status === GenerationStatus.GENERATING}
                       className={`flex-1 py-2 rounded-lg flex items-center justify-center gap-2 text-xs font-bold transition-all border ${
                         outputFormat === 'standard' 
                         ? 'bg-blue-900/30 border-blue-500 text-blue-300' 
                         : 'bg-[#0f172a] border-gray-700 text-gray-500 hover:border-gray-500'
                       }`}
                     >
                       <FileText size={14} /> 📝 Standard
                     </button>
                     <button
                       onClick={() => setOutputFormat('json')}
                       disabled={status === GenerationStatus.GENERATING}
                       className={`flex-1 py-2 rounded-lg flex items-center justify-center gap-2 text-xs font-bold transition-all border ${
                         outputFormat === 'json' 
                         ? 'bg-purple-900/30 border-purple-500 text-purple-300' 
                         : 'bg-[#0f172a] border-gray-700 text-gray-500 hover:border-gray-500'
                       }`}
                     >
                       <FileJson size={14} /> 🤖 Detailed JSON
                     </button>
                   </div>
                </div>

              </div>

              <MetricsDisplay metrics={metrics} />
            </div>
          </div>

          {/* Right Column: Output */}
          <div className="lg:col-span-2 space-y-6">
             <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-gray-800 pb-4">
                <div className="flex items-center gap-3">
                  <h2 className="text-xl font-bold text-white">Generated Output</h2>
                  {clips.length > 0 && (
                    <span className="bg-green-900/30 text-green-400 px-3 py-1 rounded-full text-xs font-semibold border border-green-800 animate-pulse">
                      {clips.length} / {progress.total > 0 ? progress.total : metrics.estimatedClipCount} Clips
                    </span>
                  )}
                </div>

                {/* Export is always available if we have clips, even during error/generation */}
                <ExportActions clips={clips} settings={settings} />
             </div>

            {/* REAL-TIME PROGRESS BAR & ERROR BOX */}
            {(status === GenerationStatus.GENERATING || status === GenerationStatus.WAITING_APPROVAL || status === GenerationStatus.ERROR || status === GenerationStatus.PREPARING) && (
              <div className={`border rounded-xl p-4 shadow-lg transition-all duration-300 ${status === GenerationStatus.ERROR ? 'bg-red-900/10 border-red-800' : 'bg-[#1e293b] border-gray-700'}`}>

                <div className="flex justify-between items-end mb-2">
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      {status === GenerationStatus.GENERATING && <Loader2 className="animate-spin text-blue-400" size={16} />}
                      {status === GenerationStatus.ERROR && <AlertCircle className="text-red-500" size={16} />}
                      <span className={`text-sm font-bold ${status === GenerationStatus.ERROR ? 'text-red-400' : 'text-blue-300'}`}>
                        {status === GenerationStatus.ERROR ? "Generation Interrupted" : progress.currentStep}
                      </span>
                    </div>
                    {status === GenerationStatus.GENERATING && (
                      <div className="flex items-center gap-2 text-xs text-gray-400">
                         <Clock size={12} />
                         <span>Est. Remaining: <span className="text-white font-mono">{estTimeRemaining}</span></span>
                      </div>
                    )}
                  </div>
                  <span className="text-xs text-gray-500 font-mono">
                    {Math.round((clips.length / (progress.total || 1)) * 100)}%
                  </span>
                </div>

                {/* Progress Line */}
                <div className="w-full bg-gray-700 rounded-full h-2.5 overflow-hidden">
                  <div 
                    className={`h-2.5 rounded-full transition-all duration-300 ease-linear ${
                      status === GenerationStatus.ERROR ? 'bg-red-500' : 'bg-blue-500'
                    }`}
                    style={{ width: `${(clips.length / (progress.total || 1)) * 100}%` }}
                  ></div>
                </div>

                {/* ERROR STATE: THE "RED BOX" */}
                {status === GenerationStatus.ERROR && (
                  <div className="mt-4 flex flex-col md:flex-row items-center justify-between bg-red-950/40 border border-red-500/30 p-4 rounded-lg gap-4">
                    <div className="text-red-200 text-sm">
                      <p className="font-bold mb-1">❌ Failed at Batch {Math.ceil(nextClipIndex / BATCH_SIZE)}</p>
                      <p className="font-mono text-xs opacity-80">{errorMsg}</p>
                    </div>
                    <button 
                      onClick={handleRetry}
                      className="px-4 py-2 bg-red-600 hover:bg-red-500 text-white text-sm font-bold rounded-lg shadow-lg flex items-center gap-2 whitespace-nowrap transition-transform active:scale-95"
                    >
                      <RotateCcw size={16} /> Retry from Clip {nextClipIndex}
                    </button>
                  </div>
                )}
              </div>
            )}

             {status === GenerationStatus.IDLE && clips.length === 0 && (
               <div className="h-[400px] flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl bg-[#1e293b]/50">
                 <Video size={48} className="mb-4 opacity-50" />
                 <p className="text-lg font-medium text-gray-400">Ready to generate.</p>
                 <p className="text-sm text-gray-500">Supports high-volume scripts (400+ clips).</p>
               </div>
             )}

            <div className="grid grid-cols-1 gap-6">
              {clips.map((clip) => (
                <PromptCard 
                  key={clip.id} 
                  clip={clip} 
                  onRegenerate={handleRegenerateClip}
                  isRegenerating={regeneratingIds.has(clip.id)}
                />
              ))}
              <div ref={bottomRef} className="h-4" />
            </div>

            {status === GenerationStatus.WAITING_APPROVAL && (
              <div className="sticky bottom-6 z-20">
                <div className="bg-[#1e293b] border border-blue-500/50 p-4 rounded-xl shadow-2xl shadow-black/50 flex flex-col items-center gap-3 backdrop-blur-sm">
                  <div className="text-center">
                    <h3 className="text-white font-bold text-lg">Test Batch Complete (1-10)</h3>
                    <p className="text-gray-400 text-sm">Review the first 10 clips above. If satisfied, continue generating the rest.</p>
                  </div>
                  <button 
                    onClick={handleApproveAndContinue}
                    className="w-full md:w-auto px-8 py-3 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg shadow-lg shadow-green-900/50 flex items-center justify-center gap-2 transition-all transform hover:scale-105"
                  >
                    <CheckCircle size={20} />
                    APPROVE & GENERATE REMAINING {scriptChunks.length - 10} CLIPS
                  </button>
                </div>
              </div>
            )}

            {status === GenerationStatus.GENERATING && (
              <div className="opacity-50 pointer-events-none animate-pulse flex flex-col items-center gap-2">
                <div className="bg-[#1e293b] w-full h-32 rounded-xl border border-gray-700/50 p-6 flex flex-col gap-3">
                   <div className="h-4 bg-gray-700 rounded w-1/4"></div>
                   <div className="h-4 bg-gray-700 rounded w-3/4"></div>
                </div>
                <span className="text-xs text-blue-400 flex items-center gap-1">
                   <ArrowDownCircle size={12} /> Auto-scrolling enabled
                </span>
              </div>
            )}
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { StyleEngine } from './components/StyleEngine';
import { MetricsDisplay } from './components/MetricsDisplay';
import { PromptCard } from './components/PromptCard';
import { ExportActions } from './components/ExportActions';
import { ProjectImportModal } from './components/ProjectImportModal';
import { geminiService } from './services/geminiService';
import { StyleSettings, ScriptMetrics, GeneratedClip, GenerationStatus, ClipDuration, GenerationProgress, ProjectExportData, OutputFormat } from './types';
import { DEFAULT_SETTINGS, CLIP_DURATIONS, BATCH_SIZE } from './constants';
import { Sparkles, Play, AlertCircle, Video, Loader2, CheckCircle, RotateCcw, ArrowDownCircle, Clock, Download, Upload, FileJson, FileText } from 'lucide-react';

const App: React.FC = () => {
  const [script, setScript] = useState('');
  const [settings, setSettings] = useState<StyleSettings>(DEFAULT_SETTINGS);
  const [clipDuration, setClipDuration] = useState<ClipDuration>(8);
  const [outputFormat, setOutputFormat] = useState<OutputFormat>('standard');

  // UI State
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [showToast, setShowToast] = useState<string | null>(null);

  // Generation State
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [clips, setClips] = useState<GeneratedClip[]>([]);
  const [scriptChunks, setScriptChunks] = useState<string[]>([]);
  const [progress, setProgress] = useState<GenerationProgress>({ current: 0, total: 0, currentStep: '' });
  const [estTimeRemaining, setEstTimeRemaining] = useState<string>('--:--');

  // State for individual clip regeneration
  const [regeneratingIds, setRegeneratingIds] = useState<Set<string>>(new Set());

  // Tracks the index of the next clip to be generated.
  const [nextClipIndex, setNextClipIndex] = useState(0);

  // Refs for control and scrolling
  const stopGenerationRef = useRef(false);
  const bottomRef = useRef<HTMLDivElement>(null);

  // Refs for ETR calculation
  const sessionStartTimeRef = useRef<number>(0);
  const itemsProcessedInSessionRef = useRef<number>(0);

  const [metrics, setMetrics] = useState<ScriptMetrics>({
    wordCount: 0,
    estimatedDurationMinutes: 0,
    estimatedClipCount: 0
  });

  // Calculate metrics
  useEffect(() => {
    const trimmed = script.trim();
    if (!trimmed) {
      setMetrics({ wordCount: 0, estimatedDurationMinutes: 0, estimatedClipCount: 0 });
      return;
    }
    const words = trimmed.split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;
    const wordsPerSec = 3; 
    const totalDurationSeconds = wordCount / wordsPerSec;
    const durationMins = totalDurationSeconds / 60;
    const estClips = Math.ceil(totalDurationSeconds / clipDuration);

    setMetrics({
      wordCount,
      estimatedDurationMinutes: durationMins,
      estimatedClipCount: estClips
    });
  }, [script, clipDuration]);

  // Toast Timer
  useEffect(() => {
    if (showToast) {
      const timer = setTimeout(() => setShowToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [showToast]);

  // Auto-scroll
  useEffect(() => {
    if (status === GenerationStatus.GENERATING && clips.length > 0) {
      bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [clips.length, status]);

  const formatTime = (ms: number) => {
    if (!isFinite(ms) || ms < 0) return '--:--';
    const totalSeconds = Math.floor(ms / 1000);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}m ${seconds.toString().padStart(2, '0')}s`;
  };

  const handleRegenerateClip = async (clipId: string, instruction: string) => {
    const clipToRegenerate = clips.find(c => c.id === clipId);
    if (!clipToRegenerate) return;

    setRegeneratingIds(prev => new Set(prev).add(clipId));

    try {
      const updatedClip = await geminiService.regenerateClip(clipToRegenerate, settings, instruction, outputFormat);
      setClips(prevClips => prevClips.map(c => c.id === clipId ? updatedClip : c));
    } catch (error) {
      console.error("Failed to regenerate clip", error);
    } finally {
      setRegeneratingIds(prev => {
        const next = new Set(prev);
        next.delete(clipId);
        return next;
      });
    }
  };

  // --- PROJECT IMPORT / EXPORT LOGIC ---

  const handleExportProject = () => {
    const { characters, ...globalStyle } = settings;
    const exportData: ProjectExportData = {
      script,
      pacing: `${clipDuration}s`,
      outputFormat,
      globalStyle,
      characters
    };

    const jsonString = JSON.stringify(exportData, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `project_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setShowToast("✅ Project exported successfully!");
  };

  const handleImportProject = (jsonString: string): { success: boolean; message?: string } => {
    try {
      let data: any;

      // AUTO-WRAP LOGIC:
      // If the user pastes a raw fragment (e.g. "LIGHTING": "Neon"), we automatically wrap it in braces.
      // We check if it *doesn't* start with '{' or '[' (ignoring whitespace).
      let processedInput = jsonString.trim();

      if (processedInput.length > 0 && !processedInput.startsWith('{') && !processedInput.startsWith('[')) {
        processedInput = `{${processedInput}}`;
      }

      try {
        data = JSON.parse(processedInput);
      } catch (e) {
        return { success: false, message: "Invalid JSON Syntax. Check for missing quotes around keys or commas." };
      }

      let hasUpdates = false;

      // 1. Script (Check root level and common aliases)
      const scriptVal = data.script || data.video_script || data.source_script?.text;
      if (scriptVal && typeof scriptVal === 'string') {
        setScript(scriptVal);
        hasUpdates = true;
      }

      // 2. Pacing
      const pacingVal = data.pacing || data.clip_duration || data.pacing_seconds || data.timing_data?.duration;
      if (pacingVal) {
        const cleanPacing = parseInt(String(pacingVal).replace(/s|seconds/gi, ''));
        if (CLIP_DURATIONS.includes(cleanPacing as any)) {
          setClipDuration(cleanPacing as ClipDuration);
          hasUpdates = true;
        }
      }

      // 3. Output Format
      const formatVal = data.outputFormat || data.output_format;
      if (formatVal === 'json' || formatVal === 'standard') {
        setOutputFormat(formatVal);
        hasUpdates = true;
      }

      // 4. Smart Style Mapping
      // Check for style keys at root level OR inside a nested object (globalStyle, style, style_engine_parameters)
      // We prioritize specific objects but fall back to root.
      const styleSources = [data, data.globalStyle, data.style, data.global_style, data.style_engine_parameters].filter(Boolean);

      const findKey = (candidates: string[]) => {
        for (const source of styleSources) {
          for (const key of candidates) {
            if (source[key] !== undefined && source[key] !== null) return source[key];
          }
        }
        return undefined;
      };

      const newSettings = { ...settings }; // Start with current settings to allow partial updates
      let styleUpdated = false;

      // Visual Style
      const visualStyle = findKey(['visualStyle', 'visual_style', 'VISUAL_STYLE', 'visual_aesthetic', 'aesthetic']);
      if (visualStyle) { newSettings.visualStyle = visualStyle; styleUpdated = true; }

      // Mood
      const mood = findKey(['mood', 'mood_tone', 'MOOD_&_TONE', 'atmosphere', 'emotional_beat']);
      if (mood) { newSettings.mood = mood; styleUpdated = true; }

      // Lighting
      const lighting = findKey(['lighting', 'lighting_style', 'LIGHTING_STYLE', 'lighting_setup']);
      if (lighting) { newSettings.lighting = lighting; styleUpdated = true; }

      // Camera Style
      const cameraStyle = findKey(['cameraStyle', 'camera_style', 'CAMERA_STYLE', 'camera_angle', 'camera_architecture']);
      if (typeof cameraStyle === 'object' && cameraStyle.angle) {
          newSettings.cameraStyle = cameraStyle.angle;
          styleUpdated = true;
      } else if (typeof cameraStyle === 'string') {
          newSettings.cameraStyle = cameraStyle;
          styleUpdated = true;
      }

      // Camera Movement
      const movement = findKey(['cameraMovement', 'camera_movement', 'CAMERA_MOVEMENT', 'movement']);
      // Handle the Detailed JSON structure where movement is inside camera_architecture
      const deepMovement = data.style_engine_parameters?.camera_architecture?.movement;
      if (deepMovement) {
         newSettings.cameraMovement = deepMovement;
         styleUpdated = true;
      } else if (movement) {
         newSettings.cameraMovement = movement;
         styleUpdated = true;
      }

      // Art Keywords
      // UPDATED: Added aliases for ART_DIRECTION_KEYWORDS and art_direction_keywords
      const keywords = findKey(['artKeywords', 'art_keywords', 'keywords', 'texture_keywords', 'ART_DIRECTION_KEYWORDS', 'art_direction_keywords']);
      if (keywords) {
        newSettings.artKeywords = Array.isArray(keywords) ? keywords.join(', ') : keywords;
        styleUpdated = true;
      }

      // Color Palette
      // UPDATED: Added COLOR_PALETTE_HEX alias and mapped Color_1, Color_2, Color_3 fields
      const palette = findKey(['colorPalette', 'color_palette', 'COLOR_PALETTE', 'colors', 'color_grading', 'COLOR_PALETTE_HEX']);
      if (palette && typeof palette === 'object') {
        newSettings.colorPalette = {
          primary: palette.primary || palette.hex_1 || palette.Color_1 || palette.color_1 || newSettings.colorPalette.primary,
          secondary: palette.secondary || palette.hex_2 || palette.Color_2 || palette.color_2 || newSettings.colorPalette.secondary,
          accent: palette.accent || palette.hex_3 || palette.Color_3 || palette.color_3 || newSettings.colorPalette.accent
        };
        styleUpdated = true;
      }

      // Characters
      const chars = findKey(['characters', 'cast', 'character_profiles']);
      if (Array.isArray(chars)) {
        newSettings.characters = chars;
        styleUpdated = true;
      }

      if (styleUpdated) {
        setSettings(newSettings);
        hasUpdates = true;
      }

      if (hasUpdates) {
        setShowToast("✅ Project updated successfully!");
        return { success: true };
      } else {
        const detectedKeys = Object.keys(data).slice(0, 5).join(", ");
        return { 
          success: false, 
          message: `JSON parsed, but no recognizable fields were found. Detected keys: [${detectedKeys}...]` 
        };
      }
    } catch (e: any) {
      console.error("Import failed", e);
      return { success: false, message: "Unknown import error: " + e.message };
    }
  };

  // --- BATCH GENERATION LOGIC ---

  const processScriptQueue = async (startIndex: number, endIndex: number, chunks: string[]) => {
    if (stopGenerationRef.current) return;

    if (startIndex >= endIndex) {
      if (endIndex === chunks.length) {
        setStatus(GenerationStatus.SUCCESS);
        setProgress(prev => ({ ...prev, current: chunks.length, currentStep: 'Generation Complete!' }));
        setEstTimeRemaining('0m 00s');
      } else {
        setStatus(GenerationStatus.WAITING_APPROVAL);
      }
      return;
    }

    const batchLimit = Math.min(startIndex + BATCH_SIZE, endIndex);
    const currentBatchNumber = Math.floor(startIndex / BATCH_SIZE) + 1;
    const isPhase1 = endIndex <= 10;
    const phaseLabel = isPhase1 ? "Phase 1: Test Run" : "Phase 3: Full Run";

    setStatus(GenerationStatus.GENERATING);
    setErrorMsg(null);

    for (let i = startIndex; i < batchLimit; i++) {
      if (stopGenerationRef.current) break;

      const clipNum = i + 1;
      setProgress(prev => ({ 
        ...prev, 
        current: i, 
        currentStep: `${phaseLabel} - Batch ${currentBatchNumber} (Clip ${clipNum}/${chunks.length})` 
      }));

      try {
        if (!clips.find(c => c.clipNumber === clipNum)) {
          const newClip = await geminiService.generateSingleClip(chunks[i], clipNum, settings, clipDuration, outputFormat);
          setClips(prev => [...prev, newClip]);

          itemsProcessedInSessionRef.current += 1;
          const elapsed = Date.now() - sessionStartTimeRef.current;
          const avgTimePerClip = elapsed / itemsProcessedInSessionRef.current;
          const remainingClips = endIndex - (i + 1);
          const estimatedRemainingMs = avgTimePerClip * remainingClips;
          setEstTimeRemaining(formatTime(estimatedRemainingMs));
        }
        setNextClipIndex(i + 1);

      } catch (err: any) {
        console.error("Batch Error:", err);
        stopGenerationRef.current = true;
        setStatus(GenerationStatus.ERROR);
        setErrorMsg(`Failed at Batch ${currentBatchNumber} (Clip ${clipNum}). Error: ${err.message || 'API Error'}`);
        return; 
      }
    }

    if (!stopGenerationRef.current) {
      setTimeout(() => {
        processScriptQueue(batchLimit, endIndex, chunks);
      }, 100);
    }
  };

  const startSessionTracking = () => {
    sessionStartTimeRef.current = Date.now();
    itemsProcessedInSessionRef.current = 0;
    setEstTimeRemaining('Calculating...');
  };

  const handleInitialGenerate = async () => {
    if (!script.trim()) return;

    setClips([]);
    setErrorMsg(null);
    setNextClipIndex(0);
    setStatus(GenerationStatus.PREPARING);
    stopGenerationRef.current = false;
    startSessionTracking();

    const chunks = geminiService.splitScriptToChunks(script, clipDuration);
    setScriptChunks(chunks);
    setProgress({ current: 0, total: chunks.length, currentStep: 'Analyzing Script Structure...' });

    const firstBatchEnd = chunks.length <= 10 ? chunks.length : 10;
    await processScriptQueue(0, firstBatchEnd, chunks);
  };

  const handleApproveAndContinue = async () => {
    if (status !== GenerationStatus.WAITING_APPROVAL && status !== GenerationStatus.ERROR) return;
    stopGenerationRef.current = false;
    startSessionTracking();
    await processScriptQueue(nextClipIndex, scriptChunks.length, scriptChunks);
  };

  const handleRetry = async () => {
    if (status !== GenerationStatus.ERROR) return;
    stopGenerationRef.current = false;
    startSessionTracking();

    const isTestBatchPhase = scriptChunks.length > 10 && nextClipIndex < 10;
    const targetEnd = isTestBatchPhase ? 10 : scriptChunks.length;

    await processScriptQueue(nextClipIndex, targetEnd, scriptChunks);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-gray-200 pb-20 relative">
      {/* Toast Notification */}
      {showToast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-green-600 text-white px-6 py-3 rounded-full shadow-2xl font-bold flex items-center gap-2 animate-in fade-in slide-in-from-top-4">
          <CheckCircle size={20} /> {showToast}
        </div>
      )}

      {/* Import Modal */}
      <ProjectImportModal 
        isOpen={isImportModalOpen} 
        onClose={() => setIsImportModalOpen(false)}
        onImport={handleImportProject}
      />

      {/* Navbar / Header */}
      <header className="bg-[#0f172a]/80 backdrop-blur-md border-b border-gray-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-900/50">
              <Sparkles className="text-white w-6 h-6" />
            </div>
            <h1 className="text-2xl font-bold text-white tracking-tight">
              Video Script to <span className="text-blue-500">Prompt Elite 2.0</span>
            </h1>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsImportModalOpen(true)}
              disabled={status === GenerationStatus.GENERATING}
              className="flex items-center gap-2 px-3 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 text-xs font-bold rounded-lg border border-gray-700 transition-colors disabled:opacity-50"
            >
              <Upload size={14} /> Import Project
            </button>
            <button 
              onClick={handleExportProject}
              className="flex items-center gap-2 px-3 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 text-xs font-bold rounded-lg border border-gray-700 transition-colors"
            >
              <Download size={14} /> Export Project
            </button>
            <div className="w-px h-6 bg-gray-700 mx-1 hidden sm:block"></div>
            <div className="text-sm text-gray-500 hidden sm:block font-medium">
              Powered by Gemini 2.5
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-10 space-y-10">

        {/* Style Engine Panel */}
        <section>
          <StyleEngine 
            settings={settings} 
            setSettings={setSettings} 
            disabled={status === GenerationStatus.GENERATING}
          />
        </section>

        {/* Input & Output Grid */}
        <section className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Left Column: Input */}
          <div className="lg:col-span-1 space-y-6">
            <div className="sticky top-28 space-y-6">

              {/* Script Input Box */}
              <div className="space-y-2">
                <div className="flex justify-between items-center">
                  <label className="text-sm font-bold text-gray-300 uppercase tracking-wider">Input Script</label>
                  <button 
                    onClick={() => {
                      setScript('');
                      setClips([]);
                      setStatus(GenerationStatus.IDLE);
                      setNextClipIndex(0);
                      setEstTimeRemaining('--:--');
                    }}
                    className="text-xs text-red-400 hover:text-red-300 transition-colors"
                  >
                    Clear & Reset
                  </button>
                </div>

                <div className="relative">
                  <textarea
                    value={script}
                    onChange={(e) => setScript(e.target.value)}
                    placeholder="Paste your video script here... (Supports 400+ clips)"
                    className="w-full h-[400px] bg-[#1e293b] border border-gray-700 rounded-xl p-4 text-gray-200 placeholder-gray-500 focus:ring-2 focus:ring-blue-600 focus:border-transparent transition-all resize-none font-mono text-sm leading-relaxed"
                    disabled={status === GenerationStatus.GENERATING}
                  />

                  {/* Generate Button Overlay */}
                  <div className="absolute bottom-4 right-4 left-4">
                    {status === GenerationStatus.IDLE || status === GenerationStatus.SUCCESS || status === GenerationStatus.ERROR ? (
                       <button
                       onClick={handleInitialGenerate}
                       disabled={!script.trim()}
                       className={`w-full py-4 rounded-lg flex items-center justify-center gap-2 font-bold text-lg shadow-xl transition-all transform active:scale-95 ${
                         !script.trim()
                           ? 'bg-gray-700 text-gray-500 cursor-not-allowed'
                           : 'bg-[#3b82f6] hover:bg-blue-600 text-white shadow-blue-900/50 hover:shadow-blue-700/50'
                       }`}
                     >
                       <Play fill="currentColor" size={20} />
                       {clips.length > 0 ? "RESTART GENERATION" : "GENERATE PROMPTS"}
                     </button>
                    ) : null}
                  </div>
                </div>
              </div>

              {/* Clip Duration & Output Format Selector */}
              <div className="bg-[#1e293b] border border-gray-700 rounded-xl p-4 space-y-4">

                {/* Duration */}
                <div>
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-wider block mb-2">Seconds per Clip</label>
                  <div className="flex justify-between gap-2">
                    {CLIP_DURATIONS.map(dur => (
                      <button
                        key={dur}
                        onClick={() => setClipDuration(dur as ClipDuration)}
                        disabled={status === GenerationStatus.GENERATING}
                        className={`flex-1 py-1.5 text-xs font-semibold rounded-lg transition-all ${
                          clipDuration === dur 
                            ? 'bg-blue-600 text-white shadow-lg' 
                            : 'bg-[#0f172a] text-gray-400 hover:text-white border border-gray-700 hover:border-gray-500'
                        }`}
                      >
                        {dur}s
                      </button>
                    ))}
                  </div>
                </div>

                {/* Output Format */}
                <div>
                   <label className="text-xs font-bold text-gray-400 uppercase tracking-wider block mb-2">Output Format</label>
                   <div className="flex gap-2">
                     <button
                       onClick={() => setOutputFormat('standard')}
                       disabled={status === GenerationStatus.GENERATING}
                       className={`flex-1 py-2 rounded-lg flex items-center justify-center gap-2 text-xs font-bold transition-all border ${
                         outputFormat === 'standard' 
                         ? 'bg-blue-900/30 border-blue-500 text-blue-300' 
                         : 'bg-[#0f172a] border-gray-700 text-gray-500 hover:border-gray-500'
                       }`}
                     >
                       <FileText size={14} /> 📝 Standard
                     </button>
                     <button
                       onClick={() => setOutputFormat('json')}
                       disabled={status === GenerationStatus.GENERATING}
                       className={`flex-1 py-2 rounded-lg flex items-center justify-center gap-2 text-xs font-bold transition-all border ${
                         outputFormat === 'json' 
                         ? 'bg-purple-900/30 border-purple-500 text-purple-300' 
                         : 'bg-[#0f172a] border-gray-700 text-gray-500 hover:border-gray-500'
                       }`}
                     >
                       <FileJson size={14} /> 🤖 Detailed JSON
                     </button>
                   </div>
                </div>

              </div>

              <MetricsDisplay metrics={metrics} />
            </div>
          </div>

          {/* Right Column: Output */}
          <div className="lg:col-span-2 space-y-6">
             <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-gray-800 pb-4">
                <div className="flex items-center gap-3">
                  <h2 className="text-xl font-bold text-white">Generated Output</h2>
                  {clips.length > 0 && (
                    <span className="bg-green-900/30 text-green-400 px-3 py-1 rounded-full text-xs font-semibold border border-green-800 animate-pulse">
                      {clips.length} / {progress.total > 0 ? progress.total : metrics.estimatedClipCount} Clips
                    </span>
                  )}
                </div>

                {/* Export is always available if we have clips, even during error/generation */}
                <ExportActions clips={clips} settings={settings} />
             </div>

            {/* REAL-TIME PROGRESS BAR & ERROR BOX */}
            {(status === GenerationStatus.GENERATING || status === GenerationStatus.WAITING_APPROVAL || status === GenerationStatus.ERROR || status === GenerationStatus.PREPARING) && (
              <div className={`border rounded-xl p-4 shadow-lg transition-all duration-300 ${status === GenerationStatus.ERROR ? 'bg-red-900/10 border-red-800' : 'bg-[#1e293b] border-gray-700'}`}>

                <div className="flex justify-between items-end mb-2">
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      {status === GenerationStatus.GENERATING && <Loader2 className="animate-spin text-blue-400" size={16} />}
                      {status === GenerationStatus.ERROR && <AlertCircle className="text-red-500" size={16} />}
                      <span className={`text-sm font-bold ${status === GenerationStatus.ERROR ? 'text-red-400' : 'text-blue-300'}`}>
                        {status === GenerationStatus.ERROR ? "Generation Interrupted" : progress.currentStep}
                      </span>
                    </div>
                    {status === GenerationStatus.GENERATING && (
                      <div className="flex items-center gap-2 text-xs text-gray-400">
                         <Clock size={12} />
                         <span>Est. Remaining: <span className="text-white font-mono">{estTimeRemaining}</span></span>
                      </div>
                    )}
                  </div>
                  <span className="text-xs text-gray-500 font-mono">
                    {Math.round((clips.length / (progress.total || 1)) * 100)}%
                  </span>
                </div>

                {/* Progress Line */}
                <div className="w-full bg-gray-700 rounded-full h-2.5 overflow-hidden">
                  <div 
                    className={`h-2.5 rounded-full transition-all duration-300 ease-linear ${
                      status === GenerationStatus.ERROR ? 'bg-red-500' : 'bg-blue-500'
                    }`}
                    style={{ width: `${(clips.length / (progress.total || 1)) * 100}%` }}
                  ></div>
                </div>

                {/* ERROR STATE: THE "RED BOX" */}
                {status === GenerationStatus.ERROR && (
                  <div className="mt-4 flex flex-col md:flex-row items-center justify-between bg-red-950/40 border border-red-500/30 p-4 rounded-lg gap-4">
                    <div className="text-red-200 text-sm">
                      <p className="font-bold mb-1">❌ Failed at Batch {Math.ceil(nextClipIndex / BATCH_SIZE)}</p>
                      <p className="font-mono text-xs opacity-80">{errorMsg}</p>
                    </div>
                    <button 
                      onClick={handleRetry}
                      className="px-4 py-2 bg-red-600 hover:bg-red-500 text-white text-sm font-bold rounded-lg shadow-lg flex items-center gap-2 whitespace-nowrap transition-transform active:scale-95"
                    >
                      <RotateCcw size={16} /> Retry from Clip {nextClipIndex}
                    </button>
                  </div>
                )}
              </div>
            )}

             {status === GenerationStatus.IDLE && clips.length === 0 && (
               <div className="h-[400px] flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl bg-[#1e293b]/50">
                 <Video size={48} className="mb-4 opacity-50" />
                 <p className="text-lg font-medium text-gray-400">Ready to generate.</p>
                 <p className="text-sm text-gray-500">Supports high-volume scripts (400+ clips).</p>
               </div>
             )}

            <div className="grid grid-cols-1 gap-6">
              {clips.map((clip) => (
                <PromptCard 
                  key={clip.id} 
                  clip={clip} 
                  onRegenerate={handleRegenerateClip}
                  isRegenerating={regeneratingIds.has(clip.id)}
                />
              ))}
              <div ref={bottomRef} className="h-4" />
            </div>

            {status === GenerationStatus.WAITING_APPROVAL && (
              <div className="sticky bottom-6 z-20">
                <div className="bg-[#1e293b] border border-blue-500/50 p-4 rounded-xl shadow-2xl shadow-black/50 flex flex-col items-center gap-3 backdrop-blur-sm">
                  <div className="text-center">
                    <h3 className="text-white font-bold text-lg">Test Batch Complete (1-10)</h3>
                    <p className="text-gray-400 text-sm">Review the first 10 clips above. If satisfied, continue generating the rest.</p>
                  </div>
                  <button 
                    onClick={handleApproveAndContinue}
                    className="w-full md:w-auto px-8 py-3 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg shadow-lg shadow-green-900/50 flex items-center justify-center gap-2 transition-all transform hover:scale-105"
                  >
                    <CheckCircle size={20} />
                    APPROVE & GENERATE REMAINING {scriptChunks.length - 10} CLIPS
                  </button>
                </div>
              </div>
            )}

            {status === GenerationStatus.GENERATING && (
              <div className="opacity-50 pointer-events-none animate-pulse flex flex-col items-center gap-2">
                <div className="bg-[#1e293b] w-full h-32 rounded-xl border border-gray-700/50 p-6 flex flex-col gap-3">
                   <div className="h-4 bg-gray-700 rounded w-1/4"></div>
                   <div className="h-4 bg-gray-700 rounded w-3/4"></div>
                </div>
                <span className="text-xs text-blue-400 flex items-center gap-1">
                   <ArrowDownCircle size={12} /> Auto-scrolling enabled
                </span>
              </div>
            )}
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { StyleEngine } from './components/StyleEngine';
import { MetricsDisplay } from './components/MetricsDisplay';
import { PromptCard } from './components/PromptCard';
import { ExportActions } from './components/ExportActions';
import { ProjectImportModal } from './components/ProjectImportModal';
import { geminiService } from './services/geminiService';
import { StyleSettings, ScriptMetrics, GeneratedClip, GenerationStatus, ClipDuration, GenerationProgress, ProjectExportData, OutputFormat } from './types';
import { DEFAULT_SETTINGS, CLIP_DURATIONS, BATCH_SIZE } from './constants';
import { Sparkles, Play, AlertCircle, Video, Loader2, CheckCircle, RotateCcw, ArrowDownCircle, Clock, Download, Upload, FileJson, FileText } from 'lucide-react';

const App: React.FC = () => {
  const [script, setScript] = useState('');
  const [settings, setSettings] = useState<StyleSettings>(DEFAULT_SETTINGS);
  const [clipDuration, setClipDuration] = useState<ClipDuration>(8);
  const [outputFormat, setOutputFormat] = useState<OutputFormat>('standard');

  // UI State
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [showToast, setShowToast] = useState<string | null>(null);

  // Generation State
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [clips, setClips] = useState<GeneratedClip[]>([]);
  const [scriptChunks, setScriptChunks] = useState<string[]>([]);
  const [progress, setProgress] = useState<GenerationProgress>({ current: 0, total: 0, currentStep: '' });
  const [estTimeRemaining, setEstTimeRemaining] = useState<string>('--:--');

  // State for individual clip regeneration
  const [regeneratingIds, setRegeneratingIds] = useState<Set<string>>(new Set());

  // Tracks the index of the next clip to be generated.
  const [nextClipIndex, setNextClipIndex] = useState(0);

  // Refs for control and scrolling
  const stopGenerationRef = useRef(false);
  const bottomRef = useRef<HTMLDivElement>(null);

  // Refs for ETR calculation
  const sessionStartTimeRef = useRef<number>(0);
  const itemsProcessedInSessionRef = useRef<number>(0);

  const [metrics, setMetrics] = useState<ScriptMetrics>({
    wordCount: 0,
    estimatedDurationMinutes: 0,
    estimatedClipCount: 0
  });

  // Calculate metrics
  useEffect(() => {
    const trimmed = script.trim();
    if (!trimmed) {
      setMetrics({ wordCount: 0, estimatedDurationMinutes: 0, estimatedClipCount: 0 });
      return;
    }
    const words = trimmed.split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;
    const wordsPerSec = 3; 
    const totalDurationSeconds = wordCount / wordsPerSec;
    const durationMins = totalDurationSeconds / 60;
    const estClips = Math.ceil(totalDurationSeconds / clipDuration);

    setMetrics({
      wordCount,
      estimatedDurationMinutes: durationMins,
      estimatedClipCount: estClips
    });
  }, [script, clipDuration]);

  // Toast Timer
  useEffect(() => {
    if (showToast) {
      const timer = setTimeout(() => setShowToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [showToast]);

  // Auto-scroll
  useEffect(() => {
    if (status === GenerationStatus.GENERATING && clips.length > 0) {
      bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [clips.length, status]);

  const formatTime = (ms: number) => {
    if (!isFinite(ms) || ms < 0) return '--:--';
    const totalSeconds = Math.floor(ms / 1000);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}m ${seconds.toString().padStart(2, '0')}s`;
  };

  const handleRegenerateClip = async (clipId: string, instruction: string) => {
    const clipToRegenerate = clips.find(c => c.id === clipId);
    if (!clipToRegenerate) return;

    setRegeneratingIds(prev => new Set(prev).add(clipId));

    try {
      const updatedClip = await geminiService.regenerateClip(clipToRegenerate, settings, instruction, outputFormat);
      setClips(prevClips => prevClips.map(c => c.id === clipId ? updatedClip : c));
    } catch (error) {
      console.error("Failed to regenerate clip", error);
    } finally {
      setRegeneratingIds(prev => {
        const next = new Set(prev);
        next.delete(clipId);
        return next;
      });
    }
  };

  // --- PROJECT IMPORT / EXPORT LOGIC ---

  const handleExportProject = () => {
    const { characters, ...globalStyle } = settings;
    const exportData: ProjectExportData = {
      script,
      pacing: `${clipDuration}s`,
      outputFormat,
      globalStyle,
      characters
    };

    const jsonString = JSON.stringify(exportData, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `project_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setShowToast("✅ Project exported successfully!");
  };

  const handleImportProject = (jsonString: string): { success: boolean; message?: string } => {
    let data: any = {};
    let isPartialRawMode = false;

    // STEP 1: Strict JSON Parse Attempt (with Auto-Wrap)
    let processedInput = jsonString.trim();
    if (processedInput.length > 0 && !processedInput.startsWith('{') && !processedInput.startsWith('[')) {
      processedInput = `{${processedInput}}`;
    }

    try {
      data = JSON.parse(processedInput);
    } catch (e) {
      // STEP 2: Fallback to Regex Scanning (Fuzzy Mode)
      // If JSON fails, we don't throw, we just try to scrape keys.
      isPartialRawMode = true;
      const regex = /"?([a-zA-Z0-9_&]+)"?\s*:\s*["']([^"']+)["']/g;
      let match;
      let matchesFound = false;

      while ((match = regex.exec(jsonString)) !== null) {
        matchesFound = true;
        const key = match[1];
        const value = match[2];
        data[key] = value;
      }

      // If we found absolutely nothing in regex scan, then we fail.
      if (!matchesFound) {
        return { success: false, message: "Invalid syntax. Could not parse JSON or find any key-value pairs." };
      }
    }

    let hasUpdates = false;

    // 1. Script (Check root level and common aliases)
    const scriptVal = data.script || data.video_script || data.source_script?.text;
    if (scriptVal && typeof scriptVal === 'string') {
      setScript(scriptVal);
      hasUpdates = true;
    }

    // 2. Pacing
    const pacingVal = data.pacing || data.clip_duration || data.pacing_seconds || data.timing_data?.duration;
    if (pacingVal) {
      const cleanPacing = parseInt(String(pacingVal).replace(/s|seconds/gi, ''));
      if (CLIP_DURATIONS.includes(cleanPacing as any)) {
        setClipDuration(cleanPacing as ClipDuration);
        hasUpdates = true;
      }
    }

    // 3. Output Format
    const formatVal = data.outputFormat || data.output_format;
    if (formatVal === 'json' || formatVal === 'standard') {
      setOutputFormat(formatVal);
      hasUpdates = true;
    }

    // 4. Smart Style Mapping
    // Check for style keys at root level OR inside a nested object (globalStyle, style, style_engine_parameters)
    // We prioritize specific objects but fall back to root.
    const styleSources = [data, data.globalStyle, data.style, data.global_style, data.style_engine_parameters].filter(Boolean);

    const findKey = (candidates: string[]) => {
      for (const source of styleSources) {
        for (const key of candidates) {
          if (source[key] !== undefined && source[key] !== null) return source[key];
        }
      }
      return undefined;
    };

    const newSettings = { ...settings }; // Start with current settings to allow partial updates
    let styleUpdated = false;

    // Visual Style
    const visualStyle = findKey(['visualStyle', 'visual_style', 'VISUAL_STYLE', 'visual_aesthetic', 'aesthetic']);
    if (visualStyle) { newSettings.visualStyle = visualStyle; styleUpdated = true; }

    // Mood
    const mood = findKey(['mood', 'mood_tone', 'MOOD_&_TONE', 'atmosphere', 'emotional_beat']);
    if (mood) { newSettings.mood = mood; styleUpdated = true; }

    // Lighting
    const lighting = findKey(['lighting', 'lighting_style', 'LIGHTING_STYLE', 'lighting_setup']);
    if (lighting) { newSettings.lighting = lighting; styleUpdated = true; }

    // Camera Style
    const cameraStyle = findKey(['cameraStyle', 'camera_style', 'CAMERA_STYLE', 'camera_angle', 'camera_architecture']);
    if (typeof cameraStyle === 'object' && cameraStyle.angle) {
        newSettings.cameraStyle = cameraStyle.angle;
        styleUpdated = true;
    } else if (typeof cameraStyle === 'string') {
        newSettings.cameraStyle = cameraStyle;
        styleUpdated = true;
    }

    // Camera Movement
    const movement = findKey(['cameraMovement', 'camera_movement', 'CAMERA_MOVEMENT', 'movement']);
    // Handle the Detailed JSON structure where movement is inside camera_architecture
    const deepMovement = data.style_engine_parameters?.camera_architecture?.movement;
    if (deepMovement) {
       newSettings.cameraMovement = deepMovement;
       styleUpdated = true;
    } else if (movement) {
       newSettings.cameraMovement = movement;
       styleUpdated = true;
    }

    // Art Keywords
    // UPDATED: Added aliases for ART_DIRECTION_KEYWORDS and art_direction_keywords
    const keywords = findKey(['artKeywords', 'art_keywords', 'keywords', 'texture_keywords', 'ART_DIRECTION_KEYWORDS', 'art_direction_keywords']);
    if (keywords) {
      newSettings.artKeywords = Array.isArray(keywords) ? keywords.join(', ') : keywords;
      styleUpdated = true;
    }

    // Color Palette
    // UPDATED: Added COLOR_PALETTE_HEX alias and mapped Color_1, Color_2, Color_3 fields
    // Also supports finding keys directly at root (via findKey) if container is missing
    const paletteContainer = findKey(['colorPalette', 'color_palette', 'COLOR_PALETTE', 'colors', 'color_grading', 'COLOR_PALETTE_HEX']);

    const pPrimary = (paletteContainer?.primary || paletteContainer?.hex_1 || paletteContainer?.Color_1 || paletteContainer?.color_1) || 
                     findKey(['Color_1', 'color_1', 'primary_color', 'primary']);

    const pSecondary = (paletteContainer?.secondary || paletteContainer?.hex_2 || paletteContainer?.Color_2 || paletteContainer?.color_2) || 
                       findKey(['Color_2', 'color_2', 'secondary_color', 'secondary']);

    const pAccent = (paletteContainer?.accent || paletteContainer?.hex_3 || paletteContainer?.Color_3 || paletteContainer?.color_3) || 
                    findKey(['Color_3', 'color_3', 'accent_color', 'accent']);

    if (pPrimary || pSecondary || pAccent) {
      newSettings.colorPalette = {
        primary: pPrimary || newSettings.colorPalette.primary,
        secondary: pSecondary || newSettings.colorPalette.secondary,
        accent: pAccent || newSettings.colorPalette.accent
      };
      styleUpdated = true;
    }

    // Characters
    const chars = findKey(['characters', 'cast', 'character_profiles']);
    if (Array.isArray(chars)) {
      newSettings.characters = chars;
      styleUpdated = true;
    }

    if (styleUpdated) {
      setSettings(newSettings);
      hasUpdates = true;
    }

    if (hasUpdates) {
      if (isPartialRawMode) {
        setShowToast("⚠️ Loaded data partially from raw text scan.");
      } else {
        setShowToast("✅ Project updated successfully!");
      }
      return { success: true };
    } else {
      const detectedKeys = Object.keys(data).slice(0, 5).join(", ");
      return { 
        success: false, 
        message: `Parsed data, but no recognizable fields were found. Detected keys: [${detectedKeys}...]` 
      };
    }
  };

  // --- BATCH GENERATION LOGIC ---

  const processScriptQueue = async (startIndex: number, endIndex: number, chunks: string[]) => {
    if (stopGenerationRef.current) return;

    if (startIndex >= endIndex) {
      if (endIndex === chunks.length) {
        setStatus(GenerationStatus.SUCCESS);
        setProgress(prev => ({ ...prev, current: chunks.length, currentStep: 'Generation Complete!' }));
        setEstTimeRemaining('0m 00s');
      } else {
        setStatus(GenerationStatus.WAITING_APPROVAL);
      }
      return;
    }

    const batchLimit = Math.min(startIndex + BATCH_SIZE, endIndex);
    const currentBatchNumber = Math.floor(startIndex / BATCH_SIZE) + 1;
    const isPhase1 = endIndex <= 10;
    const phaseLabel = isPhase1 ? "Phase 1: Test Run" : "Phase 3: Full Run";

    setStatus(GenerationStatus.GENERATING);
    setErrorMsg(null);

    for (let i = startIndex; i < batchLimit; i++) {
      if (stopGenerationRef.current) break;

      const clipNum = i + 1;
      setProgress(prev => ({ 
        ...prev, 
        current: i, 
        currentStep: `${phaseLabel} - Batch ${currentBatchNumber} (Clip ${clipNum}/${chunks.length})` 
      }));

      try {
        if (!clips.find(c => c.clipNumber === clipNum)) {
          const newClip = await geminiService.generateSingleClip(chunks[i], clipNum, settings, clipDuration, outputFormat);
          setClips(prev => [...prev, newClip]);

          itemsProcessedInSessionRef.current += 1;
          const elapsed = Date.now() - sessionStartTimeRef.current;
          const avgTimePerClip = elapsed / itemsProcessedInSessionRef.current;
          const remainingClips = endIndex - (i + 1);
          const estimatedRemainingMs = avgTimePerClip * remainingClips;
          setEstTimeRemaining(formatTime(estimatedRemainingMs));
        }
        setNextClipIndex(i + 1);

      } catch (err: any) {
        console.error("Batch Error:", err);
        stopGenerationRef.current = true;
        setStatus(GenerationStatus.ERROR);
        setErrorMsg(`Failed at Batch ${currentBatchNumber} (Clip ${clipNum}). Error: ${err.message || 'API Error'}`);
        return; 
      }
    }

    if (!stopGenerationRef.current) {
      setTimeout(() => {
        processScriptQueue(batchLimit, endIndex, chunks);
      }, 100);
    }
  };

  const startSessionTracking = () => {
    sessionStartTimeRef.current = Date.now();
    itemsProcessedInSessionRef.current = 0;
    setEstTimeRemaining('Calculating...');
  };

  const handleInitialGenerate = async () => {
    if (!script.trim()) return;

    setClips([]);
    setErrorMsg(null);
    setNextClipIndex(0);
    setStatus(GenerationStatus.PREPARING);
    stopGenerationRef.current = false;
    startSessionTracking();

    const chunks = geminiService.splitScriptToChunks(script, clipDuration);
    setScriptChunks(chunks);
    setProgress({ current: 0, total: chunks.length, currentStep: 'Analyzing Script Structure...' });

    const firstBatchEnd = chunks.length <= 10 ? chunks.length : 10;
    await processScriptQueue(0, firstBatchEnd, chunks);
  };

  const handleApproveAndContinue = async () => {
    if (status !== GenerationStatus.WAITING_APPROVAL && status !== GenerationStatus.ERROR) return;
    stopGenerationRef.current = false;
    startSessionTracking();
    await processScriptQueue(nextClipIndex, scriptChunks.length, scriptChunks);
  };

  const handleRetry = async () => {
    if (status !== GenerationStatus.ERROR) return;
    stopGenerationRef.current = false;
    startSessionTracking();

    const isTestBatchPhase = scriptChunks.length > 10 && nextClipIndex < 10;
    const targetEnd = isTestBatchPhase ? 10 : scriptChunks.length;

    await processScriptQueue(nextClipIndex, targetEnd, scriptChunks);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-gray-200 pb-20 relative">
      {/* Toast Notification */}
      {showToast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-green-600 text-white px-6 py-3 rounded-full shadow-2xl font-bold flex items-center gap-2 animate-in fade-in slide-in-from-top-4">
          <CheckCircle size={20} /> {showToast}
        </div>
      )}

      {/* Import Modal */}
      <ProjectImportModal 
        isOpen={isImportModalOpen} 
        onClose={() => setIsImportModalOpen(false)}
        onImport={handleImportProject}
      />

      {/* Navbar / Header */}
      <header className="bg-[#0f172a]/80 backdrop-blur-md border-b border-gray-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-900/50">
              <Sparkles className="text-white w-6 h-6" />
            </div>
            <h1 className="text-2xl font-bold text-white tracking-tight">
              Video Script to <span className="text-blue-500">Prompt Elite 2.0</span>
            </h1>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsImportModalOpen(true)}
              disabled={status === GenerationStatus.GENERATING}
              className="flex items-center gap-2 px-3 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 text-xs font-bold rounded-lg border border-gray-700 transition-colors disabled:opacity-50"
            >
              <Upload size={14} /> Import Project
            </button>
            <button 
              onClick={handleExportProject}
              className="flex items-center gap-2 px-3 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 text-xs font-bold rounded-lg border border-gray-700 transition-colors"
            >
              <Download size={14} /> Export Project
            </button>
            <div className="w-px h-6 bg-gray-700 mx-1 hidden sm:block"></div>
            <div className="text-sm text-gray-500 hidden sm:block font-medium">
              Powered by Gemini 2.5
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-10 space-y-10">

        {/* Style Engine Panel */}
        <section>
          <StyleEngine 
            settings={settings} 
            setSettings={setSettings} 
            disabled={status === GenerationStatus.GENERATING}
          />
        </section>

        {/* Input & Output Grid */}
        <section className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Left Column: Input */}
          <div className="lg:col-span-1 space-y-6">
            <div className="sticky top-28 space-y-6">

              {/* Script Input Box */}
              <div className="space-y-2">
                <div className="flex justify-between items-center">
                  <label className="text-sm font-bold text-gray-300 uppercase tracking-wider">Input Script</label>
                  <button 
                    onClick={() => {
                      setScript('');
                      setClips([]);
                      setStatus(GenerationStatus.IDLE);
                      setNextClipIndex(0);
                      setEstTimeRemaining('--:--');
                    }}
                    className="text-xs text-red-400 hover:text-red-300 transition-colors"
                  >
                    Clear & Reset
                  </button>
                </div>

                <div className="relative">
                  <textarea
                    value={script}
                    onChange={(e) => setScript(e.target.value)}
                    placeholder="Paste your video script here... (Supports 400+ clips)"
                    className="w-full h-[400px] bg-[#1e293b] border border-gray-700 rounded-xl p-4 text-gray-200 placeholder-gray-500 focus:ring-2 focus:ring-blue-600 focus:border-transparent transition-all resize-none font-mono text-sm leading-relaxed"
                    disabled={status === GenerationStatus.GENERATING}
                  />

                  {/* Generate Button Overlay */}
                  <div className="absolute bottom-4 right-4 left-4">
                    {status === GenerationStatus.IDLE || status === GenerationStatus.SUCCESS || status === GenerationStatus.ERROR ? (
                       <button
                       onClick={handleInitialGenerate}
                       disabled={!script.trim()}
                       className={`w-full py-4 rounded-lg flex items-center justify-center gap-2 font-bold text-lg shadow-xl transition-all transform active:scale-95 ${
                         !script.trim()
                           ? 'bg-gray-700 text-gray-500 cursor-not-allowed'
                           : 'bg-[#3b82f6] hover:bg-blue-600 text-white shadow-blue-900/50 hover:shadow-blue-700/50'
                       }`}
                     >
                       <Play fill="currentColor" size={20} />
                       {clips.length > 0 ? "RESTART GENERATION" : "GENERATE PROMPTS"}
                     </button>
                    ) : null}
                  </div>
                </div>
              </div>

              {/* Clip Duration & Output Format Selector */}
              <div className="bg-[#1e293b] border border-gray-700 rounded-xl p-4 space-y-4">

                {/* Duration */}
                <div>
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-wider block mb-2">Seconds per Clip</label>
                  <div className="flex justify-between gap-2">
                    {CLIP_DURATIONS.map(dur => (
                      <button
                        key={dur}
                        onClick={() => setClipDuration(dur as ClipDuration)}
                        disabled={status === GenerationStatus.GENERATING}
                        className={`flex-1 py-1.5 text-xs font-semibold rounded-lg transition-all ${
                          clipDuration === dur 
                            ? 'bg-blue-600 text-white shadow-lg' 
                            : 'bg-[#0f172a] text-gray-400 hover:text-white border border-gray-700 hover:border-gray-500'
                        }`}
                      >
                        {dur}s
                      </button>
                    ))}
                  </div>
                </div>

                {/* Output Format */}
                <div>
                   <label className="text-xs font-bold text-gray-400 uppercase tracking-wider block mb-2">Output Format</label>
                   <div className="flex gap-2">
                     <button
                       onClick={() => setOutputFormat('standard')}
                       disabled={status === GenerationStatus.GENERATING}
                       className={`flex-1 py-2 rounded-lg flex items-center justify-center gap-2 text-xs font-bold transition-all border ${
                         outputFormat === 'standard' 
                         ? 'bg-blue-900/30 border-blue-500 text-blue-300' 
                         : 'bg-[#0f172a] border-gray-700 text-gray-500 hover:border-gray-500'
                       }`}
                     >
                       <FileText size={14} /> 📝 Standard
                     </button>
                     <button
                       onClick={() => setOutputFormat('json')}
                       disabled={status === GenerationStatus.GENERATING}
                       className={`flex-1 py-2 rounded-lg flex items-center justify-center gap-2 text-xs font-bold transition-all border ${
                         outputFormat === 'json' 
                         ? 'bg-purple-900/30 border-purple-500 text-purple-300' 
                         : 'bg-[#0f172a] border-gray-700 text-gray-500 hover:border-gray-500'
                       }`}
                     >
                       <FileJson size={14} /> 🤖 Detailed JSON
                     </button>
                   </div>
                </div>

              </div>

              <MetricsDisplay metrics={metrics} />
            </div>
          </div>

          {/* Right Column: Output */}
          <div className="lg:col-span-2 space-y-6">
             <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-gray-800 pb-4">
                <div className="flex items-center gap-3">
                  <h2 className="text-xl font-bold text-white">Generated Output</h2>
                  {clips.length > 0 && (
                    <span className="bg-green-900/30 text-green-400 px-3 py-1 rounded-full text-xs font-semibold border border-green-800 animate-pulse">
                      {clips.length} / {progress.total > 0 ? progress.total : metrics.estimatedClipCount} Clips
                    </span>
                  )}
                </div>

                {/* Export is always available if we have clips, even during error/generation */}
                <ExportActions clips={clips} settings={settings} />
             </div>

            {/* REAL-TIME PROGRESS BAR & ERROR BOX */}
            {(status === GenerationStatus.GENERATING || status === GenerationStatus.WAITING_APPROVAL || status === GenerationStatus.ERROR || status === GenerationStatus.PREPARING) && (
              <div className={`border rounded-xl p-4 shadow-lg transition-all duration-300 ${status === GenerationStatus.ERROR ? 'bg-red-900/10 border-red-800' : 'bg-[#1e293b] border-gray-700'}`}>

                <div className="flex justify-between items-end mb-2">
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      {status === GenerationStatus.GENERATING && <Loader2 className="animate-spin text-blue-400" size={16} />}
                      {status === GenerationStatus.ERROR && <AlertCircle className="text-red-500" size={16} />}
                      <span className={`text-sm font-bold ${status === GenerationStatus.ERROR ? 'text-red-400' : 'text-blue-300'}`}>
                        {status === GenerationStatus.ERROR ? "Generation Interrupted" : progress.currentStep}
                      </span>
                    </div>
                    {status === GenerationStatus.GENERATING && (
                      <div className="flex items-center gap-2 text-xs text-gray-400">
                         <Clock size={12} />
                         <span>Est. Remaining: <span className="text-white font-mono">{estTimeRemaining}</span></span>
                      </div>
                    )}
                  </div>
                  <span className="text-xs text-gray-500 font-mono">
                    {Math.round((clips.length / (progress.total || 1)) * 100)}%
                  </span>
                </div>

                {/* Progress Line */}
                <div className="w-full bg-gray-700 rounded-full h-2.5 overflow-hidden">
                  <div 
                    className={`h-2.5 rounded-full transition-all duration-300 ease-linear ${
                      status === GenerationStatus.ERROR ? 'bg-red-500' : 'bg-blue-500'
                    }`}
                    style={{ width: `${(clips.length / (progress.total || 1)) * 100}%` }}
                  ></div>
                </div>

                {/* ERROR STATE: THE "RED BOX" */}
                {status === GenerationStatus.ERROR && (
                  <div className="mt-4 flex flex-col md:flex-row items-center justify-between bg-red-950/40 border border-red-500/30 p-4 rounded-lg gap-4">
                    <div className="text-red-200 text-sm">
                      <p className="font-bold mb-1">❌ Failed at Batch {Math.ceil(nextClipIndex / BATCH_SIZE)}</p>
                      <p className="font-mono text-xs opacity-80">{errorMsg}</p>
                    </div>
                    <button 
                      onClick={handleRetry}
                      className="px-4 py-2 bg-red-600 hover:bg-red-500 text-white text-sm font-bold rounded-lg shadow-lg flex items-center gap-2 whitespace-nowrap transition-transform active:scale-95"
                    >
                      <RotateCcw size={16} /> Retry from Clip {nextClipIndex}
                    </button>
                  </div>
                )}
              </div>
            )}

             {status === GenerationStatus.IDLE && clips.length === 0 && (
               <div className="h-[400px] flex flex-col items-center justify-center text-gray-600 border-2 border-dashed border-gray-800 rounded-xl bg-[#1e293b]/50">
                 <Video size={48} className="mb-4 opacity-50" />
                 <p className="text-lg font-medium text-gray-400">Ready to generate.</p>
                 <p className="text-sm text-gray-500">Supports high-volume scripts (400+ clips).</p>
               </div>
             )}

            <div className="grid grid-cols-1 gap-6">
              {clips.map((clip) => (
                <PromptCard 
                  key={clip.id} 
                  clip={clip} 
                  onRegenerate={handleRegenerateClip}
                  isRegenerating={regeneratingIds.has(clip.id)}
                />
              ))}
              <div ref={bottomRef} className="h-4" />
            </div>

            {status === GenerationStatus.WAITING_APPROVAL && (
              <div className="sticky bottom-6 z-20">
                <div className="bg-[#1e293b] border border-blue-500/50 p-4 rounded-xl shadow-2xl shadow-black/50 flex flex-col items-center gap-3 backdrop-blur-sm">
                  <div className="text-center">
                    <h3 className="text-white font-bold text-lg">Test Batch Complete (1-10)</h3>
                    <p className="text-gray-400 text-sm">Review the first 10 clips above. If satisfied, continue generating the rest.</p>
                  </div>
                  <button 
                    onClick={handleApproveAndContinue}
                    className="w-full md:w-auto px-8 py-3 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg shadow-lg shadow-green-900/50 flex items-center justify-center gap-2 transition-all transform hover:scale-105"
                  >
                    <CheckCircle size={20} />
                    APPROVE & GENERATE REMAINING {scriptChunks.length - 10} CLIPS
                  </button>
                </div>
              </div>
            )}

            {status === GenerationStatus.GENERATING && (
              <div className="opacity-50 pointer-events-none animate-pulse flex flex-col items-center gap-2">
                <div className="bg-[#1e293b] w-full h-32 rounded-xl border border-gray-700/50 p-6 flex flex-col gap-3">
                   <div className="h-4 bg-gray-700 rounded w-1/4"></div>
                   <div className="h-4 bg-gray-700 rounded w-3/4"></div>
                </div>
                <span className="text-xs text-blue-400 flex items-center gap-1">
                   <ArrowDownCircle size={12} /> Auto-scrolling enabled
                </span>
              </div>
            )}
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { StyleEngine } from './components/StyleEngine';
import { MetricsDisplay } from './components/MetricsDisplay';
import { PromptCard } from './components/PromptCard';
import { ExportActions } from './components/ExportActions';
import { ProjectImportModal } from './components/ProjectImportModal';
import { geminiService } from './services/geminiService';
import { StyleSettings, ScriptMetrics, GeneratedClip, GenerationStatus, ClipDuration, GenerationProgress, ProjectExportData, OutputFormat } from './types';
import { DEFAULT_SETTINGS, CLIP_DURATIONS, BATCH_SIZE } from './constants';
import { Sparkles, Play, AlertCircle, Video, Loader2, CheckCircle, RotateCcw, ArrowDownCircle, Clock, Download, Upload, FileJson, FileText } from 'lucide-react';

const App: React.FC = () => {
  const [script, setScript] = useState('');
  const [settings, setSettings] = useState<StyleSettings>(DEFAULT_SETTINGS);
  const [clipDuration, setClipDuration] = useState<ClipDuration>(8);
  const [outputFormat, setOutputFormat] = useState<OutputFormat>('standard');

  // UI State
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [showToast, setShowToast] = useState<string | null>(null);

  // Generation State
  const [status, setStatus] = useState<GenerationStatus>(GenerationStatus.IDLE);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [clips, setClips] = useState<GeneratedClip[]>([]);
  const [scriptChunks, setScriptChunks] = useState<string[]>([]);
  const [progress, setProgress] = useState<GenerationProgress>({ current: 0, total: 0, currentStep: '' });
  const [estTimeRemaining, setEstTimeRemaining] = useState<string>('--:--');

  // State for individual clip regeneration
  const [regeneratingIds, setRegeneratingIds] = useState<Set<string>>(new Set());

  // Tracks the index of the next clip to be generated.
  const [nextClipIndex, setNextClipIndex] = useState(0);

  // Refs for control and scrolling
  const stopGenerationRef = useRef(false);
  const bottomRef = useRef<HTMLDivElement>(null);

  // Refs for ETR calculation
  const sessionStartTimeRef = useRef<number>(0);
  const itemsProcessedInSessionRef = useRef<number>(0);

  const [metrics, setMetrics] = useState<ScriptMetrics>({
    wordCount: 0,
    estimatedDurationMinutes: 0,
    estimatedClipCount: 0
  });

  // Calculate metrics
  useEffect(() => {
    const trimmed = script.trim();
    if (!trimmed) {
      setMetrics({ wordCount: 0, estimatedDurationMinutes: 0, estimatedClipCount: 0 });
      return;
    }
    const words = trimmed.split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;
    const wordsPerSec = 3; 
    const totalDurationSeconds = wordCount / wordsPerSec;
    const durationMins = totalDurationSeconds / 60;
    const estClips = Math.ceil(totalDurationSeconds / clipDuration);

    setMetrics({
      wordCount,
      estimatedDurationMinutes: durationMins,
      estimatedClipCount: estClips
    });
  }, [script, clipDuration]);

  // Toast Timer
  useEffect(() => {
    if (showToast) {
      const timer = setTimeout(() => setShowToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [showToast]);

  // Auto-scroll
  useEffect(() => {
    if (status === GenerationStatus.GENERATING && clips.length > 0) {
      bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [clips.length, status]);

  const formatTime = (ms: number) => {
    if (!isFinite(ms) || ms < 0) return '--:--';
    const totalSeconds = Math.floor(ms / 1000);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}m ${seconds.toString().padStart(2, '0')}s`;
  };

  const handleRegenerateClip = async (clipId: string, instruction: string) => {
    const clipToRegenerate = clips.find(c => c.id === clipId);
    if (!clipToRegenerate) return;

    setRegeneratingIds(prev => new Set(prev).add(clipId));

    try {
      const updatedClip = await geminiService.regenerateClip(clipToRegenerate, settings, instruction, outputFormat);
      setClips(prevClips => prevClips.map(c => c.id === clipId ? updatedClip : c));
    } catch (error) {
      console.error("Failed to regenerate clip", error);
    } finally {
      setRegeneratingIds(prev => {
        const next = new Set(prev);
        next.delete(clipId);
        return next;
      });
    }
  };

  // --- PROJECT IMPORT / EXPORT LOGIC ---

  const handleExportProject = () => {
    const { characters, ...globalStyle } = settings;
    const exportData: ProjectExportData = {
      script,
      pacing: `${clipDuration}s`,
      outputFormat,
      globalStyle,
      characters
    };

    const jsonString = JSON.stringify(exportData, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `project_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setShowToast("✅ Project exported successfully!");
  };

  const handleImportProject = (jsonString: string): { success: boolean; message?: string } => {
    let data: any = {};
    let isPartialRawMode = false;

    // STEP 1: Strict JSON Parse Attempt (with Auto-Wrap)
    let processedInput = jsonString.trim();
    if (processedInput.length > 0 && !processedInput.startsWith('{') && !processedInput.startsWith('[')) {
      processedInput = `{${processedInput}}`;
    }

    try {
      data = JSON.parse(processedInput);
    } catch (e) {
      // STEP 2: Fallback to Regex Scanning (Fuzzy Mode)
      // If JSON fails, we don't throw, we just try to scrape keys.
      isPartialRawMode = true;
      const regex = /"?([a-zA-Z0-9_&]+)"?\s*:\s*["']([^"']+)["']/g;
      let match;
      let matchesFound = false;

      while ((match = regex.exec(jsonString)) !== null) {
        matchesFound = true;
        const key = match[1];
        const value = match[2];
        data[key] = value;
      }

      // If we found absolutely nothing in regex scan, then we fail.
      if (!matchesFound) {
        return { success: false, message: "Invalid syntax. Could not parse JSON or find any key-value pairs." };
      }
    }

    let hasUpdates = false;

    // 1. Script (Check root level and common aliases)
    const scriptVal = data.script || data.video_script || data.source_script?.text;
    if (scriptVal && typeof scriptVal === 'string') {
      setScript(scriptVal);
      hasUpdates = true;
    }

    // 2. Pacing
    const pacingVal = data.pacing || data.clip_duration || data.pacing_seconds || data.timing_data?.duration;
    if (pacingVal) {
      const cleanPacing = parseInt(String(pacingVal).replace(/s|seconds/gi, ''));
      if (CLIP_DURATIONS.includes(cleanPacing as any)) {
        setClipDuration(cleanPacing as ClipDuration);
        hasUpdates = true;
      }
    }

    // 3. Output Format
    const formatVal = data.outputFormat || data.output_format;
    if (formatVal === 'json' || formatVal === 'standard') {
      setOutputFormat(formatVal);
      hasUpdates = true;
    }

    // 4. Smart Style Mapping
    // Check for style keys at root level OR inside a nested object (globalStyle, style, style_engine_parameters)
    // We prioritize specific objects but fall back to root.
    const styleSources = [data, data.globalStyle, data.style, data.global_style, data.style_engine_parameters].filter(Boolean);

    const findKey = (candidates: string[]) => {
      for (const source of styleSources) {
        for (const key of candidates) {
          if (source[key] !== undefined && source[key] !== null) return source[key];
        }
      }
      return undefined;
    };

    const newSettings = { ...settings }; // Start with current settings to allow partial updates
    let styleUpdated = false;

    // Visual Style
    const visualStyle = findKey(['visualStyle', 'visual_style', 'VISUAL_STYLE', 'visual_aesthetic', 'aesthetic']);
    if (visualStyle) { newSettings.visualStyle = visualStyle; styleUpdated = true; }

    // Mood
    const mood = findKey(['mood', 'mood_tone', 'MOOD_&_TONE', 'atmosphere', 'emotional_beat']);
    if (mood) { newSettings.mood = mood; styleUpdated = true; }

    // Lighting
    const lighting = findKey(['lighting', 'lighting_style', 'LIGHTING_STYLE', 'lighting_setup']);
    if (lighting) { newSettings.lighting = lighting; styleUpdated = true; }

    // Camera Style
    const cameraStyle = findKey(['cameraStyle', 'camera_style', 'CAMERA_STYLE', 'camera_angle', 'camera_architecture']);
    if (typeof cameraStyle === 'object' && cameraStyle.angle) {
        newSettings.cameraStyle = cameraStyle.angle;
        styleUpdated = true;
    } else if (typeof cameraStyle === 'string') {
        newSettings.cameraStyle = cameraStyle;
        styleUpdated = true;
    }

    // Camera Movement
    const movement = findKey(['cameraMovement', 'camera_movement', 'CAMERA_MOVEMENT', 'movement']);
    // Handle the Detailed JSON structure where movement is inside camera_architecture
    const deepMovement = data.style_engine_parameters?.camera_architecture?.movement;
    if (deepMovement) {
       newSettings.cameraMovement = deepMovement;
       styleUpdated = true;
    } else if (movement) {
       newSettings.cameraMovement = movement;
       styleUpdated = true;
    }

    // Art Keywords
    // UPDATED: Added aliases for ART_DIRECTION_KEYWORDS and art_direction_keywords
    const keywords = findKey(['artKeywords', 'art_keywords', 'keywords', 'texture_keywords', 'ART_DIRECTION_KEYWORDS', 'art_direction_keywords']);
    if (keywords) {
      newSettings.artKeywords = Array.isArray(keywords) ? keywords.join(', ') : keywords;
      styleUpdated = true;
    }

    // Color Palette
    // UPDATED: Added COLOR_PALETTE_HEX alias and mapped Color_1, Color_2, Color_3 fields
    // Also supports finding keys directly at root (via findKey) if container is missing
    const paletteContainer = findKey(['colorPalette', 'color_palette', 'COLOR_PALETTE', 'colors', 'color_grading', 'COLOR_PALETTE_HEX']);

    const pPrimary = (paletteContainer?.primary || paletteContainer?.hex_1 || paletteContainer?.Color_1 || paletteContainer?.color_1) || 
                     findKey(['Color_1', 'color_1', 'primary_color', 'primary']);

    const pSecondary = (paletteContainer?.secondary || paletteContainer?.hex_2 || paletteContainer?.Color_2 || paletteContainer?.color_2) || 
                       findKey(['Color_2', 'color_2', 'secondary_color', 'secondary']);

    const pAccent = (paletteContainer?.accent || paletteContainer?.hex_3 || paletteContainer?.Color_3 || paletteContainer?.color_3) || 
                    findKey(['Color_3', 'color_3', 'accent_color', 'accent']);

    if (pPrimary || pSecondary || pAccent) {
      newSettings.colorPalette = {
        primary: pPrimary || newSettings.colorPalette.primary,
        secondary: pSecondary || newSettings.colorPalette.secondary,
        accent: pAccent || newSettings.colorPalette.accent
      };
      styleUpdated = true;
    }

    // Characters
    const chars = findKey(['characters', 'cast', 'character_profiles']);
    if (Array.isArray(chars)) {
      newSettings.characters = chars;
      styleUpdated = true;
    }

    if (styleUpdated) {
      setSettings(newSettings);
      hasUpdates = true;
    }

    if (hasUpdates) {
      if (isPartialRawMode) {
        setShowToast("⚠️ Loaded data partially from raw text scan.");
      } else {
        setShowToast("✅ Project updated successfully!");
      }
      return { success: true };
    } else {
      const detectedKeys = Object.keys(data).slice(0, 5).join(", ");
      return { 
        success: false, 
        message: `Parsed data, but no recognizable fields were found. Detected keys: [${detectedKeys}...]` 
      };
    }
  };

  // --- BATCH GENERATION LOGIC ---

  const processScriptQueue = async (startIndex: number, endIndex: number, chunks: string[]) => {
    if (stopGenerationRef.current) return;

    if (startIndex >= endIndex) {
      if (endIndex === chunks.length) {
        setStatus(GenerationStatus.SUCCESS);
        setProgress(prev => ({ ...prev, current: chunks.length, currentStep: 'Generation Complete!' }));
        setEstTimeRemaining('0m 00s');
      } else {
        setStatus(GenerationStatus.WAITING_APPROVAL);
      }
      return;
    }

    const batchLimit = Math.min(startIndex + BATCH_SIZE, endIndex);
    const currentBatchNumber = Math.floor(startIndex / BATCH_SIZE) + 1;
    const isPhase1 = endIndex <= 10;
    const phaseLabel = isPhase1 ? "Phase 1: Test Run" : "Phase 3: Full Run";

    setStatus(GenerationStatus.GENERATING);
    setErrorMsg(null);

    for (let i = startIndex; i < batchLimit; i++) {
      if (stopGenerationRef.current) break;

      const clipNum = i + 1;
      setProgress(prev => ({ 
        ...prev, 
        current: i, 
        currentStep: `${phaseLabel} - Batch ${currentBatchNumber} (Clip ${clipNum}/${chunks.length})` 
      }));

      try {
        if (!clips.find(c => c.clipNumber === clipNum)) {
          const newClip = await geminiService.generateSingleClip(chunks[i], clipNum, settings, clipDuration, outputFormat);
          setClips(prev => [...prev, newClip]);

          itemsProcessedInSessionRef.current += 1;
          const elapsed = Date.now() - sessionStartTimeRef.current;
          const avgTimePerClip = elapsed / itemsProcessedInSessionRef.current;
          const remainingClips = endIndex - (i + 1);
          const estimatedRemainingMs = avgTimePerClip * remainingClips;
          setEstTimeRemaining(formatTime(estimatedRemainingMs));
        }
        setNextClipIndex(i + 1);

      } catch (err: any) {
        console.error("Batch Error:", err);
        stopGenerationRef.current = true;
        setStatus(GenerationStatus.ERROR);
        setErrorMsg(`Failed at Batch ${currentBatchNumber} (Clip ${clipNum}). Error: ${err.message || 'API Error'}`);
        return; 
      }
    }

    if (!stopGenerationRef.current) {
      setTimeout(() => {
        processScriptQueue(batchLimit, endIndex, chunks);
      }, 100);
    }
  };

  const startSessionTracking = () => {
    sessionStartTimeRef.current = Date.now();
    itemsProcessedInSessionRef.current = 0;
    setEstTimeRemaining('Calculating...');
  };

  const handleInitialGenerate = async () => {
    if (!script.trim()) return;

    setClips([]);
    setErrorMsg(null);
    setNextClipIndex(0);
    setStatus(GenerationStatus.PREPARING);
    stopGenerationRef.current = false;
    startSessionTracking();

    const chunks = geminiService.splitScriptToChunks(script, clipDuration);
    setScriptChunks(chunks);
    setProgress({ current: 0, total: chunks.length, currentStep: 'Analyzing Script Structure...' });

    const firstBatchEnd = chunks.length <= 10 ? chunks.length : 10;
    await processScriptQueue(0, firstBatchEnd, chunks);
  };

  const handleApproveAndContinue = async () => {
    if (status !== GenerationStatus.WAITING_APPROVAL && status !== GenerationStatus.ERROR) return;
    stopGenerationRef.current = false;
    startSessionTracking();
    await processScriptQueue(nextClipIndex, scriptChunks.length, scriptChunks);
  };

  const handleRetry = async () => {
    if (status !== GenerationStatus.ERROR) return;
    stopGenerationRef.current = false;
    startSessionTracking();

    const isTestBatchPhase = scriptChunks.length > 10 && nextClipIndex < 10;
    const targetEnd = isTestBatchPhase ? 10 : scriptChunks.length;

    await processScriptQueue(nextClipIndex, targetEnd, scriptChunks);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-gray-200 pb-20 relative">
      {/* Toast Notification */}
      {showToast && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-green-600 text-white px-6 py-3 rounded-full shadow-2xl font-bold flex items-center gap-2 animate-in fade-in slide-in-from-top-4">
          <CheckCircle size={20} /> {showToast}
        </div>
      )}

      {/* Import Modal */}
      <ProjectImportModal 
        isOpen={isImportModalOpen} 
        onClose={() => setIsImportModalOpen(false)}
        onImport={handleImportProject}
      />

      {/* Navbar / Header */}
      <header className="bg-[#0f172a]/80 backdrop-blur-md border-b border-gray-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-900/50">
              <Sparkles className="text-white w-6 h-6" />
            </div>
            <h1 className="text-2xl font-bold text-white tracking-tight">
              Video Script to <span className="text-blue-500">Prompt Elite 2.0</span>
            </h1>
          </div>

          <div className="flex items-center gap-3">
