  const ai = getAIClient();

  // Construct Character Bible text
  const characterProtocol = settings.characters.length > 0 
    ? `
    >>> CHARACTER CONSISTENCY PROTOCOL (MANDATORY) <<<
    You must scan the script for the following characters. If found, you MUST use their "Fixed Visual Anchor" description instead of generic terms.

    ${settings.characters.map(c => 
      `NAME: "${c.name}"
       VISUAL ANCHOR: "${c.description}"
       FACE LOCK: ${c.isFaceLocked ? "ON (Must append: 'Consistent facial features, identical character model')" : "OFF"}
       STYLE OVERRIDE: ${c.visualStyle || 'Default'}, ${c.mood || 'Default'}, ${c.lighting || 'Default'}`
    ).join('\n\n')}

    RULES:
    1. If script says "${settings.characters[0]?.name || 'Name'} walks", prompt must say "${settings.characters[0]?.description || 'Description'} walks...".
    2. Do NOT use pronouns like "She" or "He" at the start of the prompt. Always use the full visual anchor.
    3. If Face Lock is ON, ensure the prompt ends with the consistency phrase.
    4. If a character with a STYLE OVERRIDE appears, subtly blend their specific style preferences (e.g. lighting/mood) into the visual prompt for that specific clip.
    `
    : "No specific characters defined. Use generic but consistent descriptions.";

  // Calculate Timing Context
  const startTime = (clipNumber - 1) * clipDuration;
  const endTime = clipNumber * clipDuration;
  const timingContext = `Timing: Start ${startTime}s, End ${endTime}s, Duration ${clipDuration}s`;

  // --- STANDARD MODE SCHEMA ---
  const standardSchema = {
    type: Type.OBJECT,
    properties: {
      scriptLine: { type: Type.STRING, description: "The exact script text provided." },
      narrativeContext: { type: Type.STRING, description: "40-80 words explaining the action and story beat." },
      visualPrompt: { type: Type.STRING, description: "100-150 words. The final, strict prompt starting with 'Clean video, no text.'." }
    },
    required: ["scriptLine", "narrativeContext", "visualPrompt"]
  };

  // --- DETAILED JSON MODE SCHEMA ---
  const detailedJsonSchema = {
    type: Type.OBJECT,
    properties: {
      sequence_id: { type: Type.INTEGER },
      timing_data: {
        type: Type.OBJECT,
        properties: {
          start: { type: Type.STRING },
          end: { type: Type.STRING },
          duration: { type: Type.STRING }
        }
      },
      source_script: {
        type: Type.OBJECT,
        properties: {
          text: { type: Type.STRING },
          word_count: { type: Type.INTEGER }
        }
      },
      narrative_logic: {
        type: Type.OBJECT,
        properties: {
          context: { type: Type.STRING },
          emotional_beat: { type: Type.STRING }
        }
      },
      style_engine_parameters: {
        type: Type.OBJECT,
        properties: {
          visual_aesthetic: { type: Type.STRING },
          lighting_setup: { type: Type.STRING },
          camera_architecture: {
            type: Type.OBJECT,
            properties: {
               angle: { type: Type.STRING },
               movement: { type: Type.STRING }
            }
          },
          color_grading: {
            type: Type.OBJECT,
            properties: {
              primary: { type: Type.STRING },
              secondary: { type: Type.STRING },
              accent: { type: Type.STRING },
              description: { type: Type.STRING }
            }
          },
          texture_keywords: { type: Type.ARRAY, items: { type: Type.STRING } }
        }
      },
      character_anchor: {
        type: Type.OBJECT,
        properties: {
          present: { type: Type.BOOLEAN },
          name: { type: Type.STRING },
          visual_description: { type: Type.STRING }
        }
      },
      composition_build: {
        type: Type.OBJECT,
        properties: {
          subject_action: { type: Type.STRING },
          environment_detail: { type: Type.STRING },
          negative_constraints: { type: Type.STRING }
        }
      },
      final_veo_prompt: { type: Type.STRING }
    },
    required: ["sequence_id", "timing_data", "source_script", "narrative_logic", "style_engine_parameters", "composition_build", "final_veo_prompt"]
  };

  const isJsonMode = outputFormat === 'json';

  const systemInstruction = `You are an elite Video Prompt Engineer for Google Veo 3.1.

  MODE: ${isJsonMode ? "ULTIMATE TECHNICAL JSON" : "STANDARD NARRATIVE"}

  STRICT RULES FOR OUTPUT:
  1. JSON STRUCTURE: You must output a valid JSON object matching the schema exactly. Do not add or remove keys.
  2. "CLEAN VIDEO" MANDATE: The final prompt (visualPrompt or final_veo_prompt) MUST start with the exact phrase: "Clean video, no text."
