    });

    const jsonStr = response.text;
    if (!jsonStr) throw new Error("Empty response from AI");

    const data = JSON.parse(jsonStr);

    if (isJsonMode) {
      return {
        id: crypto.randomUUID(),
        clipNumber: clipNumber,
        scriptLine: data.source_script?.text || chunkText,
        narrativeContext: data.narrative_logic?.context || "",
        visualPrompt: data.final_veo_prompt || "",
        jsonOutput: data
