import { GoogleGenAI, Type } from "@google/genai";
import { StyleSettings, GeneratedClip, ClipDuration, OutputFormat } from "../types";
import { 
  VISUAL_STYLES, 
  LIGHTING_OPTIONS, 
  MOOD_OPTIONS, 
  CAMERA_STYLES, 
  CAMERA_MOVEMENTS 
} from '../constants';

const getAIClient = () => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

// Helper: Split script into chunks based on specific user formula
// Formula: Script Word Count / 200 = Video Duration (minutes)
// Therefore: 200 words per 60 seconds.
const splitScriptToChunks = (script: string, clipDuration: ClipDuration): string[] => {
  // Calculate words per clip based on the 200 words/min formula
  // For 8s: (200 / 60) * 8 = 26.666 => ~27 words.
  const wordsPerSecond = 200 / 60;
  const targetWordsPerChunk = Math.round(wordsPerSecond * clipDuration);

  // Split by sentence endings to preserve narrative flow where possible, 
  // but strictly adhere to length limits close to the target.
  const sentenceRegex = /[^.!?]+[.!?]+["']?|[^.!?]+$/g;
  const sentences = script.match(sentenceRegex) || [script];

  const chunks: string[] = [];
  let currentChunk = "";
  let currentWordCount = 0;

  for (const sentence of sentences) {
    const sentenceWordCount = sentence.trim().split(/\s+/).length;

    // If adding this sentence exceeds the target significantly (allow +10% buffer), push current chunk
    if (currentWordCount + sentenceWordCount > targetWordsPerChunk * 1.1 && currentChunk.length > 0) {
      chunks.push(currentChunk.trim());
      currentChunk = sentence;
      currentWordCount = sentenceWordCount;
    } else {
      currentChunk += " " + sentence;
      currentWordCount += sentenceWordCount;
    }
  }

  if (currentChunk.trim().length > 0) {
    chunks.push(currentChunk.trim());
  }

  return chunks;
};

// Analyze video reference to extract style
const analyzeVideoStyle = async (videoBase64: string, mimeType: string): Promise<Partial<StyleSettings>> => {
  const ai = getAIClient();

  const systemInstruction = `You are a Senior Colorist and Director of Photography. 
  Analyze the provided video clip to extract its exact stylistic attributes.

  You must map your analysis to the following available presets where possible:
  - Visual Styles: ${VISUAL_STYLES.join(", ")}
  - Lighting: ${LIGHTING_OPTIONS.join(", ")}
  - Mood: ${MOOD_OPTIONS.join(", ")}
  - Camera Style: ${CAMERA_STYLES.join(", ")}
  - Camera Movement: ${CAMERA_MOVEMENTS.join(", ")}

  For 'artKeywords', provide a comma-separated list of highly specific technical terms observed in the video (e.g., "anamorphic lens flare, teal and orange grading, volumetric fog, 8mm grain").
  For 'colorPalette', extract the 3 dominant hex codes.
  `;

  const prompt = "Analyze this video and return the style settings that best match the visual input.";

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview", // upgraded model for better vision analysis
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType, data: videoBase64 } },
          { text: prompt }
        ]
      },
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            visualStyle: { type: Type.STRING, enum: VISUAL_STYLES },
            colorPalette: {
              type: Type.OBJECT,
              properties: {
                primary: { type: Type.STRING, description: "Hex code" },
                secondary: { type: Type.STRING, description: "Hex code" },
                accent: { type: Type.STRING, description: "Hex code" }
              }
            },
            mood: { type: Type.STRING, enum: MOOD_OPTIONS },
            lighting: { type: Type.STRING, enum: LIGHTING_OPTIONS },
            cameraStyle: { type: Type.STRING, enum: CAMERA_STYLES },
            cameraMovement: { type: Type.STRING, enum: CAMERA_MOVEMENTS },
            artKeywords: { type: Type.STRING, description: "Comma separated technical keywords" }
          },
          required: ["visualStyle", "colorPalette", "mood", "lighting", "cameraStyle", "cameraMovement", "artKeywords"]
        }
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) throw new Error("No analysis result");
    return JSON.parse(jsonStr);

  } catch (error) {
    console.error("Video Analysis Error:", error);
    throw error;
  }
};

// Analyze character image to generate text description
