import React, { useState } from 'react';
import { GeneratedClip } from '../types';
import { Copy, Check, Video, FileText, Camera, RefreshCw, X, ArrowRight, Loader2, Code, FileJson } from 'lucide-react';

interface PromptCardProps {
  clip: GeneratedClip;
  onRegenerate: (clipId: string, instruction: string) => Promise<void>;
  isRegenerating: boolean;
}

export const PromptCard: React.FC<PromptCardProps> = ({ clip, onRegenerate, isRegenerating }) => {
  const [copied, setCopied] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  // Default to showing JSON if JSON output exists
  const [showJson, setShowJson] = useState(!!clip.jsonOutput);

  const [feedback, setFeedback] = useState('');

  const handleCopy = () => {
    navigator.clipboard.writeText(clip.visualPrompt);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleCopyJson = () => {
    if (clip.jsonOutput) {
      navigator.clipboard.writeText(JSON.stringify(clip.jsonOutput, null, 2));
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const handleRegenerateSubmit = async () => {
    if (isRegenerating) return;
    const instruction = feedback.trim() || "Regenerate with a different variation";
    await onRegenerate(clip.id, instruction);
    setIsEditing(false);
    setFeedback('');
  };

  return (
    <div className="bg-[#1a202c] border border-gray-700 rounded-xl overflow-hidden hover:border-blue-500/50 transition-colors duration-300 relative">

      {/* Loading Overlay */}
      {isRegenerating && (
        <div className="absolute inset-0 bg-[#1a202c]/80 backdrop-blur-sm z-20 flex flex-col items-center justify-center animate-in fade-in duration-200">
          <Loader2 className="animate-spin text-blue-500 w-8 h-8 mb-2" />
          <p className="text-blue-200 text-sm font-medium animate-pulse">Regenerating...</p>
        </div>
      )}

      {/* Header */}
      <div className="bg-[#2d3748] px-4 py-2 flex justify-between items-center border-b border-gray-700">
        <div className="flex items-center gap-2">
          <span className="text-xs font-bold bg-blue-900 text-blue-200 px-2 py-1 rounded">
            CLIP {String(clip.clipNumber).padStart(2, '0')}
          </span>
          {clip.jsonOutput && (
            <span className="text-[10px] font-bold bg-purple-900/50 text-purple-300 px-2 py-1 rounded border border-purple-500/30 flex items-center gap-1">
              <FileJson size={10} /> JSON
            </span>
          )}
        </div>
        <div className="flex items-center gap-3">
           <div className="text-xs text-gray-400 font-mono">~8.0s</div>
           {!isEditing && (
             <button 
               onClick={() => setIsEditing(true)}
               className="p-1 hover:bg-gray-600 rounded text-gray-400 hover:text-white transition-colors"
               title="Regenerate this clip"
             >
               <RefreshCw size={14} />
             </button>
           )}
        </div>
      </div>

      {/* Regeneration Input Panel */}
      {isEditing && (
        <div className="bg-blue-900/10 border-b border-blue-500/30 p-4 animate-in slide-in-from-top-2">
          <div className="flex justify-between items-start mb-2">
            <label className="text-xs font-bold text-blue-300 uppercase">Custom Modification</label>
            <button 
              onClick={() => setIsEditing(false)}
              className="text-gray-400 hover:text-white"
            >
              <X size={14} />
            </button>
          </div>
          <div className="flex gap-2">
            <input 
              type="text" 
              value={feedback}
              onChange={(e) => setFeedback(e.target.value)}
              placeholder="e.g. 'Make it night time', 'Remove the car', 'Use a drone shot'..."
              className="flex-1 bg-[#0e1117] border border-blue-500/30 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-blue-500"
              onKeyDown={(e) => e.key === 'Enter' && handleRegenerateSubmit()}
              autoFocus
            />
            <button 
              onClick={handleRegenerateSubmit}
              className="bg-blue-600 hover:bg-blue-500 text-white p-2 rounded-lg transition-colors"
            >
              <ArrowRight size={16} />
            </button>
          </div>
        </div>
      )}

      {/* JSON Toggle View */}
      {clip.jsonOutput && (
         <div className="px-5 pt-3 flex justify-end">
           <button 
             onClick={() => setShowJson(!showJson)}
             className="text-xs flex items-center gap-1 text-gray-500 hover:text-purple-400 transition-colors"
           >
             <Code size={12} /> {showJson ? "Hide JSON Source" : "View JSON Source"}
           </button>
         </div>
      )}

      <div className="p-5 space-y-5">

        {showJson && clip.jsonOutput ? (
          <div className="space-y-4">
             {/* Script Line Header for JSON View */}
            <div>
              <div className="flex items-center gap-2 mb-1 text-gray-400 text-xs font-semibold uppercase tracking-wider">
                <FileText size={14} /> Script Line
              </div>
              <div className="text-lg font-serif text-white italic border-l-2 border-blue-500 pl-3 py-1">
                "{clip.scriptLine}"
              </div>
            </div>

            <div className="relative group">
              <pre className="bg-[#0e1117] p-4 rounded-lg border border-purple-500/30 text-xs text-green-400 font-mono overflow-x-auto whitespace-pre-wrap">
                {JSON.stringify(clip.jsonOutput, null, 2)}
              </pre>
              <button
                onClick={handleCopyJson}
                className="absolute top-2 right-2 p-2 rounded-md bg-gray-800 hover:bg-purple-600 text-gray-400 hover:text-white transition-all border border-gray-700 hover:border-purple-500"
                title="Copy JSON"
              >
                {copied ? <Check size={14} /> : <Copy size={14} />}
              </button>
            </div>
          </div>
        ) : (
          <>
            {/* Script Line */}
            <div>
              <div className="flex items-center gap-2 mb-1 text-gray-400 text-xs font-semibold uppercase tracking-wider">
                <FileText size={14} /> Script Line
              </div>
              <div className="text-lg font-serif text-white italic border-l-2 border-blue-500 pl-3 py-1">
                "{clip.scriptLine}"
              </div>
            </div>

            {/* Narrative Context */}
            <div>
              <div className="flex items-center gap-2 mb-1 text-gray-400 text-xs font-semibold uppercase tracking-wider">
                <Video size={14} /> Context
              </div>
              <p className="text-gray-300 text-sm leading-relaxed">
                {clip.narrativeContext}
              </p>
            </div>

            {/* The Prompt */}
            <div className="bg-[#0e1117] rounded-lg border border-gray-800 p-4 relative group">
              <div className="flex items-center gap-2 mb-2 text-purple-400 text-xs font-semibold uppercase tracking-wider">
                <Camera size={14} /> AI Video Prompt
              </div>
              <p className="text-sm text-gray-200 font-mono leading-relaxed pb-6">
                {clip.visualPrompt}
              </p>

              <button
                onClick={handleCopy}
                className="absolute bottom-2 right-2 p-2 rounded-md bg-gray-800 hover:bg-blue-600 text-gray-400 hover:text-white transition-all border border-gray-700 hover:border-blue-500"
                title="Copy Prompt"
              >
                {copied ? <Check size={16} /> : <Copy size={16} />}
              </button>
            </div>
          </>
        )}

      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { StyleSettings, GeneratedClip, ClipDuration, OutputFormat } from "../types";
import { 
  VISUAL_STYLES, 
  LIGHTING_OPTIONS, 
  MOOD_OPTIONS, 
  CAMERA_STYLES, 
  CAMERA_MOVEMENTS 
} from '../constants';

const getAIClient = () => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

// Helper: Split script into chunks based on specific user formula
// Formula: Script Word Count / 200 = Video Duration (minutes)
// Therefore: 200 words per 60 seconds.
const splitScriptToChunks = (script: string, clipDuration: ClipDuration): string[] => {
  // Calculate words per clip based on the 200 words/min formula
  // For 8s: (200 / 60) * 8 = 26.666 => ~27 words.
  const wordsPerSecond = 200 / 60;
  const targetWordsPerChunk = Math.round(wordsPerSecond * clipDuration);

  // Split by sentence endings to preserve narrative flow where possible, 
  // but strictly adhere to length limits close to the target.
  const sentenceRegex = /[^.!?]+[.!?]+["']?|[^.!?]+$/g;
  const sentences = script.match(sentenceRegex) || [script];

  const chunks: string[] = [];
  let currentChunk = "";
  let currentWordCount = 0;

  for (const sentence of sentences) {
    const sentenceWordCount = sentence.trim().split(/\s+/).length;

    // If adding this sentence exceeds the target significantly (allow +10% buffer), push current chunk
    if (currentWordCount + sentenceWordCount > targetWordsPerChunk * 1.1 && currentChunk.length > 0) {
      chunks.push(currentChunk.trim());
      currentChunk = sentence;
      currentWordCount = sentenceWordCount;
    } else {
      currentChunk += " " + sentence;
      currentWordCount += sentenceWordCount;
    }
  }

  if (currentChunk.trim().length > 0) {
    chunks.push(currentChunk.trim());
  }

  return chunks;
};

// Analyze video reference to extract style
const analyzeVideoStyle = async (videoBase64: string, mimeType: string): Promise<Partial<StyleSettings>> => {
  const ai = getAIClient();

  const systemInstruction = `You are a Senior Colorist and Director of Photography. 
  Analyze the provided video clip to extract its exact stylistic attributes.

  You must map your analysis to the following available presets where possible:
  - Visual Styles: ${VISUAL_STYLES.join(", ")}
  - Lighting: ${LIGHTING_OPTIONS.join(", ")}
  - Mood: ${MOOD_OPTIONS.join(", ")}
  - Camera Style: ${CAMERA_STYLES.join(", ")}
  - Camera Movement: ${CAMERA_MOVEMENTS.join(", ")}

  For 'artKeywords', provide a comma-separated list of highly specific technical terms observed in the video (e.g., "anamorphic lens flare, teal and orange grading, volumetric fog, 8mm grain").
  For 'colorPalette', extract the 3 dominant hex codes.
  `;

  const prompt = "Analyze this video and return the style settings that best match the visual input.";

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview", // upgraded model for better vision analysis
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType, data: videoBase64 } },
          { text: prompt }
        ]
      },
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            visualStyle: { type: Type.STRING, enum: VISUAL_STYLES },
            colorPalette: {
              type: Type.OBJECT,
              properties: {
                primary: { type: Type.STRING, description: "Hex code" },
                secondary: { type: Type.STRING, description: "Hex code" },
                accent: { type: Type.STRING, description: "Hex code" }
              }
            },
            mood: { type: Type.STRING, enum: MOOD_OPTIONS },
            lighting: { type: Type.STRING, enum: LIGHTING_OPTIONS },
            cameraStyle: { type: Type.STRING, enum: CAMERA_STYLES },
            cameraMovement: { type: Type.STRING, enum: CAMERA_MOVEMENTS },
            artKeywords: { type: Type.STRING, description: "Comma separated technical keywords" }
          },
          required: ["visualStyle", "colorPalette", "mood", "lighting", "cameraStyle", "cameraMovement", "artKeywords"]
        }
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) throw new Error("No analysis result");
    return JSON.parse(jsonStr);

  } catch (error) {
    console.error("Video Analysis Error:", error);
    throw error;
  }
};

// Analyze character image to generate text description
const analyzeCharacterImage = async (imageBase64: string, mimeType: string): Promise<string> => {
  const ai = getAIClient();

  const systemInstruction = `You are a Character Designer for Film.
  Analyze this character image. Write a precise, 40-word physical description suitable for a video generation prompt.
  Focus STRICTLY on: Age, Gender, Ethnicity, Hairstyle/Color, Clothing (Style/Color), and Distinctive Facial Features.
  Do not describe the background, lighting, or pose. Output only the description string.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType, data: imageBase64 } },
          { text: "Describe this character's physical appearance for a prompt." }
        ]
      },
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "text/plain",
      }
    });

    return response.text || "Could not analyze character.";
  } catch (error) {
    console.error("Character Analysis Error:", error);
    throw new Error("Failed to analyze character image.");
  }
};

const generateSingleClip = async (
  chunkText: string,
  clipNumber: number,
  settings: StyleSettings,
  clipDuration: ClipDuration,
  outputFormat: OutputFormat
): Promise<GeneratedClip> => {
  const ai = getAIClient();

  // Construct Character Bible text
  const characterProtocol = settings.characters.length > 0 
    ? `
    >>> CHARACTER CONSISTENCY PROTOCOL (MANDATORY) <<<
    You must scan the script for the following characters. If found, you MUST use their "Fixed Visual Anchor" description instead of generic terms.

    ${settings.characters.map(c => 
      `NAME: "${c.name}"
       VISUAL ANCHOR: "${c.description}"
       FACE LOCK: ${c.isFaceLocked ? "ON (Must append: 'Consistent facial features, identical character model')" : "OFF"}
       STYLE OVERRIDE: ${c.visualStyle || 'Default'}, ${c.mood || 'Default'}, ${c.lighting || 'Default'}`
    ).join('\n\n')}

    RULES:
    1. If script says "${settings.characters[0]?.name || 'Name'} walks", prompt must say "${settings.characters[0]?.description || 'Description'} walks...".
    2. Do NOT use pronouns like "She" or "He" at the start of the prompt. Always use the full visual anchor.
    3. If Face Lock is ON, ensure the prompt ends with the consistency phrase.
    4. If a character with a STYLE OVERRIDE appears, subtly blend their specific style preferences (e.g. lighting/mood) into the visual prompt for that specific clip.
    `
    : "No specific characters defined. Use generic but consistent descriptions.";

  // Calculate Timing Context
  const startTime = (clipNumber - 1) * clipDuration;
  const endTime = clipNumber * clipDuration;
  const timingContext = `Timing: Start ${startTime}s, End ${endTime}s, Duration ${clipDuration}s`;

  // --- STANDARD MODE SCHEMA ---
  const standardSchema = {
    type: Type.OBJECT,
    properties: {
      scriptLine: { type: Type.STRING, description: "The exact script text provided." },
      narrativeContext: { type: Type.STRING, description: "40-80 words explaining the action and story beat." },
      visualPrompt: { type: Type.STRING, description: "100-150 words. The final, strict prompt starting with 'Clean video, no text.'." }
    },
    required: ["scriptLine", "narrativeContext", "visualPrompt"]
  };

  // --- PRODUCTION JSON SCHEMA (The "SWAP_ME" Schema) ---
  const detailedJsonSchema = {
    type: Type.OBJECT,
    properties: {
      sequence_id: { type: Type.INTEGER },
      visual_engine: {
        type: Type.OBJECT,
        properties: {
          style_preset: { type: Type.STRING },
          aesthetic_keywords: { type: Type.ARRAY, items: { type: Type.STRING } },
          color_palette_hex: { type: Type.STRING }
        }
      },
      camera_engine: {
        type: Type.OBJECT,
        properties: {
          style: { type: Type.STRING },
          movement: { type: Type.STRING },
          lens_suggestion: { type: Type.STRING }
        }
      },
      lighting_engine: {
        type: Type.OBJECT,
        properties: {
          setup: { type: Type.STRING },
          mood: { type: Type.STRING },
          key_light_color: { type: Type.STRING }
        }
      },
      narrative_layer: {
        type: Type.OBJECT,
        properties: {
          script_line: { type: Type.STRING },
          context_summary: { type: Type.STRING },
          character_present: { type: Type.BOOLEAN }
        }
      },
      timeline_events: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            beat: { type: Type.STRING, enum: ["Start (0-25%)", "Middle (25-75%)", "End (75-100%)"] },
            action_description: { type: Type.STRING },
            camera_state: { type: Type.STRING }
          }
        }
      },
      final_veo_prompt: { type: Type.STRING }
    },
    required: ["sequence_id", "visual_engine", "camera_engine", "lighting_engine", "narrative_layer", "timeline_events", "final_veo_prompt"]
  };

  const isJsonMode = outputFormat === 'json';

  const systemInstruction = `You are an elite Video Prompt Engineer for Google Veo 3.1.

  MODE: ${isJsonMode ? "SWAP_ME PRODUCTION SCHEMA" : "STANDARD NARRATIVE"}

  >>> CORE DIRECTIVE: NATURAL LANGUAGE WEAVING <<<
  You are NOT a list dumper. You are a PROFESSIONAL ART DIRECTOR.
  You must weave the provided Global Style Context into a cohesive direction paragraph.

  GLOBAL STYLE CONTEXT (USER SETTINGS):
  - VISUAL AESTHETIC: "${settings.visualStyle}"
  - LIGHTING: "${settings.lighting}"
  - CAMERA: "${settings.cameraStyle}"
  - MOVEMENT: "${settings.cameraMovement}"
  - PALETTE: Primary ${settings.colorPalette.primary}, Secondary ${settings.colorPalette.secondary}
  - KEYWORDS: ${settings.artKeywords}

  ${isJsonMode ? `
  >>> JSON PRODUCTION MAPPING RULES (STRICT) <<<
  You MUST fill the JSON template by mapping the User Settings to these specific keys:

  1. visual_engine.style_preset = "${settings.visualStyle}"
  2. visual_engine.aesthetic_keywords = [${settings.artKeywords}] (Split into array)
  3. visual_engine.color_palette_hex = "${settings.colorPalette.primary}"
  4. camera_engine.movement = "${settings.cameraMovement}"
  5. camera_engine.style = "${settings.cameraStyle}"
  6. lighting_engine.setup = "${settings.lighting}"
  7. lighting_engine.mood = "${settings.mood}"
  8. lighting_engine.key_light_color = "${settings.colorPalette.primary}"
  9. narrative_layer.script_line = "${chunkText}" (Exact match)

  >>> TIMELINE EVENTS GENERATION <<<
  Generate exactly 3 timeline events based on the clip duration (${clipDuration}s):
  - "Start (0-25%)": Establish the ${settings.visualStyle} look.
  - "Middle (25-75%)": Execute the ${settings.cameraMovement} movement.
  - "End (75-100%)": Settle, transition, or fade.
  ` : ''}

  >>> PROMPT CONSTRUCTION FORMULA (MANDATORY) <<<
  The 'final_veo_prompt' (or 'visualPrompt') MUST be constructed using this "Weaving" structure:

  1. [SAFETY TAG]: Start with "Clean video, no text. No typography."
  2. [SCENE & STYLE]: "A [Visual Aesthetic: ${settings.visualStyle}] depicting [Subject & Action]..."
  3. [LIGHTING]: "The lighting is ${settings.lighting}, casting [specific shadow/highlight effects]."
  4. [CAMERA WEAVING]: "The camera performs a ${settings.cameraMovement}, revealing [Environment Detail]..." (Connect move to subject).
  5. [TEXTURE & COLOR WEAVING]: "The image features ${settings.artKeywords}, and the color palette is dominated by [Color Description] tones, specifically ${settings.colorPalette.primary} and ${settings.colorPalette.secondary}."
  6. [MOTION ENFORCER]:
     - IF style is "2.5D/Matte": Describe "parallax layer separation, drifting atmosphere, independent element movement".
     - IF style is "Vintage": Describe "film grain motion, projector jitter".
     - IF style is "Anime": Describe "limited frame rate, wind in hair".
     - GENERAL: Ensure the scene is ALIVE and matches the requested movement "${settings.cameraMovement}".

  STRICT RULES:
  1. JSON STRUCTURE: Output valid JSON exactly matching the schema.
  2. SCRIPT SYNC: Use the provided script line exactly.
  3. NO GENERIC TERMS: Do not say "Good lighting". Say "${settings.lighting}".
  ${isJsonMode ? '4. NEGATIVE CONSTRAINTS: In JSON mode, `negative_constraints` MUST include: "text, watermarks, subtitles, typography, split screen".' : ''}

  ${characterProtocol}

  CONTEXT: ${timingContext}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: `Generate Prompt for Clip #${clipNumber}. Script Segment: "${chunkText}"`,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: isJsonMode ? detailedJsonSchema : standardSchema
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) throw new Error("Empty response from AI");

    const data = JSON.parse(jsonStr);

    if (isJsonMode) {
      return {
        id: crypto.randomUUID(),
        clipNumber: clipNumber,
        scriptLine: data.narrative_layer?.script_line || chunkText,
        narrativeContext: data.narrative_layer?.context_summary || "",
        visualPrompt: data.final_veo_prompt || "",
        jsonOutput: data
      };
    } else {
      return {
        id: crypto.randomUUID(),
        clipNumber: clipNumber,
        scriptLine: data.scriptLine,
        narrativeContext: data.narrativeContext,
        visualPrompt: data.visualPrompt
      };
    }

  } catch (error) {
    console.error(`Error generating clip ${clipNumber}:`, error);
    throw error;
  }
};

const regenerateClip = async (
  originalClip: GeneratedClip,
  settings: StyleSettings,
  instruction: string,
  outputFormat: OutputFormat
): Promise<GeneratedClip> => {
  const ai = getAIClient();

  const characterProtocol = settings.characters.length > 0 
    ? `MAINTAIN CHARACTER CONSISTENCY for: ${settings.characters.map(c => c.name).join(', ')}.`
    : "";

  const systemInstruction = `You are an elite Video Prompt Engineer (Veo 3.1).
  Your task is to REGENERATE and REFINE a video prompt based on user feedback.

  STRICT RULES:
  1. START with "Clean video, no text. No typography."
  2. NATURAL LANGUAGE WEAVING: Do not dump keywords. Weave them into sentences.
     - "The image features [Keywords]..."
     - "The camera performs a ${settings.cameraMovement}, revealing..."
  3. LITERAL STYLE INJECTION: Ensure the visual style (${settings.visualStyle}) and movement (${settings.cameraMovement}) are explicitly described.
  4. MOTION ENFORCER: Ensure specific movement is described (Parallax, Grain, etc.).
  5. ${characterProtocol}

  ORIGINAL SCRIPT LINE: "${originalClip.scriptLine}" (Do not change this)

  CURRENT STYLE SETTINGS:
  - Visual: ${settings.visualStyle}
  - Mood: ${settings.mood}
  - Movement: ${settings.cameraMovement}

  USER MODIFICATION REQUEST: "${instruction}"

  PROMPT FORMULA:
  [SAFETY TAG] + [Visual Style] + [Subject Action w/ Mods] + [Camera Move connected to subject] + [Lighting sentence] + [Texture/Color sentence] + [Specific Motion].
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Regenerate Clip #${originalClip.clipNumber} with feedback: ${instruction}`,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            scriptLine: { type: Type.STRING },
            narrativeContext: { type: Type.STRING },
            visualPrompt: { type: Type.STRING }
          },
          required: ["scriptLine", "narrativeContext", "visualPrompt"]
        }
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) throw new Error("Empty response from AI");

    const data = JSON.parse(jsonStr);

    const updatedJson = originalClip.jsonOutput ? {
      ...originalClip.jsonOutput,
      final_veo_prompt: data.visualPrompt,
      narrative_layer: {
        ...originalClip.jsonOutput.narrative_layer,
        context_summary: data.narrativeContext
      }
    } : undefined;

    return {
      ...originalClip, // Keep original ID and clipNumber
      scriptLine: data.scriptLine, 
      narrativeContext: data.narrativeContext,
      visualPrompt: data.visualPrompt,
      jsonOutput: updatedJson
    };

  } catch (error) {
    console.error(`Error regenerating clip ${originalClip.clipNumber}:`, error);
    throw error;
  }
};

export const geminiService = {
  splitScriptToChunks,
  generateSingleClip,
  regenerateClip,
  analyzeVideoStyle,
  analyzeCharacterImage
};

