): Promise<GeneratedClip> => {
  const ai = getAIClient();

  const characterProtocol = settings.characters.length > 0 
    ? `MAINTAIN CHARACTER CONSISTENCY for: ${settings.characters.map(c => c.name).join(', ')}.`
    : "";

  const systemInstruction = `You are an elite Video Prompt Engineer (Veo 3.1).
  Your task is to REGENERATE and REFINE a video prompt based on user feedback.

  STRICT RULES:
  1. START with "Clean video, no text. No typography."
  2. REALISM ENFORCER: IF style is Matte/2.5D/Illustrated, REMOVE "cartoon/illustrative" terms and ADD "oil painting texture, 8k, masterpiece".
  3. NATURAL LANGUAGE WEAVING: Do not dump keywords. Weave them into sentences.
     - "The image features [Keywords]..."
     - "The camera performs a ${settings.cameraMovement}, revealing..."
  4. LITERAL STYLE INJECTION: Ensure the visual style (${settings.visualStyle}) and movement (${settings.cameraMovement}) are explicitly described.
  5. MOTION ENFORCER: Ensure specific movement is described (Parallax, Grain, etc.).
  6. ${characterProtocol}

  ORIGINAL SCRIPT LINE: "${originalClip.scriptLine}" (Do not change this)

  CURRENT STYLE SETTINGS:
  - Visual: ${settings.visualStyle}
  - Mood: ${settings.mood}
  - Movement: ${settings.cameraMovement}

  USER MODIFICATION REQUEST: "${instruction}"

  PROMPT FORMULA:
  [SAFETY TAG] + [Visual Style] + [Subject Action w/ Mods] + [Camera Move connected to subject] + [Lighting sentence] + [Texture/Color sentence] + [Specific Motion].
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Regenerate Clip #${originalClip.clipNumber} with feedback: ${instruction}`,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            scriptLine: { type: Type.STRING },
            narrativeContext: { type: Type.STRING },
            visualPrompt: { type: Type.STRING }
          },
          required: ["scriptLine", "narrativeContext", "visualPrompt"]
        }
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) throw new Error("Empty response from AI");

    const data = JSON.parse(jsonStr);

    const updatedJson = originalClip.jsonOutput ? {
      ...originalClip.jsonOutput,
      visual_prompt: data.visualPrompt,
      // Update meta if script line changed (unlikely for regen but possible if instructed)
      meta_data_DO_NOT_RENDER: {
        ...originalClip.jsonOutput.meta_data_DO_NOT_RENDER,
        script_source: data.scriptLine
      }
    } : undefined;

    return {
      ...originalClip, // Keep original ID and clipNumber
      scriptLine: data.scriptLine, 
      narrativeContext: data.narrativeContext,
      visualPrompt: data.visualPrompt,
      jsonOutput: updatedJson
    };

  } catch (error) {
    console.error(`Error regenerating clip ${originalClip.clipNumber}:`, error);
    throw error;
  }
};

