            {/* The Prompt */}
            <div className="bg-[#0e1117] rounded-lg border border-gray-800 p-4 relative group">
              <div className="flex items-center gap-2 mb-2 text-purple-400 text-xs font-semibold uppercase tracking-wider">
                <Camera size={14} /> AI Video Prompt
              </div>
              <p className="text-sm text-gray-200 font-mono leading-relaxed pb-6">
                {clip.visualPrompt}
              </p>

              <button
                onClick={handleCopy}
                className="absolute bottom-2 right-2 p-2 rounded-md bg-gray-800 hover:bg-blue-600 text-gray-400 hover:text-white transition-all border border-gray-700 hover:border-blue-500"
                title="Copy Prompt"
              >
                {copied ? <Check size={16} /> : <Copy size={16} />}
              </button>
            </div>
          </>
        )}

      </div>
    </div>
  );
