                       className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-sm font-bold transition-colors ${
                         settings.isConsistencyEnabled 
                         ? 'bg-purple-900/50 text-purple-200 border border-purple-500' 
                         : 'bg-gray-800 text-gray-400 border border-gray-700'
                       }`}
                     >
                        {settings.isConsistencyEnabled ? <ToggleRight size={24} className="text-purple-400" /> : <ToggleLeft size={24} />}
                        {settings.isConsistencyEnabled ? "Consistency Engine ENABLED" : "Consistency Engine DISABLED"}
                     </button>
                   </div>
                   <p className="text-xs text-gray-500">
                     {settings.isConsistencyEnabled 
                       ? "The AI will strictly enforce the descriptions below when these characters appear in the script."
                       : "Character descriptions will be ignored. The AI will generate generic visuals based on the script only."}
                   </p>
                </div>

                <div className="flex gap-2">
                   <button 
                     onClick={handleScriptAnalysis}
                     disabled={disabled || analyzingScript || !script}
                     className="px-4 py-2 bg-blue-900/30 hover:bg-blue-800 border border-blue-600 text-blue-200 text-sm font-bold rounded-lg flex items-center gap-2 transition-all disabled:opacity-50"
                     title="AI will read your script and identify the main cast for you."
                   >
                     {analyzingScript ? <Loader className="animate-spin" size={16} /> : <Search size={16} />}
                     Auto-Detect Cast from Script
                   </button>

                   <button onClick={addCharacter} disabled={disabled} className="px-4 py-2 bg-purple-600 hover:bg-purple-500 text-white text-sm font-bold rounded-lg flex items-center gap-2 shadow-lg shadow-purple-900/40 transition-all">
                     <UserPlus size={16} /> Add Character
                   </button>
