import { GoogleGenAI, Type } from "@google/genai";
import { StyleSettings, GeneratedClip, ClipDuration, OutputFormat, Character } from "../types";
import { 
  VISUAL_STYLES, 
  LIGHTING_OPTIONS, 
  MOOD_OPTIONS, 
  CAMERA_STYLES, 
  CAMERA_MOVEMENTS 
} from '../constants';

const getAIClient = () => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

// Helper: Split script into chunks based on specific user formula
// Formula: Script Word Count / 200 = Video Duration (minutes)
// Therefore: 200 words per 60 seconds.
const splitScriptToChunks = (script: string, clipDuration: ClipDuration): string[] => {
  // Calculate words per clip based on the 200 words/min formula
  // For 8s: (200 / 60) * 8 = 26.666 => ~27 words.
  const wordsPerSecond = 200 / 60;
  const targetWordsPerChunk = Math.round(wordsPerSecond * clipDuration);

  // Split by sentence endings to preserve narrative flow where possible, 
  // but strictly adhere to length limits close to the target.
  const sentenceRegex = /[^.!?]+[.!?]+["']?|[^.!?]+$/g;
  const sentences = script.match(sentenceRegex) || [script];

  const chunks: string[] = [];
  let currentChunk = "";
  let currentWordCount = 0;

  for (const sentence of sentences) {
    const sentenceWordCount = sentence.trim().split(/\s+/).length;

    // If adding this sentence exceeds the target significantly (allow +10% buffer), push current chunk
    if (currentWordCount + sentenceWordCount > targetWordsPerChunk * 1.1 && currentChunk.length > 0) {
      chunks.push(currentChunk.trim());
      currentChunk = sentence;
      currentWordCount = sentenceWordCount;
    } else {
      currentChunk += " " + sentence;
      currentWordCount += sentenceWordCount;
    }
  }

  if (currentChunk.trim().length > 0) {
    chunks.push(currentChunk.trim());
  }

  return chunks;
};

// Analyze video reference to extract style
const analyzeVideoStyle = async (videoBase64: string, mimeType: string): Promise<Partial<StyleSettings>> => {
  const ai = getAIClient();

  const systemInstruction = `You are a Senior Colorist and Director of Photography. 
  Analyze the provided video clip to extract its exact stylistic attributes.

  You must map your analysis to the following available presets where possible:
  - Visual Styles: ${VISUAL_STYLES.join(", ")}
  - Lighting: ${LIGHTING_OPTIONS.join(", ")}
  - Mood: ${MOOD_OPTIONS.join(", ")}
  - Camera Style: ${CAMERA_STYLES.join(", ")}
  - Camera Movement: ${CAMERA_MOVEMENTS.join(", ")}

  For 'artKeywords', provide a comma-separated list of highly specific technical terms observed in the video (e.g., "anamorphic lens flare, teal and orange grading, volumetric fog, 8mm grain").
  For 'colorPalette', extract the 3 dominant hex codes.
  `;

  const prompt = "Analyze this video and return the style settings that best match the visual input.";

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview", // upgraded model for better vision analysis
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType, data: videoBase64 } },
          { text: prompt }
        ]
      },
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            visualStyle: { type: Type.STRING, enum: VISUAL_STYLES },
            colorPalette: {
              type: Type.OBJECT,
              properties: {
                primary: { type: Type.STRING, description: "Hex code" },
                secondary: { type: Type.STRING, description: "Hex code" },
                accent: { type: Type.STRING, description: "Hex code" }
              }
            },
            mood: { type: Type.STRING, enum: MOOD_OPTIONS },
            lighting: { type: Type.STRING, enum: LIGHTING_OPTIONS },
            cameraStyle: { type: Type.STRING, enum: CAMERA_STYLES },
            cameraMovement: { type: Type.STRING, enum: CAMERA_MOVEMENTS },
            artKeywords: { type: Type.STRING, description: "Comma separated technical keywords" }
          },
          required: ["visualStyle", "colorPalette", "mood", "lighting", "cameraStyle", "cameraMovement", "artKeywords"]
        }
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) throw new Error("No analysis result");
    return JSON.parse(jsonStr);

  } catch (error) {
    console.error("Video Analysis Error:", error);
    throw error;
  }
};

// Analyze character image to generate text description
const analyzeCharacterImage = async (imageBase64: string, mimeType: string): Promise<string> => {
  const ai = getAIClient();

  const systemInstruction = `You are a Character Designer for Film.
  Analyze this character image. Write a precise, 40-word physical description suitable for a video generation prompt.
  Focus STRICTLY on: Age, Gender, Ethnicity, Hairstyle/Color, Clothing (Style/Color), and Distinctive Facial Features.
  Do not describe the background, lighting, or pose. Output only the description string.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType, data: imageBase64 } },
          { text: "Describe this character's physical appearance for a prompt." }
        ]
      },
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "text/plain",
      }
    });

    return response.text || "Could not analyze character.";
  } catch (error) {
    console.error("Character Analysis Error:", error);
    throw new Error("Failed to analyze character image.");
  }
};

// Analyze Script to Extract Characters
const analyzeScriptForCharacters = async (script: string): Promise<Character[]> => {
  const ai = getAIClient();

  const systemInstruction = `You are a Casting Director and Costume Designer.
  Analyze the provided movie script text. 
  Identify the RECURRING characters who appear multiple times.

  For each character, generate a "Fixed Visual Anchor" description.
  RULES FOR DESCRIPTION:
  1. Infer details from the context (e.g., if script says "Detective", implies suit/trench coat. If "Medieval", implies tunic/armor).
  2. If the character implies a specific age (e.g. "Grandma"), specify it ("Elderly woman, 70s").
  3. Specify precise attire, hair, and key features.
  4. Keep it under 40 words per character.

  OUTPUT: A JSON list of characters.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyze this script and identify the main cast:\n\n${script.substring(0, 15000)}`, // Limit context if needed
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING },
              frequency: { type: Type.STRING, enum: ["Main Protagonist", "Supporting", "Occasional"] }
            },
            required: ["name", "description", "frequency"]
          }
        }
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) return [];

    const rawList = JSON.parse(jsonStr);

    // Map to Character interface
    return rawList.map((c: any) => ({
      id: crypto.randomUUID(),
      name: c.name,
      description: c.description,
      frequency: c.frequency,
      isFaceLocked: false,
      visualStyle: "",
      lighting: "",
      mood: "",
      cameraStyle: "",
      cameraMovement: "",
      colorPalette: { primary: "", secondary: "", accent: "" }
    }));

  } catch (error) {
    console.error("Script Character Analysis Error:", error);
    throw new Error("Failed to analyze script for characters.");
  }
};

const generateSingleClip = async (
  chunkText: string,
  clipNumber: number,
  settings: StyleSettings,
  clipDuration: ClipDuration,
  outputFormat: OutputFormat
): Promise<GeneratedClip> => {
  const ai = getAIClient();

  // Construct Character Bible text ONLY if enabled and characters exist
  const characterProtocol = (settings.isConsistencyEnabled && settings.characters.length > 0)
    ? `
    >>> CHARACTER CONSISTENCY PROTOCOL (ACTIVE) <<<
    You must scan the script for the following characters. If found, you MUST use their "Fixed Visual Anchor" description instead of generic terms.

    ${settings.characters.map(c => 
      `NAME: "${c.name}"
       VISUAL ANCHOR: "${c.description}"
       FACE LOCK: ${c.isFaceLocked ? "ON (Must append: 'Consistent facial features, identical character model')" : "OFF"}
       STYLE OVERRIDE: ${c.visualStyle || 'Default'}, ${c.mood || 'Default'}, ${c.lighting || 'Default'}`
    ).join('\n\n')}

    RULES:
    1. If script says "${settings.characters[0]?.name || 'Name'} walks", prompt must say "${settings.characters[0]?.description || 'Description'} walks...".
    2. Do NOT use pronouns like "She" or "He" at the start of the prompt. Always use the full visual anchor.
    3. If Face Lock is ON, ensure the prompt ends with the consistency phrase.
    4. If a character with a STYLE OVERRIDE appears, subtly blend their specific style preferences (e.g. lighting/mood) into the visual prompt for that specific clip.
    `
    : "Character Consistency is DISABLED. Use generic descriptions based on the script only.";

  // Calculate Timing Context
  const startTime = (clipNumber - 1) * clipDuration;
  const endTime = clipNumber * clipDuration;
  const timingContext = `Timing: Start ${startTime}s, End ${endTime}s, Duration ${clipDuration}s`;

  // --- STANDARD MODE SCHEMA ---
  const standardSchema = {
    type: Type.OBJECT,
    properties: {
      scriptLine: { type: Type.STRING, description: "The exact script text provided." },
      narrativeContext: { type: Type.STRING, description: "40-80 words explaining the action and story beat." },
      visualPrompt: { type: Type.STRING, description: "MAXIMUM 100 WORDS. High density, precision only." }
    },
    required: ["scriptLine", "narrativeContext", "visualPrompt"]
  };

  // --- NEW "SAFE" JSON TEMPLATE (Prompt First to Prevent Text Bleed) ---
  const detailedJsonSchema = {
    type: Type.OBJECT,
    properties: {
      visual_prompt: { type: Type.STRING, description: "The prompt MUST be the first key. MAX 100 WORDS." },
      meta_data_DO_NOT_RENDER: {
        type: Type.OBJECT,
        properties: {
          scene_id: { type: Type.INTEGER },
          duration: { type: Type.STRING },
          script_source: { type: Type.STRING }
        }
      },
      technical_settings: {
          type: Type.OBJECT,
          properties: {
              camera: {
                  type: Type.OBJECT,
                  properties: {
                      type: { type: Type.STRING },
                      action: { type: Type.STRING }
                  }
              },
              lighting: {
                  type: Type.OBJECT,
                  properties: {
                      setup: { type: Type.STRING },
                      palette: { type: Type.STRING }
                  }
              }
          }
      },
      audio_instruction: {
          type: Type.OBJECT,
          properties: {
              music: { type: Type.STRING },
              sfx: { type: Type.STRING }
          }
      },
      safety_rules: {
          type: Type.OBJECT,
          properties: {
              negative_prompt: { type: Type.STRING }
          }
      }
    },
    required: ["visual_prompt", "meta_data_DO_NOT_RENDER", "technical_settings", "audio_instruction", "safety_rules"]
  };

  const isJsonMode = outputFormat === 'json';

  const systemInstruction = `You are an elite Video Prompt Engineer for Google Veo 3.1.

  MODE: ${isJsonMode ? "SAFE PRODUCTION JSON" : "STANDARD NARRATIVE"}

  >>> LENGTH CONSTRAINT (CRITICAL): MAXIMUM 100 WORDS <<<
  Every video prompt MUST be under 100 words.
  - Do not be verbose. Be dense and precise.
  - Remove filler words. Focus on subject, action, style, and motion.
  - High quality does not mean long length. It means specific vocabulary.

  >>> STYLE CHAMELEON LOGIC (DYNAMIC AESTHETIC MAPPING) <<<
  Analyze the User's "Visual Aesthetic" setting (${settings.visualStyle}) and apply the matching rule set:

  RULESET A: REALISM / PAINTING / MATTE (Triggers: "Realism", "Oil", "Matte", "Cinematic", "Vintage", "Documentary")
  - Action: Apply "High-Texture" rules.
  - Keywords to Inject: "Cinematic historical realism, thick oil textures, volumetric smoke, hazy atmospheric depth, 8k masterpiece."
  - Forbidden: "Cartoon", "Vector", "Low poly".

  RULESET B: CARTOON / 3D / ANIME (Triggers: "Cartoon", "Anime", "3D", "Flat", "Disney", "Pixar", "Low Poly")
  - Action: Apply "Clean-Line" rules.
  - Keywords to Inject: "Vibrant cel-shaded colors, clean vector lines, expressive character animation, soft global illumination, high-quality 3D render."
  - Forbidden: "Photorealistic", "Grain", "Noise".

  RULESET C: ILLUSTRATIVE / SKETCH (Triggers: "Illustrative", "Sketch", "Drawing", "Pencil", "Ink")
  - Action: Apply "Hand-Drawn" rules.
  - Keywords to Inject: "Hand-drawn aesthetic, visible graphite/ink strokes, textured paper background, fluid artistic motion."

  >>> UNIVERSAL SAFETY RULE (ALWAYS ACTIVE) <<<
  Regardless of the style, EVERY prompt must start with: "Clean video, no text. No typography."

  >>> COLOR TRANSLATION RULE (CRITICAL) <<<
  You must translate the provided Hex Codes from settings (${settings.colorPalette.primary}, ${settings.colorPalette.secondary}) into artistic natural language descriptions.
  - Example: #524B40 -> "deep taupe and dark earth"
  - Example: #FF0000 -> "vibrant crimson"
  - STRICT RULE: Never output the actual #Hex string in the final 'visual_prompt'. Only use the descriptive words to prevent text artifacts.

  >>> CORE DIRECTIVE: NATURAL LANGUAGE WEAVING <<<
  You are NOT a list dumper. You are a PROFESSIONAL ART DIRECTOR.
  You must weave the provided Global Style Context into a cohesive direction paragraph.

  GLOBAL STYLE CONTEXT (USER SETTINGS):
  - VISUAL AESTHETIC: "${settings.visualStyle}"
  - LIGHTING: "${settings.lighting}"
  - CAMERA: "${settings.cameraStyle}"
  - MOVEMENT: "${settings.cameraMovement}"
  - PALETTE: Primary ${settings.colorPalette.primary}, Secondary ${settings.colorPalette.secondary}
  - KEYWORDS: ${settings.artKeywords}

  ${isJsonMode ? `
  >>> JSON STRUCTURE RULE: PROMPT FIRST <<<
  To prevent the video model from rendering text on screen, the 'visual_prompt' MUST be the very first key in the JSON output.

  MAPPING RULES:
  1. visual_prompt: Construct using the "Weaving" formula below.
  2. meta_data_DO_NOT_RENDER.scene_id: ${clipNumber}
  3. meta_data_DO_NOT_RENDER.duration: "${clipDuration}s"
  4. meta_data_DO_NOT_RENDER.script_source: "${chunkText}"
  5. technical_settings.camera.type: "${settings.cameraStyle}"
  6. technical_settings.camera.action: "${settings.cameraMovement}"
  7. technical_settings.lighting.setup: "${settings.lighting}"
  8. technical_settings.lighting.palette: "${settings.colorPalette.primary}, ${settings.colorPalette.secondary}"
  ` : ''}

  >>> PROMPT CONSTRUCTION FORMULA (MANDATORY) <<<
  The 'visual_prompt' (or 'visualPrompt') MUST be constructed using this "Weaving" structure:

  1. [SAFETY TAG]: Start with "Clean video, no text. No typography."
  2. [SCENE & STYLE]: "A [Visual Aesthetic: ${settings.visualStyle}] depicting [Subject & Action]..."
  3. [LIGHTING]: "The lighting is ${settings.lighting}, casting [specific shadow/highlight effects]."
  4. [CAMERA WEAVING]: "The camera performs a ${settings.cameraMovement}, revealing [Environment Detail]..." (Connect move to subject).
  5. [TEXTURE & COLOR WEAVING]: "The image features ${settings.artKeywords}. The color palette is defined by [Translated Natural Language Description of ${settings.colorPalette.primary}] and [Translated Description of ${settings.colorPalette.secondary}] tones."
  6. [MOTION ENFORCER]:
     - IF style is "2.5D/Matte": Describe "parallax layer separation, drifting atmosphere, independent element movement".
     - IF style is "Vintage": Describe "film grain motion, projector jitter".
     - IF style is "Anime": Describe "limited frame rate, wind in hair".
     - GENERAL: Ensure the scene is ALIVE and matches the requested movement "${settings.cameraMovement}".

  STRICT RULES:
  1. JSON STRUCTURE: Output valid JSON exactly matching the schema.
  2. SCRIPT SYNC: Use the provided script line exactly.
  3. WORD COUNT: ABSOLUTE MAX 100 WORDS.
  4. NO GENERIC TERMS: Do not say "Good lighting". Say "${settings.lighting}".
  ${isJsonMode ? '5. SAFETY: `safety_rules.negative_prompt` MUST include: "text, typography, subtitles, watermarks".' : ''}

  ${characterProtocol}

  CONTEXT: ${timingContext}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: `Generate Prompt for Clip #${clipNumber}. Script Segment: "${chunkText}"`,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: isJsonMode ? detailedJsonSchema : standardSchema
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) throw new Error("Empty response from AI");

    const data = JSON.parse(jsonStr);

    if (isJsonMode) {
      return {
        id: crypto.randomUUID(),
        clipNumber: clipNumber,
        scriptLine: data.meta_data_DO_NOT_RENDER?.script_source || chunkText,
        narrativeContext: "", // Not explicitly in "Safe" schema, leaving blank or inferred
        visualPrompt: data.visual_prompt || "",
        jsonOutput: data
      };
    } else {
      return {
        id: crypto.randomUUID(),
        clipNumber: clipNumber,
        scriptLine: data.scriptLine,
        narrativeContext: data.narrativeContext,
        visualPrompt: data.visualPrompt
      };
    }

  } catch (error) {
    console.error(`Error generating clip ${clipNumber}:`, error);
    throw error;
  }
};

const regenerateClip = async (
  originalClip: GeneratedClip,
  settings: StyleSettings,
  instruction: string,
  outputFormat: OutputFormat
): Promise<GeneratedClip> => {
  const ai = getAIClient();

  const characterProtocol = (settings.isConsistencyEnabled && settings.characters.length > 0)
    ? `MAINTAIN CHARACTER CONSISTENCY for: ${settings.characters.map(c => c.name).join(', ')}.`
    : "";

  const systemInstruction = `You are an elite Video Prompt Engineer (Veo 3.1).
  Your task is to REGENERATE and REFINE a video prompt based on user feedback.

  STRICT RULES:
  1. LENGTH: MAX 100 WORDS. High Density.
  2. START with "Clean video, no text. No typography."
  3. STYLE CHAMELEON: 
     - IF style implies Realism/Oil: Inject "8k masterpiece, thick oil textures, volumetric smoke".
     - IF style implies Cartoon/3D: Inject "vibrant cel-shaded colors, clean lines, high-quality 3D render".
     - IF style implies Sketch: Inject "hand-drawn aesthetic, graphite strokes, textured paper".
  4. NATURAL LANGUAGE WEAVING: Do not dump keywords. Weave them into sentences.
     - "The image features [Keywords]..."
     - "The camera performs a ${settings.cameraMovement}, revealing..."
  5. COLOR TRANSLATION RULE:
     - You must translate Hex Codes (${settings.colorPalette.primary}, ${settings.colorPalette.secondary}) into descriptive adjectives (e.g. "burnt ochre" instead of "#C2B287").
     - NEVER use hex codes in the prompt string.
  6. LITERAL STYLE INJECTION: Ensure the visual style (${settings.visualStyle}) and movement (${settings.cameraMovement}) are explicitly described.
  7. MOTION ENFORCER: Ensure specific movement is described (Parallax, Grain, etc.).
  8. ${characterProtocol}

  ORIGINAL SCRIPT LINE: "${originalClip.scriptLine}" (Do not change this)

  CURRENT STYLE SETTINGS:
  - Visual: ${settings.visualStyle}
  - Mood: ${settings.mood}
  - Movement: ${settings.cameraMovement}

  USER MODIFICATION REQUEST: "${instruction}"

  PROMPT FORMULA:
  [SAFETY TAG] + [Visual Style] + [Subject Action w/ Mods] + [Camera Move connected to subject] + [Lighting sentence] + [Translated Color/Texture sentence] + [Specific Motion].
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Regenerate Clip #${originalClip.clipNumber} with feedback: ${instruction}`,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            scriptLine: { type: Type.STRING },
            narrativeContext: { type: Type.STRING },
            visualPrompt: { type: Type.STRING }
          },
          required: ["scriptLine", "narrativeContext", "visualPrompt"]
        }
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) throw new Error("Empty response from AI");

    const data = JSON.parse(jsonStr);

    const updatedJson = originalClip.jsonOutput ? {
      ...originalClip.jsonOutput,
      visual_prompt: data.visualPrompt,
      // Update meta if script line changed (unlikely for regen but possible if instructed)
      meta_data_DO_NOT_RENDER: {
        ...originalClip.jsonOutput.meta_data_DO_NOT_RENDER,
        script_source: data.scriptLine
      }
    } : undefined;

    return {
      ...originalClip, // Keep original ID and clipNumber
      scriptLine: data.scriptLine, 
      narrativeContext: data.narrativeContext,
      visualPrompt: data.visualPrompt,
      jsonOutput: updatedJson
    };

  } catch (error) {
    console.error(`Error regenerating clip ${originalClip.clipNumber}:`, error);
    throw error;
  }
};

