export const CharacterEngine: React.FC<CharacterEngineProps> = ({ settings, setSettings, disabled, script, onAnalysisComplete, analysisInProgress }) => {
  const [analyzingCharId, setAnalyzingCharId] = useState<string | null>(null);
  const [charError, setCharError] = useState<{id: string, msg: string} | null>(null);

  const addCharacter = () => {
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: "New Character",
      role: "Supporting",
      description: "Describe visual appearance here...",
      shortDescription: "",
      frequency: "Main Protagonist",
      isFaceLocked: true,
      visualStyle: settings.visualStyle,
      lighting: settings.lighting,
      mood: settings.mood,
      cameraStyle: settings.cameraStyle,
      cameraMovement: settings.cameraMovement,
      colorPalette: { ...settings.colorPalette }
    };
    setSettings(prev => ({ ...prev, characters: [...prev.characters, newChar] }));
  };

  const updateCharacter = (id: string, updates: Partial<Character>) => {
    setSettings(prev => ({
      ...prev,
      characters: prev.characters.map(c => c.id === id ? { ...c, ...updates } : c)
    }));
  };

  const removeCharacter = (id: string) => {
    setSettings(prev => ({
      ...prev,
      characters: prev.characters.filter(c => c.id !== id)
    }));
  };

  const handleScriptAnalysis = async () => {
    if (!script || !script.trim()) {
      alert("Please enter a script in the main input box first.");
      return;
    }

    // Parent component handles the state 'analysisInProgress'
    if (onAnalysisComplete) {
       // We'll call the service here but the loading state comes from props for sync
       // Actually, we can just trigger the parent's handler
       onAnalysisComplete(); 
       return;
    }
  };

  const handleCharacterImageUpload = async (charId: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setAnalyzingCharId(charId);
    setCharError(null);

    const reader = new FileReader();
    reader.onloadend = async () => {
      try {
        const result = reader.result;
        if (!result) throw new Error("Failed to read file.");
        const base64String = result.toString().split(',')[1];

        const description = await geminiService.analyzeCharacterImage(base64String, file.type);
        updateCharacter(charId, { description });
      } catch (err) {
        setCharError({ id: charId, msg: "Could not analyze character. Please enter description manually." });
      } finally {
        setAnalyzingCharId(null);
        e.target.value = '';
      }
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="bg-[#1e293b] border border-gray-700 rounded-xl p-4 space-y-4">
      {/* Header & Toggle */}
      <div className="flex flex-col gap-3 pb-3 border-b border-gray-700">
        <div className="flex items-center justify-between">
           <h3 className="text-sm font-bold text-purple-400 flex items-center gap-2">
             <Users size={16} /> CAST & CONSISTENCY
           </h3>
           <div className="text-xs font-mono text-gray-500">{settings.characters.length} Active</div>
        </div>

        <button 
           onClick={() => setSettings(prev => ({ ...prev, isConsistencyEnabled: !prev.isConsistencyEnabled }))}
           className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-xs font-bold transition-all border ${
             settings.isConsistencyEnabled 
             ? 'bg-purple-900/30 text-purple-200 border-purple-500' 
             : 'bg-gray-800 text-gray-400 border-gray-700'
           }`}
         >
            <span className="flex items-center gap-2">
               {settings.isConsistencyEnabled ? "Consistency ENABLED" : "Consistency DISABLED"}
            </span>
            {settings.isConsistencyEnabled ? <ToggleRight size={20} className="text-purple-400" /> : <ToggleLeft size={20} />}
         </button>
      </div>

      {/* Action Buttons */}
      <div className="flex gap-2">
         {/* This button is now purely for manual overrides or re-analysis, 
             the main flow is controlled by the parent 'Generate' logic 
             but we keep it here for convenience. */}
         <button 
           onClick={onAnalysisComplete}
           disabled={disabled || analysisInProgress || !script}
           className="flex-1 px-3 py-2 bg-blue-900/20 hover:bg-blue-800/40 border border-blue-600/50 text-blue-200 text-xs font-bold rounded-lg flex items-center justify-center gap-2 transition-all disabled:opacity-50"
           title="AI will read your script and identify the main cast."
         >
           {analysisInProgress ? <Loader className="animate-spin" size={14} /> : <Search size={14} />}
           Re-Analyze Cast
         </button>

         <button onClick={addCharacter} disabled={disabled} className="px-3 py-2 bg-purple-600 hover:bg-purple-500 text-white text-xs font-bold rounded-lg flex items-center gap-1 shadow-lg shadow-purple-900/40 transition-all">
           <UserPlus size={14} />
         </button>
      </div>

      {settings.isConsistencyEnabled && settings.characters.length === 0 && (
         <div className="text-center py-4 bg-yellow-900/20 border border-yellow-700/50 rounded-lg p-3">
             <AlertTriangle size={16} className="mx-auto text-yellow-500 mb-2" />
             <p className="text-xs text-yellow-200 font-bold">Action Required</p>
             <p className="text-[10px] text-yellow-400/80 mt-1">
                 You must Analyze Cast before generating prompts.
             </p>
         </div>
      )}

      {/* Character List */}
      <div className="space-y-3 max-h-[600px] overflow-y-auto pr-1">
         {settings.characters.map(char => (
           <CharacterCard
             key={char.id}
             character={char}
             updateCharacter={updateCharacter}
             removeCharacter={removeCharacter}
             onImageUpload={handleCharacterImageUpload}
             analyzingCharId={analyzingCharId}
             charError={charError}
             disabled={disabled}
             consistencyEnabled={settings.isConsistencyEnabled}
           />
         ))}
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { StyleSettings, GeneratedClip, ClipDuration, OutputFormat, Character } from "../types";
import { 
  VISUAL_STYLES, 
  LIGHTING_OPTIONS, 
  MOOD_OPTIONS, 
  CAMERA_STYLES, 
  CAMERA_MOVEMENTS 
} from '../constants';

const getAIClient = () => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

// Helper: Split script into chunks based on specific user formula
// Formula: Script Word Count / 200 = Video Duration (minutes)
// Therefore: 200 words per 60 seconds.
const splitScriptToChunks = (script: string, clipDuration: ClipDuration): string[] => {
  // Calculate words per clip based on the 200 words/min formula
  // For 8s: (200 / 60) * 8 = 26.666 => ~27 words.
  const wordsPerSecond = 200 / 60;
  const targetWordsPerChunk = Math.round(wordsPerSecond * clipDuration);

  // Split by sentence endings to preserve narrative flow where possible, 
  // but strictly adhere to length limits close to the target.
  const sentenceRegex = /[^.!?]+[.!?]+["']?|[^.!?]+$/g;
  const sentences = script.match(sentenceRegex) || [script];

  const chunks: string[] = [];
  let currentChunk = "";
  let currentWordCount = 0;

  for (const sentence of sentences) {
    const sentenceWordCount = sentence.trim().split(/\s+/).length;

    // If adding this sentence exceeds the target significantly (allow +10% buffer), push current chunk
    if (currentWordCount + sentenceWordCount > targetWordsPerChunk * 1.1 && currentChunk.length > 0) {
      chunks.push(currentChunk.trim());
      currentChunk = sentence;
      currentWordCount = sentenceWordCount;
    } else {
      currentChunk += " " + sentence;
      currentWordCount += sentenceWordCount;
    }
  }

  if (currentChunk.trim().length > 0) {
    chunks.push(currentChunk.trim());
  }

  return chunks;
};

// Analyze video reference to extract style
const analyzeVideoStyle = async (videoBase64: string, mimeType: string): Promise<Partial<StyleSettings>> => {
  const ai = getAIClient();

  const systemInstruction = `You are a Senior Colorist and Director of Photography. 
  Analyze the provided video clip to extract its exact stylistic attributes.

  You must map your analysis to the following available presets where possible:
  - Visual Styles: ${VISUAL_STYLES.join(", ")}
  - Lighting: ${LIGHTING_OPTIONS.join(", ")}
  - Mood: ${MOOD_OPTIONS.join(", ")}
  - Camera Style: ${CAMERA_STYLES.join(", ")}
  - Camera Movement: ${CAMERA_MOVEMENTS.join(", ")}

  For 'artKeywords', provide a comma-separated list of highly specific technical terms observed in the video (e.g., "anamorphic lens flare, teal and orange grading, volumetric fog, 8mm grain").
  For 'colorPalette', extract the 3 dominant hex codes.
  `;

  const prompt = "Analyze this video and return the style settings that best match the visual input.";

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview", // upgraded model for better vision analysis
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType, data: videoBase64 } },
          { text: prompt }
        ]
      },
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            visualStyle: { type: Type.STRING, enum: VISUAL_STYLES },
            colorPalette: {
              type: Type.OBJECT,
              properties: {
                primary: { type: Type.STRING, description: "Hex code" },
                secondary: { type: Type.STRING, description: "Hex code" },
                accent: { type: Type.STRING, description: "Hex code" }
              }
            },
            mood: { type: Type.STRING, enum: MOOD_OPTIONS },
            lighting: { type: Type.STRING, enum: LIGHTING_OPTIONS },
            cameraStyle: { type: Type.STRING, enum: CAMERA_STYLES },
            cameraMovement: { type: Type.STRING, enum: CAMERA_MOVEMENTS },
            artKeywords: { type: Type.STRING, description: "Comma separated technical keywords" }
          },
          required: ["visualStyle", "colorPalette", "mood", "lighting", "cameraStyle", "cameraMovement", "artKeywords"]
        }
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) throw new Error("No analysis result");
    return JSON.parse(jsonStr);

  } catch (error) {
    console.error("Video Analysis Error:", error);
    throw error;
  }
};

// Analyze character image to generate text description
const analyzeCharacterImage = async (imageBase64: string, mimeType: string): Promise<string> => {
  const ai = getAIClient();

  const systemInstruction = `You are a Character Designer for Film.
  Analyze this character image. Write a precise, 40-word physical description suitable for a video generation prompt.
  Focus STRICTLY on: Age, Gender, Ethnicity, Hairstyle/Color, Clothing (Style/Color), and Distinctive Facial Features.
  Do not describe the background, lighting, or pose. Output only the description string.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType, data: imageBase64 } },
          { text: "Describe this character's physical appearance for a prompt." }
        ]
      },
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "text/plain",
      }
    });

    return response.text || "Could not analyze character.";
  } catch (error) {
    console.error("Character Analysis Error:", error);
    throw new Error("Failed to analyze character image.");
  }
};

// Analyze Script to Extract Characters
const analyzeScriptForCharacters = async (script: string): Promise<Character[]> => {
  const ai = getAIClient();

  const systemInstruction = `You are a Casting Director and Costume Designer.
  Analyze the provided movie script text. 
  Identify the RECURRING characters who appear multiple times.

  For each character, create a DETAILED PROFILE:

  1. NAME: Character Name.
  2. ROLE: E.g., "Protagonist", "Villain", "Mentor", "Comic Relief".
  3. FREQUENCY: "Main Protagonist", "Supporting", or "Occasional".
  4. FULL DESCRIPTION (Visual Anchor):
     - Age, Build, Face, Hair, Distinctive Features.
     - Period-accurate attire (Clothing, Armor, Colors, Condition).
     - Must be precise and visual (e.g. "Tall, 30s, scar on left cheek, wearing worn leather aviator jacket").
  5. SHORT IDENTIFIER:
     - A concise version for subsequent mentions. 
     - Format: "Name (Key Feature 1, Key Feature 2)".
     - Example: "Wallace (dark hair, leather armor)".

  OUTPUT: A JSON list of characters.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyze this script and identify the main cast:\n\n${script.substring(0, 20000)}`,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              role: { type: Type.STRING },
              description: { type: Type.STRING, description: "Full visual anchor (40 words)" },
              shortDescription: { type: Type.STRING, description: "Name + key visual tags" },
              frequency: { type: Type.STRING, enum: ["Main Protagonist", "Supporting", "Occasional"] }
            },
            required: ["name", "role", "description", "shortDescription", "frequency"]
          }
        }
      }
    });

    const jsonStr = response.text;
    if (!jsonStr) return [];

    const rawList = JSON.parse(jsonStr);

    // Map to Character interface
    return rawList.map((c: any) => ({
      id: crypto.randomUUID(),
      name: c.name,
      role: c.role || "Character",
      description: c.description,
      shortDescription: c.shortDescription || `${c.name} (${c.description.substring(0, 15)}...)`,
      frequency: c.frequency,
      isFaceLocked: true, // Default to locked as per user request
      visualStyle: "",
      lighting: "",
      mood: "",
      cameraStyle: "",
      cameraMovement: "",
      colorPalette: { primary: "", secondary: "", accent: "" }
    }));

  } catch (error) {
    console.error("Script Character Analysis Error:", error);
    throw new Error("Failed to analyze script for characters.");
  }
};

const generateSingleClip = async (
  chunkText: string,
  clipNumber: number,
  settings: StyleSettings,
  clipDuration: ClipDuration,
  outputFormat: OutputFormat
): Promise<GeneratedClip> => {
  const ai = getAIClient();

  // Construct Character Bible text ONLY if enabled and characters exist
  const characterProtocol = (settings.isConsistencyEnabled && settings.characters.length > 0)
    ? `
    >>> CHARACTER CONSISTENCY PROTOCOL (LOCKED) <<<
    The following characters are APPROVED and LOCKED. You MUST use their descriptions.

    ${settings.characters.map(c => 
      `CHARACTER: "${c.name}"
       ROLE: ${c.role}
       FULL VISUAL ANCHOR: "${c.description}"
       SHORT IDENTIFIER: "${c.shortDescription}"
       FACE LOCK: ${c.isFaceLocked ? "ON (Must preserve distinctive features)" : "OFF"}
       STYLE OVERRIDE: ${c.visualStyle || 'None'}`
    ).join('\n\n')}

    INSTRUCTION FOR INSERTION:
    1. **Scan the Script Segment** to see which characters are present.
    2. **First Mention in this Clip**: Use the FULL VISUAL ANCHOR. The audience must instantly recognize the attire and features.
    3. **Subsequent Mentions**: You may use the SHORT IDENTIFIER to save word count, provided the character is already visually established in the scene.
    4. **Groups/Background**: If specific characters are not named, ensure background extras match the period/style of the main cast.
    5. **Substitution**: NEVER use just the Name (e.g. "John"). ALWAYS substitute with the visual description (e.g. "John, a rugged man in 40s wearing...") or Short Identifier.
    `
    : "Character Consistency is DISABLED. Use generic descriptions based on the script only.";

  // Calculate Timing Context
  const startTime = (clipNumber - 1) * clipDuration;
  const endTime = clipNumber * clipDuration;
  const timingContext = `Timing: Start ${startTime}s, End ${endTime}s, Duration ${clipDuration}s`;

  // --- STANDARD MODE SCHEMA ---
  const standardSchema = {
    type: Type.OBJECT,
    properties: {
      scriptLine: { type: Type.STRING, description: "The exact script text provided." },
      narrativeContext: { type: Type.STRING, description: "40-80 words explaining the action and story beat." },
      visualPrompt: { type: Type.STRING, description: "MAXIMUM 100 WORDS. High density, precision only." }
    },
    required: ["scriptLine", "narrativeContext", "visualPrompt"]
  };

  // --- NEW "SAFE" JSON TEMPLATE (Prompt First to Prevent Text Bleed) ---
  const detailedJsonSchema = {
    type: Type.OBJECT,
    properties: {
      visual_prompt: { type: Type.STRING, description: "The prompt MUST be the first key. MAX 100 WORDS." },
      meta_data_DO_NOT_RENDER: {
        type: Type.OBJECT,
        properties: {
          scene_id: { type: Type.INTEGER },
          duration: { type: Type.STRING },
          script_source: { type: Type.STRING }
        }
      },
      technical_settings: {
          type: Type.OBJECT,
          properties: {
              camera: {
                  type: Type.OBJECT,
                  properties: {
                      type: { type: Type.STRING },
                      action: { type: Type.STRING }
                  }
              },
              lighting: {
                  type: Type.OBJECT,
                  properties: {
                      setup: { type: Type.STRING },
                      palette: { type: Type.STRING }
                  }
              }
          }
      },
      audio_instruction: {
          type: Type.OBJECT,
          properties: {
              music: { type: Type.STRING },
              sfx: { type: Type.STRING }
          }
      },
      safety_rules: {
          type: Type.OBJECT,
          properties: {
              negative_prompt: { type: Type.STRING }
          }
      }
    },
    required: ["visual_prompt", "meta_data_DO_NOT_RENDER", "technical_settings", "audio_instruction", "safety_rules"]
  };

  const isJsonMode = outputFormat === 'json';

  const systemInstruction = `You are an elite Video Prompt Engineer for Google Veo 3.1.

  MODE: ${isJsonMode ? "SAFE PRODUCTION JSON" : "STANDARD NARRATIVE"}

  >>> LENGTH CONSTRAINT (CRITICAL): MAXIMUM 100 WORDS <<<
  Every video prompt MUST be under 100 words.
  - Do not be verbose. Be dense and precise.
  - Remove filler words. Focus on subject, action, style, and motion.

  >>> STYLE CHAMELEON LOGIC (DYNAMIC AESTHETIC MAPPING) <<<
  Analyze the User's "Visual Aesthetic" setting (${settings.visualStyle}) and apply the matching rule set:

  RULESET A: REALISM / PAINTING / MATTE (Triggers: "Realism", "Oil", "Matte", "Cinematic", "Vintage", "Documentary")
  - Action: Apply "High-Texture" rules.
  - Keywords to Inject: "Cinematic historical realism, thick oil textures, volumetric smoke, hazy atmospheric depth, 8k masterpiece."
  - Forbidden: "Cartoon", "Vector", "Low poly".

  RULESET B: CARTOON / 3D / ANIME (Triggers: "Cartoon", "Anime", "3D", "Flat", "Disney", "Pixar", "Low Poly")
